# ---------------------------------------------------------------------------
# Autocompleter — activates on '/', shows descriptions as meta
# ---------------------------------------------------------------------------
if _HAS_PT:
    class _CogniaCompleter(Completer):
        def get_completions(self, document, complete_event):
            text = document.text_before_cursor
            # @-menciones de ficheros (2026-08-12): '@src/mod' completa rutas
            # reales del proyecto. Es la via universal de los CLI punteros para
            # meter contexto exacto sin copiar y pegar, y funciona en cualquier
            # punto de la linea (tambien dentro de una frase).
            corte = text.rfind("@")
            if corte >= 0 and " " not in text[corte + 1:]:
                prefijo = text[corte + 1:]
                # Bots primero (2026-08-25): '@edi' -> '@editor' con su titulo.
                # Un fallo del registro se ve y no tapa las rutas de abajo.
                # Cacheado (_bots_para_completar): esto corre en CADA tecla.
                try:
                    for _nb, _tb in _bots_para_completar():
                        if _nb.startswith(prefijo.lower()):
                            yield Completion(
                                _nb, start_position=-len(prefijo),
                                display=f"@{_nb}",
                                display_meta=f"bot · {_tb or 'sin titulo'}")
                except Exception as _exc_b:
                    _aviso_degradado("bots.autocompletado",
                                     f"{type(_exc_b).__name__}: {_exc_b}")
                try:
                    from cognia.harness.menciones import completar_rutas
                    for ruta in completar_rutas(prefijo, os.getcwd(), limite=20):
                        yield Completion(ruta, start_position=-len(prefijo),
                                         display=ruta, display_meta="archivo")
                except Exception:
                    pass
                return
            if not text.startswith("/"):
                return
            if text.lower().startswith("/bots "):
                # '/bots cr' -> subcomandos; '/bots chat inv' -> nombres de bot.
                _trozos = text.split(" ")
                _ultimo = _trozos[-1]
                if len(_trozos) == 2:
                    for _sub in _BOTS_SUBCOMANDOS:
                        if _sub.startswith(_ultimo.lower()):
                            yield Completion(_sub, start_position=-len(_ultimo),
                                             display=_sub, display_meta="/bots")
                elif len(_trozos) == 3:
                    # Misma cache que '@' (no relee bot.json por tecla); los
                    # ocultos no se completan pero se pueden teclear.
                    try:
                        for _nb, _tb in _bots_para_completar():
                            if _nb.startswith(_ultimo.lower()):
                                yield Completion(_nb, start_position=-len(_ultimo),
                                                 display=_nb,
                                                 display_meta=_tb or "bot")
                    except Exception as _exc_b:
                        _aviso_degradado("bots.autocompletado",
                                         f"{type(_exc_b).__name__}: {_exc_b}")
                return
            if text.lower().startswith("/flujoteca "):
                # '/flujoteca eje' -> subcomandos; '/flujoteca ejecutar Inf'
                # -> nombres de flujo. Los nombres LLEVAN ESPACIOS ("Informe
                # semanal"), asi que no se completa por token: se completa lo
                # que va DESPUES del subcomando, entero.
                _resto = text[len("/flujoteca "):]
                _trozos = _resto.split(" ", 1)
                if len(_trozos) == 1:
                    for _sub in sorted(_FLUJOTECA_SUBCOMANDOS):
                        if _sub.startswith(_trozos[0].lower()):
                            yield Completion(_sub,
                                             start_position=-len(_trozos[0]),
                                             display=_sub,
                                             display_meta="/flujoteca")
                    return
                _sub, _pref = _trozos[0].lower(), _trozos[1]
                if _sub not in _FLUJOTECA_SUB_CON_NOMBRE:
                    return
                # Cacheado: `flujoteca.listar()` abre un JSON por flujo y esto
                # corre con cada tecla.
                for _nf in _flujoteca_para_completar():
                    if _nf.lower().startswith(_pref.lower()):
                        yield Completion(_nf, start_position=-len(_pref),
                                         display=_nf, display_meta="flujo")
                return
            if " " in text:
                return
            lower = text.lower()
            # _cmds_visibles() y no _CMD_DESCRIPTIONS: el nivel de /avanzado
            # filtra lo que se OFRECE. Corre en cada pulsacion, por eso
            # cli_visibilidad cachea el nivel y no toca disco aqui.
            for cmd, desc in _cmds_visibles().items():
                if cmd.lower().startswith(lower):
                    yield Completion(
                        cmd,
                        start_position=-len(text),
                        display=cmd,
                        display_meta=desc,
                    )

