def _slash_estado(args: str) -> None:
    import threading
    results = {}
    errors = []

    def fetch(name, url):
        try:
            import requests
            r = requests.get(url, timeout=2)
            if r.status_code == 200:
                results[name] = r.json()
        except Exception:
            errors.append(name)

    endpoints = {
        "notas": "http://127.0.0.1:8765/notes/stats",
        "logros": "http://127.0.0.1:8765/achievements/stats",
        "uso": "http://127.0.0.1:8765/analytics/stats",
        "aprendizaje": "http://127.0.0.1:8765/learning/stats",
    }
    threads = [threading.Thread(target=fetch, args=(n, u)) for n, u in endpoints.items()]
    for t in threads:
        t.start()
    for t in threads:
        t.join(timeout=3)

    # Backend LLM local (no depende de la app Desktop): una linea de diagnostico
    # con el motor de inferencia en uso. describir() ya existia sin puerta REPL.
    _backend_line = None
    try:
        from cognia.llm_local import describir as _describir_backend
        _backend_line = _describir_backend()
    except Exception:
        _backend_line = None

    if not results and errors:
        if _backend_line:
            print("Estado de Cognia:")
            print(f"  Backend LLM: {_backend_line}")
            print()
        print("Servicio no disponible. Requiere la app Cognia Desktop corriendo (su API local en 127.0.0.1:8765).")
        return

    print("Estado de Cognia:")
    if _backend_line:
        print(f"  Backend LLM: {_backend_line}")
    if "notas" in results:
        n = results["notas"]
        print(f"  Notas      : {n.get('total',0)} total, {n.get('pinned',0)} fijadas")
    if "logros" in results:
        a = results["logros"]
        print(f"  Logros     : {a.get('unlocked',0)}/{a.get('total',0)} ({a.get('points',0)} pts)")
    if "uso" in results:
        u = results["uso"]
        print(f"  Racha      : {u.get('streak',0)} dia(s) | Hoy: {u.get('today_count',0)} eventos")
    if "aprendizaje" in results:
        l = results["aprendizaje"]
        print(f"  Estudio    : {l.get('total',0)} tarjetas, {l.get('due_today',0)} para revisar")


