def _mcp_activo() -> bool:
    """¿Tiene el agente acceso a los MCP? UN solo lector, como el de TX.

    El env manda y la config persistida es el respaldo: es el mismo contrato
    que `cognia/tx/flag.py`, escrito alli tras medir que dos lectores del mismo
    flag que no coinciden dejan el REPL diciendo ACTIVO con el registry vacio.
    `cognia.agent.tools._mcp_encendido` lee exactamente lo mismo.
    """
    crudo = os.environ.get("COGNIA_MCP", "").strip().lower()
    if crudo:
        return crudo in ("1", "on", "true", "yes", "si")
    try:
        return bool(_load_config().get("mcp_activo", False))
    except Exception:
        return False


def _mcp_cliente_de(nombre: str):
    """El cliente del servidor `nombre`, venga de donde venga.

    Se mira PRIMERO lo que el dueno ya tiene configurado en sus otros clientes
    de IA y despues la lista de servidores libres. Ese orden importa: `context7`
    esta en las dos, y el que el dueno configuro a mano es el que quiere usar.
    """
    from cognia.mcp_externos import cliente_de, descubrir
    for s in descubrir():
        if s.nombre == nombre:
            return cliente_de(s), s.origen
    from cognia.mcp_libre import SERVIDORES_LIBRES, cliente
    if nombre in SERVIDORES_LIBRES:
        return cliente(nombre), "libres"
    return None, ""


def _slash_mcp(arg: str) -> str:
    """
    /mcp                          — servidores MCP disponibles
    /mcp herramientas <servidor>  — que sabe hacer
    /mcp probar <servidor>        — conectarse ahora mismo
    /mcp on | off                 — dar (o quitar) al agente acceso a los MCP

    Dos fuentes, y se ven las dos:
      * los que YA tienes configurados en otros clientes de IA (Claude Code,
        Claude Desktop, Cursor, Windsurf, VS Code) — incluido el de Roblox
        Studio. No hay que copiar nada: se leen de sus propios ficheros.
      * los servidores libres sin registro ni clave de cognia/mcp_libre.py.

    `/mcp on` enciende COGNIA_MCP: el agente gana DOS herramientas
    (`mcp_herramientas` y `mcp`) con las que alcanza las de todos los
    servidores. Dos y no doscientas a proposito: el A/B de este repo midio que
    un catalogo de 46 herramientas baja el camino feliz de 4,25/5 a 2,5/5, y
    solo estos cinco servidores suman 186.
    """
    from cognia.mcp_libre import ErrorMCP, formatear_servidores

    partes = arg.split()
    if not partes:
        try:
            from cognia.mcp_externos import descubrir, formatear_descubiertos
            externos = formatear_descubiertos(descubrir())
        except Exception as exc:
            _aviso_degradado("cli.mcp.descubrir", f"{type(exc).__name__}: {exc}")
            externos = f"(no se pudieron leer las configs de otros clientes: {exc})"
        estado = "ACTIVO" if _mcp_activo() else "apagado"
        return (externos + "\n\n" + formatear_servidores()
                + f"\n\n  Acceso del agente: {estado}   (/mcp on | /mcp off)")

    accion = partes[0].lower()
    nombre = partes[1] if len(partes) > 1 else ""

    if accion in ("on", "off"):
        encender = accion == "on"
        cfg = _load_config()
        cfg["mcp_activo"] = encender
        _save_config(cfg)
        os.environ["COGNIA_MCP"] = "1" if encender else "0"
        if encender:
            return ("MCP ACTIVO: el agente ya puede usar `mcp_herramientas` y "
                    "`mcp`.\n  Prueba: /hacer con mcp_herramientas Roblox_Studio"
                    "\n  (las tools se registran al arrancar: si el agente aun "
                    "no las ve, reabre el REPL)")
        return "MCP apagado: el agente vuelve a su catalogo de siempre."

    if accion not in ("herramientas", "probar"):
        return ("Uso: /mcp [herramientas|probar] <servidor>\n"
                "     /mcp on | off   — acceso del agente\n"
                "     /mcp            — ver los servidores")
    if not nombre:
        return f"Uso: /mcp {accion} <servidor>"

    c, origen = _mcp_cliente_de(nombre)
    if c is None:
        try:
            from cognia.mcp_externos import descubrir
            hay = sorted(s.nombre for s in descubrir())
        except Exception:
            hay = []
        from cognia.mcp_libre import SERVIDORES_LIBRES
        hay += sorted(SERVIDORES_LIBRES)
        return (f"[MCP] no conozco '{nombre}'. Hay: {', '.join(hay) or '(ninguno)'}")

    try:
        if accion == "probar":
            c.conectar()
            hs = c.listar_herramientas()
            return (f"{nombre} responde.  [{origen}]\n"
                    f"  servidor: {c.servidor.get('name','?')} "
                    f"{c.servidor.get('version','')}\n"
                    f"  herramientas: {len(hs)}")
        hs = c.listar_herramientas()
        return (f"{nombre} — {len(hs)} herramienta(s):  [{origen}]\n"
                + "\n".join(f"  {h.resumen()}" for h in hs))
    except ErrorMCP as exc:
        return f"[MCP] {exc}"
    except Exception as exc:
        _aviso_degradado("cli.mcp." + accion, f"{type(exc).__name__}: {exc}")
        return f"[MCP] {nombre}: {type(exc).__name__}: {exc}"
    finally:
        # Un servidor stdio es un SUBPROCESO: sin esto, cada /mcp probar
        # dejaria uno vivo hasta cerrar el REPL.
        try:
            c.cerrar()
        except Exception:
            pass


def _slash_mapa_codigo(arg: str) -> str:
    """
    /mapa-codigo [ruta]           — clases y funciones del proyecto, con su linea
    /mapa-codigo buscar <termino> — donde esta definido algo

    Existe para no gastar la ventana de contexto leyendo ficheros enteros
    cuando lo que hace falta es saber donde mirar.

    OJO con el nombre: /mapa ya estaba cogido por el mapa mental del KG
    (_slash_mapa, linea ~2426). Llamar igual a los dos hacia que la segunda
    definicion sombreara a la primera en silencio.
    """
    from cognia.mapa_proyecto import (buscar, dependencias, mapear, quien_usa,
                                      resumen)

    partes = arg.split()

    if partes and partes[0] == "depende":
        mapa = mapear(".")
        deps = dependencias(mapa)
        if not deps:
            return "No hay dependencias internas entre los ficheros."
        return ("Dependencias internas:\n"
                + "\n".join(f"  {f} -> {', '.join(d)}"
                            for f, d in sorted(deps.items())[:40]))

    if partes and partes[0] == "usan":
        modulo = " ".join(partes[1:]).strip()
        if not modulo:
            return "Uso: /mapa-codigo usan <modulo>"
        hits = quien_usa(mapear("."), modulo)
        if not hits:
            return f"Nadie importa '{modulo}'."
        return (f"{len(hits)} fichero(s) importan '{modulo}':\n"
                + "\n".join(f"  {h}" for h in hits[:40]))

    if partes and partes[0] == "buscar":
        termino = " ".join(partes[1:]).strip()
        if not termino:
            return "Uso: /mapa buscar <termino>"
        hits = buscar(mapear("."), termino)
        if not hits:
            return f"No hay ningun simbolo que contenga '{termino}'."
        return f"{len(hits)} coincidencia(s):\n" + "\n".join(f"  {h}" for h in hits[:40])

    ruta = partes[0] if partes else "."
    mapa = mapear(ruta)
    if not mapa:
        return f"No hay ficheros Python en '{ruta}'."

    n_clases = sum(len(f.clases) for f in mapa.values())
    n_funcs  = sum(len(f.funciones) for f in mapa.values())
    return (f"{len(mapa)} ficheros | {n_clases} clases | {n_funcs} funciones\n\n"
            + resumen(mapa))


def _slash_imagenes(arg: str) -> str:
    """
    /imagenes borrar input|output|todo|<n>

    Las input images son temporales por definicion: son la evidencia que
    Cognia miro para validarse. Se pueden tirar sin perder nada del trabajo.
    """
    from cognia.program_creator.vista_navegador import (
        borrar_imagenes, listar_imagenes, _humano)

    partes = arg.split()
    if not partes or partes[0] != "borrar":
        return ("Uso: /imagenes borrar input|output|todo|<n>\n"
                "     /imagenes            — ver que hay")

    que = partes[1] if len(partes) > 1 else ""

    if que in ("input", "output", "todo"):
        n, b = borrar_imagenes(solo=que)
        if not n:
            return f"No habia imagenes de tipo '{que}'."
        return f"Borradas {n} imagenes ({_humano(b)} liberados) — {que}."

    if que.isdigit():
        lotes = listar_imagenes()
        i = int(que)
        if not (1 <= i <= len(lotes)):
            return f"No hay programa {i}. Hay {len(lotes)} en la lista."
        lote = lotes[i - 1]
        n, b = borrar_imagenes(programa=lote.programa, solo="todo")
        return (f"Borradas {n} imagenes de '{lote.programa}' "
                f"({_humano(b)} liberados).")

    return ("Uso: /imagenes borrar input|output|todo|<n>\n"
            "     'input' son las temporales de validacion.")


def _slash_aprende_repo(ai, target: str) -> str:
    """Fetch a GitHub repo or search query and ingest into semantic memory."""
    import re as _re_ar
    try:
        from cognia.research_engine.github_scraper import GitHubScraper
    except ImportError:
        return "GitHubScraper no disponible."

    scraper = GitHubScraper()
    repos = []

    _url_pat = _re_ar.match(r'https?://github\.com/([^/]+/[^/\s?#]+)', target)
    if _url_pat:
        repo_path = _url_pat.group(1).rstrip('/')
        # Search by repo name as fallback since there's no direct fetch-by-name
        repos = scraper.search_repos(repo_path)
        if not repos:
            repos = scraper.search_repos(repo_path.split('/')[-1])
    else:
        repos = scraper.search_repos(target)

    if not repos:
        return f"No se encontraron repos para: {target}"

    stored = 0
    names = []
    for repo in repos:
        try:
            text = repo.to_learning_text()
            ai.observe(text[:600], provided_label=repo.label())
            stored += 1
            names.append(repo.repo_name)
        except Exception:
            pass

    if stored:
        return f"Aprendido de {stored} repo(s): {', '.join(names)}"
    return "No se pudo almacenar informacion de los repos."


