def _slash_tema(arg: str = ""):
    """`/tema` cicla; `/tema <nombre>` fija uno de: oscuro, claro, alto_contraste. Persiste."""
    global _theme_idx
    arg = (arg or "").strip().lower()
    if arg and arg in _THEMES:
        _theme_idx = _THEME_ORDER.index(arg)
    elif arg:
        _print_line(f"[warn_cl]Tema desconocido '{_escape(arg)}'. "
                    f"Opciones: {', '.join(_THEME_ORDER)}[/warn_cl]")
        return
    else:
        # /tema sin argumento: selector con flechas si hay tty; sin tty se
        # conserva el ciclado historico (un pipe no debe consumir stdin con
        # un menu). REGLA: no hay Live/status activo aca (comando directo).
        from cognia.ux import selector as _selector
        if _selector.hay_tty():
            _descr = paleta.DESCRIPCION_VARIANTES
            _sel = _selector.elegir(
                "Tema del CLI:",
                [(n, n, _descr.get(n, "")) for n in _THEME_ORDER],
                default=_theme_idx)
            if _sel is None:
                return  # Esc/Ctrl-C: no tocar nada
            _theme_idx = _THEME_ORDER.index(_sel)
        else:
            _theme_idx = (_theme_idx + 1) % len(_THEME_ORDER)
    name = _THEME_ORDER[_theme_idx]
    # Console + renderer + prompt, compartido con /estilo (2026-08-24): el
    # Theme sale de aspecto.tema_rich(name), que sin fichero de estilo es
    # paleta.tema_cli(name) tal cual.
    _aplicar_tema_en_caliente()
    if _HAS_RICH:
        _console.rule(f"[info_dim]Tema: {name} (guardado)[/info_dim]",
                      characters=_aspecto.glifo("separador.regla") or "\u2500")
    else:
        print(f"Tema: {name} (Rich no disponible)")
    _persist_setting("COGNIA_THEME", name)


def _vram_gpu() -> tuple:
    """(usada_mib, total_mib) de la GPU, o (0, 0) si no hay nvidia-smi."""
    try:
        import subprocess as _sp
        out = _sp.run(["nvidia-smi",
                       "--query-gpu=memory.used,memory.total",
                       "--format=csv,noheader,nounits"],
                      capture_output=True, text=True, timeout=10).stdout
        usada, total = out.strip().splitlines()[0].split(",")
        return int(usada), int(total)
    except Exception:
        return 0, 0


def _slash_vram(args: str = "") -> None:
    """Que cabe en TU GPU ahora mismo, y por que no cabe lo que no cabe.

    POR QUE EXISTE (2026-08-18): los harnesses de codigo asumen un modelo
    remoto e infinito, asi que ninguno tiene esta pantalla. Aqui el limite es
    fisico y se paga en cada decision: que modelo sirve, con cuanta ventana, y
    si cabe ademas el VLM. Cognia ya tenia el summoner con la VRAM MEDIDA por
    rol y una escalera de contexto con celdas medidas -- lo que faltaba era
    poder verlo. `grep summoner cognia/cli.py` daba CERO.
    """
    usada, total = _vram_gpu()
    if total:
        libre = total - usada
        _print_line(f"[mod]VRAM[/mod]  {usada:,} de {total:,} MiB usados  "
                    f"[info_dim]({libre:,} libres)[/info_dim]")
    else:
        _print_line("[warn_cl]sin nvidia-smi: no puedo leer la VRAM real[/warn_cl]")
    try:
        from cognia import summoner as _sm
    except Exception as exc:
        _print_line(f"[err_cl]summoner no disponible: {_escape(str(exc))}[/err_cl]")
        return

    try:
        vivos = _sm.vivos() or {}
    except Exception:
        vivos = {}
    try:
        _ancho = _console.size.width if (_HAS_RICH and _console) else 100
    except Exception:
        _ancho = 100
    _sitio_nota = max(16, _ancho - 40)   # 40 = rol + estado + vram + puerto
    _print_line("")
    # "presupuesto" y no "VRAM": la columna sale de ROLES[rol]['vram_mib'], que
    # es lo que el summoner RESERVA para decidir si cabe -- no lo que ese rol
    # esta gastando ahora. Llamarlo VRAM invitaba a leer un consumo medido
    # donde hay una declaracion.
    _print_line(f"  [info_dim]{'rol':<9} {'estado':<9} {'presup.':>8}  "
                f"{'puerto':<7} que pasa[/info_dim]")
    for rol, cfg in _sm.ROLES.items():
        vram = cfg.get("vram_mib") or 0
        puerto = cfg.get("puerto") or 0
        # "vivo" para el summoner es "lo lance yo". Pero el usuario ve la
        # VRAM ocupada, y un server que arranco a mano (o la flota) ocupa
        # igual: preguntarle al PUERTO evita el mensaje absurdo de "no cabe"
        # junto a un modelo que esta sirviendo ahi mismo.
        propio = rol in vivos
        ajeno = False
        if not propio and puerto:
            try:
                ajeno = bool(_sm._salud(int(puerto), timeout=1.0)[0] == 200)
            except Exception:
                ajeno = False
        if propio or ajeno:
            texto_estado = "vivo" if propio else "ocupado"
            color = "ok_cl" if propio else "warn_cl"
            nota = cfg.get("identidad", "") if propio else "hay algo sirviendo en ese puerto"
        else:
            texto_estado, color = "-", "info_dim"
            try:
                entra, motivo = _sm.cabe(rol)
            except Exception as exc:
                entra, motivo = False, f"no pude comprobarlo: {exc}"
            nota = "cabe" if entra else (motivo or "no cabe")
        # El padding se calcula sobre el TEXTO, no sobre el markup: si se
        # aplica a la cadena con etiquetas, rich las cuenta como caracteres y
        # la columna se descuadra (que es justo lo que pasaba).
        hueco = " " * max(0, 9 - len(texto_estado))
        nota = str(nota)
        if len(nota) > _sitio_nota:
            nota = nota[:_sitio_nota - 1].rstrip() + "…"
        _print_line(f"  [mod]{rol:<9}[/mod] [{color}]{texto_estado}[/{color}]{hueco} "
                    f"{vram:>8,}  :{str(puerto):<6} {_escape(nota)}")

    # La escalera de contexto: celdas MEDIDAS en esta maquina, no estimadas.
    _print_line("")
    _print_line("  [info_dim]ventana del cerebro — celdas MEDIDAS en esta "
                "maquina[/info_dim]")
    for celda in getattr(_sm, "ESCALERA_CTX", []):
        v = celda.get("vram_mib")
        _print_line(f"    [mod]{celda['n_ctx']:>9,}[/mod] "
                    f"[info_dim]{celda.get('cache','f16'):<5}[/info_dim] "
                    f"{(f'{v:,} MiB' if v else '—'):>11}  "
                    f"[info_dim]{_escape(str(celda.get('medida',''))[:34])}[/info_dim]")


def _slash_capacidades(args: str = "") -> None:
    """Que sabe hacer el agente, que esta encendido y que lo enciende.

    POR QUE EXISTE (2026-08-18): de las ~111 herramientas registrables solo se
    anuncian 13; el resto vive detras de nueve variables de entorno que ningun
    comando encendia. El recorte esta MEDIDO y es correcto (un catalogo de 46
    tools baja el camino feliz de 4,25/5 a 2,5/5), pero no habia forma de
    deshacerlo desde dentro: habia que saber el nombre del flag y exportarlo
    antes de arrancar. Subsistemas enteros verificados en GPU -- imagenes,
    musica, 3D, escena -- eran inalcanzables en la practica.
    """
    try:
        from cognia.harness import familias as _fam
    except Exception as exc:
        _print_line(f"[err_cl]no pude leer las capacidades: {_escape(str(exc))}[/err_cl]")
        return
    filas = _fam.estado()
    detalle = (args or "").strip().lower()
    if detalle and detalle in _fam.FAMILIAS:
        f = next(x for x in filas if x["familia"] == detalle)
        _print_line(f"[mod]{f['familia']}[/mod] — {_escape(f['que'])}")
        _print_line(f"  enciende con [info_dim]/activar {f['familia']}[/info_dim] "
                    f"(flag {f['flag']})")
        if f["tools"]:
            for t in f["tools"]:
                _print_line(f"    [info_dim]{_escape(t)}[/info_dim]")
        else:
            _print_line("    [info_dim](sin cargar todavia)[/info_dim]")
        return

    encendidas = [f for f in filas if f["encendida"]]
    _print_line(f"[mod]Capacidades[/mod]  "
                f"{len(encendidas)} de {len(filas)} familias encendidas")
    _print_line("")
    # El ancho REAL de la terminal, no uno inventado: una descripcion que se
    # envuelve rompe la alineacion de la tabla y la vuelve ilegible justo en
    # las pantallas estrechas, que es donde mas falta hace que se entienda.
    try:
        _ancho = _console.size.width if (_HAS_RICH and _console) else 100
    except Exception:
        _ancho = 100
    _sitio = max(20, _ancho - 42)      # 42 = marca + familia + estado + aire
    for f in filas:
        if not f["instalada"]:
            marca, estado = "[err_cl]x[/err_cl]", "no instalada"
        elif f["encendida"] and f["n_tools"]:
            marca, estado = "[ok_cl]*[/ok_cl]", f"{f['n_tools']} tools"
        elif f["encendida"]:
            # Flag puesto y CERO tools en el registro: decir "encendida" seria
            # exactamente la mentira que este comando existe para deshacer.
            marca, estado = "[warn_cl]![/warn_cl]", "ON, 0 tools"
        else:
            marca, estado = "[info_dim]-[/info_dim]", "apagada"
        peligro = " (toca tu maquina)" if f["peligrosa"] else ""
        texto = f["que"] + peligro
        if len(texto) > _sitio:
            texto = texto[:_sitio - 1].rstrip() + "…"
        _print_line(f"  {marca} [mod]{f['familia']:<18}[/mod] "
                    f"[info_dim]{estado:<12}[/info_dim] {_escape(texto)}")
    _print_line("")
    _print_line("  [info_dim]/activar <familia>[/info_dim] la enciende sin reiniciar   "
                "[info_dim]/capacidades <familia>[/info_dim] lista sus herramientas")


def _slash_activar(args: str = "") -> None:
    """Enciende una familia de herramientas EN CALIENTE (sin reiniciar)."""
    nombre = (args or "").strip().lower()
    try:
        from cognia.harness import familias as _fam
    except Exception as exc:
        _print_line(f"[err_cl]no pude activar: {_escape(str(exc))}[/err_cl]")
        return
    if not nombre:
        _print_line("Uso: [info_dim]/activar <familia>[/info_dim]  — familias: "
                    + ", ".join(sorted(_fam.FAMILIAS)))
        return
    if nombre in ("todo", "todas"):
        # A proposito NO se ofrece como camino comodo en la ayuda: encender las
        # 14 familias mete ~100 tools en el catalogo y el A/B del repo midio que
        # eso DEGRADA al modelo. Existe para pruebas, y se avisa.
        _print_line("[warn_cl]encender todo mete ~100 herramientas en el "
                    "catalogo, y el A/B del repo midio que un catalogo grande "
                    "degrada al agente (4,25/5 -> 2,5/5). Activa solo lo que "
                    "necesites.[/warn_cl]")
        return
    r = _fam.activar(nombre)
    if not r["ok"]:
        _print_line(f"[err_cl]{_escape(r['detalle'])}[/err_cl]")
        return
    _print_line(f"[ok_cl]{r['familia']}[/ok_cl] encendida — {_escape(r['detalle'])}")
    for t in (r.get("nuevas") or [])[:12]:
        _print_line(f"    [info_dim]{_escape(t)}[/info_dim]")
    if len(r.get("nuevas") or []) > 12:
        _print_line(f"    [info_dim]... y {len(r['nuevas']) - 12} mas[/info_dim]")


def _reestilar_prompt() -> None:
    """Repinta el marco del prompt con la rampa de la variante recien elegida.

    El Style de prompt_toolkit se construye UNA vez al armar la PromptSession
    (en repl()), asi que sin esto '/tema claro' cambiaba todo lo que pasa por
    rich y dejaba el marco, el 'cognia➤' y el texto que se escribe en la lima
    del tema oscuro: 1,96 / 1,53 / 1,19:1 sobre blanco. PromptSession.style es
    reasignable y la Application la lee por DynamicStyle en cada redibujado,
    asi que el cambio se ve en el turno siguiente sin reiniciar nada."""
    if _sesion_prompt is None:
        return
    try:
        _sesion_prompt.style = _estilo_prompt()
    except Exception as exc:
        # el tema ya cambio en rich; el marco no puede tumbar el REPL, pero
        # tampoco callarse (P5: antes era un pass mudo)
        _aviso_degradado("estilo", f"el marco del prompt no se repinto: "
                                   f"{type(exc).__name__}: {exc}")
    _MEMO_FRAG.clear()


def _slash_color(arg: str = ""):
    """`/color <nombre>` fija el color de acento de las respuestas (ej: cyan, magenta, #ff8800). Persiste."""
    global _ACCENT
    color = (arg or "").strip()
    if not color:
        _print_line(f"[detail]Color de acento actual: {_ACCENT}. "
                    "Uso: /color <nombre|#hex> (ej: normal, cyan, magenta, "
                    "green, #ff8800)[/detail]")
        return
    # 'normal' vuelve al defecto de la decision 17 (texto de la terminal). Es
    # un TOKEN del tema, no un color: Style.parse no lo sabe leer, asi que la
    # validacion de abajo se saltea para los tokens conocidos.
    if color.lower() in {"normal", "texto", "defecto", "default"}:
        color = _DEFAULT_ACCENT
    # Validate via rich.Style; reject anything rich can't parse so we never break output.
    if _HAS_RICH and color not in paleta.TOKENS_CLI:
        try:
            from rich.style import Style as _RStyle
            _RStyle.parse(color)
        except Exception:
            _print_line(f"[warn_cl]Color invalido '{_escape(color)}'. "
                        "Proba: cyan, magenta, green, yellow, blue, red, o #rrggbb[/warn_cl]")
            return
    _ACCENT = color
    _persist_setting("COGNIA_ACCENT", color)
    _acento_a_registro(color)
    if _HAS_RICH and _console:
        _console.print(f"Color de acento: {color} (guardado)", style=color)
    else:
        print(f"Color de acento: {color} (guardado)")


def _acento_a_registro(color: str) -> None:
    """/color X tambien escribe respuesta.texto.color en el registro
    (aspecto.poner + guardar), para que '/estilo ver respuesta.texto' diga
    el origen y el editor lo vea. El acento por defecto ('respuesta', la
    decision 17) vuelve el elemento a su default (@token.respuesta), que
    guardar() no escribe. Un color que el registro rechaza se avisa y el
    acento queda igual que antes de esta sincronizacion (COGNIA_ACCENT)."""
    valor = "@token.respuesta" if color == _DEFAULT_ACCENT else color
    try:
        avisos = _aspecto.poner("respuesta.texto", "color", valor)
    except Exception as exc:
        _aviso_degradado("estilo", f"respuesta.texto.color: {type(exc).__name__}: {exc}")
        return
    if _estilo_avisos(avisos):
        return
    _estilo_guardar_y_aplicar()


def _acento_desde_registro(forzar: bool = False) -> None:
    """El camino inverso: respuesta.texto.color del registro -> _ACCENT y
    COGNIA_ACCENT en caliente (lo que hace /color X). Con el elemento en su
    default solo se toca si `forzar` (un /estilo reset explicito): al
    arrancar, un COGNIA_ACCENT guardado sin estilo.json NO se pisa."""
    global _ACCENT
    try:
        if _aspecto.origen("respuesta.texto", "color") == "default":
            if not forzar:
                return
            color = _DEFAULT_ACCENT
        else:
            color = _aspecto._estilo_rich_de(
                _aspecto.estilo_resuelto("respuesta.texto", _variante_actual())) or _DEFAULT_ACCENT
    except Exception as exc:
        _aviso_degradado("estilo", f"acento desde respuesta.texto: {type(exc).__name__}: {exc}")
        return
    if color == _ACCENT:
        return
    _ACCENT = color
    _persist_setting("COGNIA_ACCENT", color)


# ---------------------------------------------------------------------------
# /estilo: estilos por elemento (2026-08-24, paso P4 del sistema de estilos)
# ---------------------------------------------------------------------------
# Registro y fichero: cognia/ux/aspecto.py (~/.cognia/estilo.json, presets).
# Motor de glow/barrido: cognia/ux/glow.py. Aqui vive la puerta slash, la
# aplicacion EN CALIENTE (compartida con /tema) y la recarga por mtime (E6:
# el toolbar solo marca; se recarga en el bucle del REPL, nunca dentro del
# render de prompt_toolkit). El editor interactivo es el paso P11.
_ESTILO_USO = ("Uso: /estilo lista [grupo] | ver [<id>] | <id> <prop> <valor> | "
               "<id> \"<style string>\" | reset [<id>|todo] | animacion on|off|estado | "
               "guardar <preset> | cargar <preset|ruta> | presets | exportar <ruta> | "
               "deshacer | ayuda")
_ESTILO_SUBCOMANDOS = ("lista", "ver", "reset", "animacion", "guardar", "cargar",
                       "presets", "exportar", "deshacer", "ayuda")


def _tema_de(nombre: str):
    """Theme de rich de la variante CON los overrides de /estilo
    (aspecto.tema_rich). Sin fichero de estilo es paleta.tema_cli(nombre)
    tal cual: byte-identico al tema precalculado en _THEMES."""
    try:
        return Theme(_aspecto.tema_rich(nombre))
    except Exception as exc:
        _aviso_degradado("estilo", f"tema_rich({nombre}) fallo: "
                                   f"{type(exc).__name__}: {exc}; uso el tema base")
        return _THEMES[nombre]


def _aplicar_tema_en_caliente() -> None:
    """Reconstruye lo que PINTA con la variante activa + los overrides de
    /estilo: la Console de rich, la referencia del renderer del bus y el
    Style del prompt. La comparten /tema, /estilo y la recarga por mtime.
    Extraida de _slash_tema (2026-08-24): antes /tema hacia esto inline."""
    global _console
    nombre = _variante_actual()
    if _HAS_RICH:
        _console = Console(theme=_tema_de(nombre), highlight=False)
        # El renderer del bus de eventos guarda SU PROPIA referencia a la
        # Console: sin re-activarlo, /tema repintaba el banner y dejaba el
        # spinner, las tools y los avisos con la rampa VIEJA el resto de la
        # sesion. activar() ya soporta el reemplazo en caliente (2026-08-18).
        try:
            from cognia.ux import renderer as _ux_renderer
            _ux_renderer.activar(console=_console)
        except Exception as _exc:
            _aviso_degradado("cli.tema.renderer",
                             f"el tema no llego al renderer: {_exc}")
    _reestilar_prompt()
    _acento_desde_registro()
    # El motor memoiza frames por version del registro y lee global.fps del
    # fichero: reconectar vacia la memo y refresca el fps.
    try:
        _aspecto.conectar_glow(_load_config)
    except Exception as exc:
        _aviso_degradado("estilo", f"motor de glow no conectado: "
                                   f"{type(exc).__name__}: {exc}")


def _estilo_avisos(avisos, prefijo: str = "") -> bool:
    """Enruta los Aviso de aspecto: nivel 'error' por _aviso_degradado
    ('estilo', ...) y nivel 'aviso' en ambar. True si hubo algun error."""
    hubo = False
    for a in avisos or ():
        texto = f"{a.id}: {a.texto}" if getattr(a, "id", "") else a.texto
        if prefijo:
            texto = f"{prefijo}: {texto}"
        if a.nivel == "error":
            hubo = True
            _aviso_degradado("estilo", texto)
        else:
            _print_line(f"[warn_cl]{_escape(texto)}[/warn_cl]")
    return hubo


def _aplicar_config_estilo() -> None:
    """Arranque del REPL: conecta el motor de glow al registro y carga
    ~/.cognia/estilo.json con validacion RUIDOSA (un fichero roto avisa por
    degradado 'estilo' y se arranca con el aspecto por defecto: nunca sin
    prompt). Si el fichero trae overrides, reconstruye la Console ANTES del
    banner para que el Theme retenido pinte desde la primera linea."""
    try:
        _aspecto.conectar_glow(_load_config)
    except Exception as exc:
        _aviso_degradado("estilo", f"motor de glow no conectado: "
                                   f"{type(exc).__name__}: {exc}")
    try:
        doc = _aspecto.cargar()
    except _aspecto.EstiloInvalido as exc:
        _aviso_degradado("estilo", f"{exc}; arranco con el aspecto por defecto")
        return
    except Exception as exc:
        _aviso_degradado("estilo", f"no pude leer {_aspecto.RUTA_ESTILO}: "
                                   f"{type(exc).__name__}: {exc}; aspecto por defecto")
        return
    _estilo_avisos(_aspecto.ultimos_avisos())
    if doc:
        _aplicar_tema_en_caliente()


def _aplicar_recarga_estilo() -> None:
    """E6: _pie_prompt solo hace un stat y MARCA la recarga pendiente; aqui,
    con el prompt ya devuelto y antes de despachar la linea, se recarga de
    verdad (Console + renderer + prompt). Un fichero editado a mano con un
    error avisa y se sigue con el estilo anterior (no se reintenta hasta que
    el mtime vuelva a cambiar: aspecto.aplicar_recarga)."""
    try:
        if not _aspecto.recarga_pendiente():
            return
    except Exception as exc:
        _aviso_degradado("estilo", f"recarga_pendiente fallo: {exc}")
        return
    try:
        _aspecto.aplicar_recarga()
    except _aspecto.EstiloInvalido as exc:
        _aviso_degradado("estilo", f"{exc}; sigo con el estilo anterior")
        return
    except Exception as exc:
        _aviso_degradado("estilo", f"recarga fallo: {type(exc).__name__}: {exc}")
        return
    _estilo_avisos(_aspecto.ultimos_avisos())
    _aplicar_tema_en_caliente()
    _print_line(f"[info_dim]estilo: recargado de {_escape(str(_aspecto.RUTA_ESTILO))}"
                "[/info_dim]")


def _estilo_guardar_y_aplicar() -> bool:
    """Persiste (aspecto.guardar hace el .bak) y aplica en caliente."""
    try:
        _aspecto.guardar()
    except Exception as exc:
        _aviso_degradado("estilo", f"no pude guardar {_aspecto.RUTA_ESTILO}: "
                                   f"{type(exc).__name__}: {exc}")
        return False
    _aplicar_tema_en_caliente()
    return True


def _estilo_sin_efecto(props) -> str:
    """'1 propiedad aun sin efecto en esta version (barra.modo.glow)' /
    '3 propiedades aun sin efecto en esta version (a, b, c)'. Es el UNICO
    texto que ve el dueno por lo que se guarda y todavia no se pinta: los
    nombres de paso del plan (P6, P9...) son jerga del desarrollo y salian
    en 'lista', 'ver', 'cargar' y en cada set (cazado 2026-08-24 tecleando
    '/estilo cargar neon': "barra.modo.glow (P9)" no le dice nada a nadie)."""
    props = sorted(set(props))
    n = len(props)
    return (f"{n} propiedad{'es' if n != 1 else ''} aun sin efecto en esta version "
            f"({', '.join(props)})")


def _estilo_aviso_enganche(id: str, props) -> str:
    """E8: '' si el cambio ya se ve; si no, el aviso de que se guardo y aun
    no se pinta. Los ENGANCHADOS_P4 cambian color/negrita/italica por el
    Theme de rich; texto, glifo, glow, animacion... esperan a su enganche."""
    e = _aspecto.elemento(id)
    if not e.enganchado:
        return (f"guardado; {_estilo_sin_efecto(f'{id}.{p}' for p in props)}: "
                f"el elemento {id} aun no se pinta desde el estilo")
    # aspecto.paso_pendiente sabe que le falta a cada elemento enganchado
    # (la animacion de la barra, los glifos y textos por token)
    pendientes = [p for p in props if _aspecto.paso_pendiente(id, p)]
    if pendientes:
        return (f"guardado; {_estilo_sin_efecto(f'{id}.{p}' for p in pendientes)}; "
                f"color/negrita/italica ya cambian")
    return ""


def _estilo_id(id: str):
    """El Elemento o None (con el aviso ruidoso de ids parecidos ya emitido)."""
    try:
        return _aspecto.elemento(id)
    except KeyError as exc:
        _aviso_degradado("estilo", str(exc).strip('"'))
        return None


def _estilo_poner(id: str, prop: str, valor: str) -> None:
    if _estilo_id(id) is None:
        return
    try:
        avisos = _aspecto.poner(id, prop, valor)
    except Exception as exc:
        _aviso_degradado("estilo", f"{id}.{prop}: {type(exc).__name__}: {exc}")
        return
    if _estilo_avisos(avisos):
        return
    if not _estilo_guardar_y_aplicar():
        return
    if id == "respuesta.texto":
        _acento_desde_registro(forzar=True)
    _print_line(f"[ok_cl]{_escape(id)}.{_escape(prop)} = {_escape(valor)} (guardado)[/ok_cl]")
    aviso = _estilo_aviso_enganche(id, [prop])
    if aviso:
        _print_line(f"[warn_cl]{aviso}[/warn_cl]")


def _estilo_poner_string(id: str, s: str) -> None:
    if _estilo_id(id) is None:
        return
    try:
        estilo = _aspecto.parsear_style_string(s)
        avisos = _aspecto.poner_style_string(id, s)
    except Exception as exc:
        _aviso_degradado("estilo", f"{id}: style string invalido: {exc}")
        return
    if _estilo_avisos(avisos):
        return
    if not _estilo_guardar_y_aplicar():
        return
    import dataclasses as _dc
    props = [f.name for f in _dc.fields(estilo)
             if getattr(estilo, f.name) not in (None, {})]
    if id == "respuesta.texto":
        _acento_desde_registro(forzar=True)
    _print_line(f"[ok_cl]{_escape(id)} = {_escape(s)} (guardado)[/ok_cl]")
    aviso = _estilo_aviso_enganche(id, props)
    if aviso:
        _print_line(f"[warn_cl]{aviso}[/warn_cl]")


def _estilo_lista(grupo: str = "") -> None:
    grupos = [(g, ids) for g, ids in _aspecto.GRUPOS if not grupo or g == grupo]
    if not grupos:
        _print_line(f"[warn_cl]grupo desconocido '{_escape(grupo)}'; hay: "
                    f"{', '.join(g for g, _ in _aspecto.GRUPOS)}[/warn_cl]")
        return
    # cabecera en dos lineas de menos de 80 celdas: la leyenda entera en una
    # sola rebasaba las 80 columnas (99 celdas)
    _print_line("[mod]Elementos del aspecto[/mod] [info_dim](/estilo ver <id> da las "
                "propiedades)[/info_dim]")
    _print_line("[info_dim]  * animacion activa · mod difiere del default · sin efecto: "
                "aun no se pinta[/info_dim]")
    # Cada fila cabe en la consola: antes llevaba TODAS las caps del elemento
    # ("texto, color, fondo, negrita, italica, subrayado, glow, animacion,
    # glifo, ...") y a 120 columnas rich partia la fila en dos, con la marca
    # 'mod' huerfana en la segunda. El ancho es el MENOR entre el del marco
    # (columns-1) y el que rich cree tener (en Windows resta 1 por su cuenta),
    # menos 1: tecleado a 120 columnas, una fila de 119 celdas justas rich la
    # partia en "posicion, " / "visib…" aunque en aislado no lo hiciera.
    ancho = _ancho_marco()
    if _HAS_RICH and _console:
        try:
            ancho = min(ancho, int(_console.width))
        except Exception as exc:
            _aviso_degradado("estilo", f"ancho de consola no legible ({exc}); uso {ancho}")
    ancho -= 1
    for g, ids in grupos:
        _print_line(f"[mod]{g}[/mod]")
        for id in ids:
            e = _aspecto.elemento(id)
            caps = ", ".join(c.value for c in _aspecto.Cap if c in e.caps)
            est = _aspecto.estilo_de(id)
            marcas = []
            if est.animacion is not None and est.animacion.activa:
                marcas.append("*")
            if _aspecto.tiene_override(id):
                marcas.append("mod")
            if not e.enganchado:
                marcas.append("sin efecto")
            m_txt = f" {' '.join(marcas)}" if marcas else ""
            # el nombre largo (spinner.pensar trae un ejemplo entre parentesis
            # de 56 celdas) se corta antes que dejar la fila fuera de la consola
            nombre = e.nombre
            cupo_nombre = ancho - 27 - len(m_txt)
            if len(nombre) > cupo_nombre:
                nombre = nombre[:max(0, cupo_nombre - 1)].rstrip() + "\u2026"
            cabeza = f"  {id:<24} {nombre}"
            cupo = ancho - len(cabeza) - len(m_txt) - 2
            if cupo >= 8 and len(caps) > cupo:
                # Se corta en el ULTIMO ', ' que cabe, no a mitad de palabra:
                # a 80 columnas 'agentes.acento' salia 'color, f… sin efecto'
                # (medido tecleando /estilo lista). Si ni la primera cap cabe,
                # se corta por celdas como antes.
                _sep = caps.rfind(", ", 0, cupo)
                caps = (caps[:_sep] if _sep > 0 else caps[:cupo - 1].rstrip(", ")) + "…"
            elif cupo < 8:
                caps = ""
            m = f" [warn_cl]{' '.join(marcas)}[/warn_cl]" if marcas else ""
            _print_line(f"  [ok_cl]{_escape(id):<24}[/ok_cl] {_escape(nombre)}"
                        f"{'  [info_dim]' + _escape(caps) + '[/info_dim]' if caps else ''}{m}")


_ESTILO_CAMPO_DE_CAP = (("texto", "texto"), ("color", "color"), ("fondo", "fondo"),
                        ("negrita", "negrita"), ("italica", "italica"),
                        ("subrayado", "subrayado"), ("glow", "glow"),
                        ("animacion", "animacion"), ("glifo", "glifo"),
                        ("posicion", "posicion"), ("alineacion", "alineacion"),
                        ("visible", "visible"), ("gradiente", "gradiente"),
                        ("separador", "separador"))


def _estilo_ver(id: str = "") -> None:
    if not id:
        ruta = _aspecto.RUTA_ESTILO
        _print_line(f"[mod]Estilo activo[/mod] [info_dim]{_escape(str(ruta))} "
                    f"({'existe' if ruta.exists() else 'sin fichero: defaults'})[/info_dim]")
        glob = _aspecto.global_doc()
        if glob:
            _print_line(f"  [info_dim]global: {_escape(str(glob))}[/info_dim]")
        act, motivo = _aspecto.animacion_global()
        _print_line(f"  [info_dim]animacion global: {'on' if act else 'off'}"
                    f"{' (' + motivo + ')' if motivo else ''}[/info_dim]")
        cambiados = [i for i in _aspecto.REGISTRO if _aspecto.tiene_override(i)]
        if not cambiados:
            _print_line("  [info_dim]ningun elemento difiere del default[/info_dim]")
        for i in cambiados:
            _print_line(f"  [ok_cl]{_escape(i)}[/ok_cl] [info_dim]"
                        f"{_escape(str(_aspecto.cambios(i)))}[/info_dim]")
        return
    e = _estilo_id(id)
    if e is None:
        return
    try:
        r = _aspecto.estilo_resuelto(id)
    except Exception as exc:
        _aviso_degradado("estilo", f"{id}: no resuelve: {type(exc).__name__}: {exc}")
        return
    est = _aspecto.estilo_de(id)
    enganche = "si" if e.enganchado else "no (aun sin efecto en esta version)"
    _print_line(f"[mod]{_escape(id)}[/mod] {_escape(e.nombre)} [info_dim](grupo {e.grupo} · "
                f"vivo {'si' if e.vivo else 'no'} · enganchado {enganche} · variante "
                f"{r.variante})[/info_dim]")
    if e.nota:
        _print_line(f"  [info_dim]{_escape(e.nota)}[/info_dim]")
    for cap, campo in _ESTILO_CAMPO_DE_CAP:
        if _aspecto.Cap(cap) not in e.caps:
            continue
        # EstiloResuelto no tiene 'glow' (lleva glow_color/glow_intensidad):
        # con getattr a secas '/estilo ver prompt.etiqueta' tumbaba el REPL
        # entero con AttributeError (cazado tecleando en P5; P4 solo lo probo
        # con sistema.ok, que no tiene GLOW).
        v = getattr(r, campo, None)
        if campo == "glow":
            v = f"color {r.glow_color} intensidad {r.glow_intensidad}"
        elif campo == "animacion":
            a = r.animacion
            v = (f"{'on' if a.activa else 'off'} {a.tipo} {a.direccion} velocidad {a.velocidad} "
                 f"ancho {a.ancho} repetir {a.repetir} cada_s {a.cada_s}"
                 f"{' solo_al_llegar' if a.solo_al_llegar else ''}")
        elif campo == "glifo":
            v = f"{v!r}" + (f" (ascii {est.glifo_ascii!r})" if est.glifo_ascii else "")
        elif campo == "color" and r.token:
            v = f"{v} (token {r.token})"
        crudo = getattr(est, campo)
        origen = _aspecto.origen(id, campo)
        extra = (f"  [info_dim]<- {_escape(str(crudo))} ({origen})[/info_dim]"
                 if origen != "default" and crudo is not None else
                 f"  [info_dim]({origen})[/info_dim]")
        _print_line(f"  {campo:<11} {_escape(str(v))}{extra}")
    if r.estados:
        _print_line(f"  {'estados':<11} [info_dim]{', '.join(r.estados)} "
                    f"(/estilo {_escape(id)} estados.<nombre>.<prop> <valor>)[/info_dim]")
    try:
        ss = _aspecto.a_style_string(est)
    except Exception as exc:
        ss = f"(no representable: {exc})"
    if ss:
        _print_line(f"  {'style':<11} [info_dim]{_escape(ss)}[/info_dim]")


def _estilo_reset(arg: str) -> None:
    arg = (arg or "").strip()
    if arg in ("", "todo"):
        from cognia.ux import selector as _selector
        if _selector.hay_tty() and not _selector.confirmar(
                "Volver TODOS los elementos al aspecto por defecto?", default=False):
            _print_line("[info_dim]reset cancelado[/info_dim]")
            return
        _aspecto.reset()
        que = "todos los elementos"
    else:
        if _estilo_id(arg) is None:
            return
        _aspecto.reset(arg)
        que = arg
    if _estilo_guardar_y_aplicar():
        if que in ("todos los elementos", "respuesta.texto"):
            _acento_desde_registro(forzar=True)
        _print_line(f"[ok_cl]estilo: {_escape(que)} al default (guardado)[/ok_cl]")


def _estilo_animacion(arg: str) -> None:
    arg = (arg or "").strip().lower()
    if arg in ("on", "off"):
        cfg = _load_config()
        cfg["estilo_animacion"] = arg
        _save_config(cfg)
        env = (os.environ.get("COGNIA_ANIMACION") or "").strip()
        extra = (f" (ojo: COGNIA_ANIMACION={env} en el entorno GANA a la config)"
                 if env else "")
        _print_line(f"[ok_cl]animacion de estilos: {arg} (guardado){extra}[/ok_cl]")
        try:
            from cognia.ux import glow as _glow
            _glow.vaciar_memo()
        except Exception as exc:
            _aviso_degradado("estilo", f"memo del motor no vaciada: {exc}")
        return
    if arg not in ("", "estado"):
        _print_line("[warn_cl]Uso: /estilo animacion on|off|estado[/warn_cl]")
        return
    cfg = _load_config()
    valor = str(cfg.get("estilo_animacion", "on")).strip().lower()
    env = (os.environ.get("COGNIA_ANIMACION") or "").strip()
    origen = ("env COGNIA_ANIMACION" if env
              else "default" if valor == _CONFIG_DEFAULTS.get("estilo_animacion")
              else "config")
    _print_line(f"[info_dim]animacion de estilos: {env or valor} ({origen}; "
                "/estilo animacion on|off para cambiarla)[/info_dim]")
    try:
        from cognia.ux import glow as _glow
        caps = _glow.capacidades()
        _print_line(f"[info_dim]  esta terminal: color {caps.nivel} · animar "
                    f"{'si' if caps.animar else 'no'}"
                    f"{' (' + caps.motivo + ')' if caps.motivo else ''}[/info_dim]")
    except Exception as exc:
        _aviso_degradado("estilo", f"capacidades del motor: {type(exc).__name__}: {exc}")
    _print_line("[info_dim]  env: COGNIA_ANIMACION=0 apaga y =1 fuerza (gana a la config); "
                "sin tty, NO_COLOR, COGNIA_REMOTO=1 y SSH apagan solos[/info_dim]")


def _estilo_presets() -> None:
    try:
        detalle = _aspecto.presets_detalle()
    except Exception as exc:
        _aviso_degradado("estilo", f"presets ilegibles: {type(exc).__name__}: {exc}")
        return
    if not detalle:
        _print_line("[info_dim]sin presets[/info_dim]")
        return
    _print_line(f"[mod]Presets[/mod] [info_dim](los del dueno en {_escape(str(_aspecto.DIR_PRESETS))}; "
                "/estilo cargar <nombre>)[/info_dim]")
    for nombre, ruta, origen, nota in detalle:
        _print_line(f"  [ok_cl]{_escape(nombre):<14}[/ok_cl] [info_dim]{origen:<8} "
                    f"{_escape(nota)}[/info_dim]")


def _estilo_cargar(arg: str) -> None:
    arg = (arg or "").strip()
    if not arg:
        from cognia.ux import selector as _selector
        detalle = _aspecto.presets_detalle()
        if _selector.hay_tty() and detalle:
            sel = _selector.elegir("Preset de estilo:",
                                   [(n, n, f"{o} · {nota}"[:60]) for n, _, o, nota in detalle])
            if sel is None:
                return
            arg = sel
        else:
            _estilo_presets()
            _print_line("[warn_cl]Uso: /estilo cargar <preset|ruta.json>[/warn_cl]")
            return
    antes = {i for i in _aspecto.REGISTRO if _aspecto.tiene_override(i)}
    try:
        _aspecto.cargar_preset(arg)
    except _aspecto.EstiloInvalido as exc:
        _aviso_degradado("estilo", f"preset no cargado: {exc}")
        return
    except (ValueError, OSError) as exc:
        _aviso_degradado("estilo", f"preset no cargado: {exc}")
        return
    _estilo_avisos(_aspecto.ultimos_avisos())
    _aplicar_tema_en_caliente()
    cambiados = [i for i in _aspecto.REGISTRO if _aspecto.tiene_override(i)]
    # dos lineas: con la ruta de ~/.cognia/estilo.json en la misma, la de
    # confirmacion pasaba de 120 celdas y rich la partia en "/estilo deshacer" / "vuelve)"
    _print_line(f"[ok_cl]estilo: '{_escape(arg)}' cargado ({len(cambiados)} elementos "
                f"difieren del default; /estilo deshacer vuelve)[/ok_cl]")
    _print_line(f"  [info_dim]guardado en {_escape(str(_aspecto.RUTA_ESTILO))}[/info_dim]")
    # Lo que el preset trae y todavia no se ve: por elemento entero si no
    # esta enganchado; por propiedad si el elemento ya lo esta y solo le
    # falta esa. En castellano llano, sin los nombres de paso del plan.
    pendientes = set()
    for i in set(cambiados) | antes:
        e = _aspecto.elemento(i)
        if not e.enganchado:
            pendientes.add(f"{i}.*")
            continue
        for prop in _aspecto.cambios(i):
            if _aspecto.paso_pendiente(i, prop):
                pendientes.add(f"{i}.{prop}")
    if pendientes:
        _print_line(f"[warn_cl]{_estilo_sin_efecto(pendientes)}[/warn_cl]")


def _estilo_deshacer() -> None:
    try:
        ok = _aspecto.deshacer()
    except _aspecto.EstiloInvalido as exc:
        _aviso_degradado("estilo", f"deshacer: {exc}")
        return
    except Exception as exc:
        _aviso_degradado("estilo", f"deshacer fallo: {type(exc).__name__}: {exc}")
        return
    if not ok:
        _print_line("[warn_cl]nada que deshacer: no hay "
                    f"{_escape(str(_aspecto.RUTA_ESTILO))}.bak[/warn_cl]")
        return
    _estilo_avisos(_aspecto.ultimos_avisos())
    _aplicar_tema_en_caliente()
    n = sum(1 for i in _aspecto.REGISTRO if _aspecto.tiene_override(i))
    _print_line(f"[ok_cl]estilo: restaurado el anterior ({n} elementos difieren del "
                "default; otro /estilo deshacer vuelve a este)[/ok_cl]")


def _estilo_ayuda(nota_editor: bool = False) -> None:
    _print_line(f"[info_dim]{_escape(_CMD_DETAILS.get('/estilo', ''))}[/info_dim]")
    _print_line(f"[info_dim]{_escape(_ESTILO_USO)}[/info_dim]")
    if nota_editor:
        _print_line("[warn_cl]/estilo sin argumentos abre el editor interactivo "
                    "(solo con terminal real y sin corrida en fondo)[/warn_cl]")


def _sin_comillas(s: str) -> str:
    s = s.strip()
    if len(s) >= 2 and s[0] == s[-1] and s[0] in "\"'":
        return s[1:-1]
    return s


def _estilo_editor() -> None:
    """`/estilo` a secas (P11): el editor full-screen de cognia/ux/editor_app.
    Solo se llama DESDE el bucle del REPL, con session.prompt() ya devuelto
    (E12: anidar una Application dentro de un binding cuelga). Las guardas
    (app anidada, COGNIA_REMOTO, corrida en fondo, status vivo, tty) las
    aplica abrir_editor; si no se puede abrir, se degrada a la ayuda textual."""
    from .ux import editor_app as _EA
    from .ux import renderer as _rmod
    _r = _rmod._renderer
    if _r is not None:
        try:
            _r._parar_status()   # prompt_toolkit jamas con un rich Live activo
        except Exception as exc:
            _aviso_degradado("estilo.editor", f"parar status: {type(exc).__name__}: {exc}")

    def _poner_config(clave, valor):
        cfg = _load_config()
        cfg[clave] = valor
        _save_config(cfg)

    try:
        resultado, detalle = _EA.abrir_editor(
            guardar=_aspecto.guardar,
            aplicar=_aplicar_tema_en_caliente,
            poner_config=_poner_config,
            variante=_variante_actual(),
            corrida_en_fondo=corrida_en_curso(),
            status_activo=(_r is not None and _r._status is not None),
        )
    except Exception as exc:
        _aviso_degradado("estilo.editor", f"{type(exc).__name__}: {exc}")
        resultado, detalle = "no_abrible", f"{type(exc).__name__}: {exc}"
    if resultado == "no_abrible":
        _aviso_degradado("estilo.editor", detalle)
        _print_line(f"[info_dim]editor no disponible: {_escape(detalle)}[/info_dim]")
        _estilo_ayuda(nota_editor=False)
        return
    # abrir_editor ya aplico en caliente si guardo (callback `aplicar`); si
    # volvio con cambios en memoria sin guardar, siguen en el registro (el
    # siguiente /estilo guardar los escribe).
    _print_line(f"[ok_cl]estilo: {_escape(detalle)} ({resultado})[/ok_cl]")


def _slash_estilo(arg: str = "") -> None:
    """`/estilo`: el aspecto de cada elemento del CLI, por separado y en
    caliente (cognia/ux/aspecto.py). Cada escritura: validar (ruidoso) ->
    guardar en ~/.cognia/estilo.json (con .bak) -> aplicar en caliente."""
    arg = (arg or "").strip()
    if not arg:
        _estilo_editor()
        return
    partes = arg.split(None, 1)
    sub = partes[0].lower()
    resto = partes[1].strip() if len(partes) > 1 else ""
    if sub == "lista":
        _estilo_lista(resto.lower())
    elif sub == "ver":
        _estilo_ver(resto)
    elif sub == "reset":
        _estilo_reset(resto)
    elif sub == "animacion":
        _estilo_animacion(resto)
    elif sub == "guardar":
        if not resto:
            _print_line("[warn_cl]Uso: /estilo guardar <nombre-del-preset>[/warn_cl]")
            return
        try:
            ruta = _aspecto.guardar_preset(resto)
        except (ValueError, OSError) as exc:
            _aviso_degradado("estilo", f"preset no guardado: {exc}")
            return
        _print_line(f"[ok_cl]estilo: preset guardado en {_escape(str(ruta))}[/ok_cl]")
    elif sub == "cargar":
        _estilo_cargar(_sin_comillas(resto))
    elif sub == "presets":
        _estilo_presets()
    elif sub == "exportar":
        if not resto:
            _print_line("[warn_cl]Uso: /estilo exportar <ruta.json>[/warn_cl]")
            return
        try:
            ruta = _aspecto.exportar(Path(_sin_comillas(resto)).expanduser())
        except OSError as exc:
            _aviso_degradado("estilo", f"no pude exportar: {exc}")
            return
        _print_line(f"[ok_cl]estilo: exportado completo a {_escape(str(ruta))}[/ok_cl]")
    elif sub == "deshacer":
        _estilo_deshacer()
    elif sub in ("ayuda", "help"):
        _estilo_ayuda()
    elif sub == "banner":
        # P7: repinta la cabecera con el aspecto vigente (mismo camino que el
        # arranque: variante por altura, caja, textos, alineacion, animacion).
        try:
            _reimprimir_banner()
        except Exception as exc:
            _aviso_degradado("estilo.banner", f"{type(exc).__name__}: {exc}")
    elif partes[0] in _aspecto.REGISTRO or "." in partes[0]:
        id = partes[0]
        if not resto:
            _estilo_ver(id)
        elif resto[0] in "\"'":
            _estilo_poner_string(id, _sin_comillas(resto))
        else:
            p2 = resto.split(None, 1)
            if len(p2) < 2:
                _print_line(f"[warn_cl]falta el valor: /estilo {_escape(id)} {_escape(p2[0])} "
                            f"<valor>  (o /estilo {_escape(id)} \"<style string>\")[/warn_cl]")
                return
            _estilo_poner(id, p2[0], _sin_comillas(p2[1]))
    else:
        import difflib as _difflib
        parecidos = _difflib.get_close_matches(
            partes[0], list(_ESTILO_SUBCOMANDOS) + list(_aspecto.REGISTRO), n=3, cutoff=0.5)
        pista = f" ¿{', '.join(parecidos)}?" if parecidos else ""
        _print_line(f"[warn_cl]/estilo: no entiendo '{_escape(partes[0])}'.{pista}[/warn_cl]")
        _print_line(f"[info_dim]{_escape(_ESTILO_USO)}[/info_dim]")


def _slash_expandir(arg: str = "") -> None:
    """`/expandir [N]`: reimprime COMPLETO el output de una tool del turno,
    crudo — sin colores, sin vinetas, seleccionable (patron 'raw view' de
    Codex). Sin N va el ULTIMO; los indices los da `/expandir lista` y la
    propia linea de colapso ('⎿ … +N lineas (/expandir 3)').

    Subcomandos de config (persisten via _save_config):
      on|off      -> clave 'render_colapso' (la env COGNIA_RENDER_COLAPSO=0
                     gana a la config, apagado de emergencia)
      lineas <n>  -> clave 'render_colapso_lineas' (cabeza visible, default 3)
    El buffer lo alimenta agent/loop.py y se vacia al arrancar cada tarea."""
    arg = (arg or "").strip()
    bajo = arg.lower()
    if bajo in ("on", "off"):
        cfg = _load_config()
        cfg["render_colapso"] = bajo
        _save_config(cfg)
        env = (os.environ.get("COGNIA_RENDER_COLAPSO") or "").strip()
        extra = (f" (ojo: COGNIA_RENDER_COLAPSO={env} en el entorno GANA "
                 f"a la config)" if env else "")
        _print_line(f"[info_dim]render colapsado de tools: {bajo}"
                    f" (guardado){extra}[/info_dim]")
        return
    if bajo.startswith("lineas"):
        resto = arg[len("lineas"):].strip()
        try:
            n = int(resto)
            if not 0 <= n <= 50:
                raise ValueError(n)
        except ValueError:
            _print_line("[warn_cl]Uso: /expandir lineas <0-50> (lineas de "
                        "cabeza visibles; 0 = solo el resumen)[/warn_cl]")
            return
        cfg = _load_config()
        cfg["render_colapso_lineas"] = str(n)
        _save_config(cfg)
        _print_line(f"[info_dim]colapso: {n} lineas de cabeza (guardado)"
                    f"[/info_dim]")
        return
    try:
        from cognia.ux import tool_buffer as _tbuf
        entradas = _tbuf.entradas()
    except Exception as exc:
        _aviso_degradado("render_tools",
                         f"tool_buffer no disponible: {exc}")
        return
    if not entradas:
        _print_line("[info_dim]sin outputs de tools en este turno todavia "
                    "(corre una tarea que use herramientas, ej: /hacer)"
                    "[/info_dim]")
        return
    if bajo == "lista":
        for i, e in enumerate(entradas, 1):
            marca = "ok " if e["ok"] else "ERR"
            n_lin = len(e["resultado"].splitlines())
            _print_line(f"[info_dim]{i:3d} {marca} {_escape(e['tool'])}"
                        f"({_escape(e['args'][:60])}) — {n_lin} lineas"
                        f"[/info_dim]")
        return
    n = None
    if arg:
        try:
            n = int(arg)
        except ValueError:
            _print_line("[warn_cl]Uso: /expandir [N | lista | on | off | "
                        "lineas <n>][/warn_cl]")
            return
    entrada = _tbuf.obtener(n)
    if entrada is None:
        _print_line(f"[warn_cl]/expandir {n}: fuera de rango (hay "
                    f"{len(entradas)} outputs; /expandir lista)[/warn_cl]")
        return
    # RAW VIEW: print pelado, sin rich — texto seleccionable tal cual salio
    # de la tool. La cabecera es texto plano a proposito (tambien cruda).
    idx = n if n is not None else len(entradas)
    # La cabecera va por rich (tenue, con la regla ─ de la casa); el CUERPO
    # sigue siendo print pelado: texto seleccionable tal cual salio.
    _print_line(f"[info_dim]  ─ /expandir {idx}: {_escape(entrada['tool'])}"
                f"({_escape(entrada['args'])})[/info_dim]")
    try:
        print(entrada["resultado"])
    except UnicodeEncodeError:
        # consola cp1252: mejor con sustitutos que tragarse el output
        enc = getattr(sys.stdout, "encoding", None) or "utf-8"
        sys.stdout.write(entrada["resultado"]
                         .encode(enc, errors="replace").decode(enc) + "\n")


def _manejar_pegado(event) -> None:
    """Binding de Keys.BracketedPaste: un paste LARGO se colapsa a la marca
    '[pegado #N: +X lineas]' (harness/pegados) y se expande recien AL ENVIAR;
    uno corto entra literal, igual que el binding por defecto de
    prompt_toolkit (que este binding reemplaza en la sesion del REPL).

    Es funcion de MODULO (no closure de repl) a proposito: el test de
    integracion de prompt_toolkit la registra en su propia PromptSession con
    un pipe input y dispara el paste real \\x1b[200~...\\x1b[201~.

    REGLA DURA: el texto del dueno JAMAS se pierde. Cualquier fallo (registro,
    config, import) inserta el paste literal y avisa degradado."""
    data = getattr(event, "data", "") or ""
    try:
        from cognia.harness import pegados as _peg
        texto = _peg.normalizar(data)
        if _peg.activo() and _peg.es_largo(texto):
            marca = _peg.registrar(texto)
            event.app.current_buffer.insert_text(marca)
            return
        event.app.current_buffer.insert_text(texto)
    except Exception as exc:
        _aviso_degradado("pegado", f"{type(exc).__name__}: {exc}")
        # normalizacion minima inline: sin ella un \r\n crudo rompe el buffer
        event.app.current_buffer.insert_text(
            data.replace("\r\n", "\n").replace("\r", "\n"))


def _slash_pegado(arg: str = "") -> None:
    """`/pegado`: los pastes colapsados de la sesion (harness/pegados).

    Sin args o 'lista' muestra el indice; `N` reimprime el contenido CRUDO
    (print pelado, seleccionable, mismo patron raw-view que /expandir).
    Subcomandos de config (persisten via _save_config):
      on|off               -> clave 'pegado' (COGNIA_PEGADO=0 gana a la config)
      umbral <lin> [<ch>]  -> claves 'pegado_lineas' / 'pegado_chars'"""
    try:
        from cognia.harness import pegados as _peg
    except Exception as exc:
        _aviso_degradado("pegado", f"modulo no importable: {exc}")
        return
    arg = (arg or "").strip()
    bajo = arg.lower()
    if bajo in ("on", "off"):
        cfg = _load_config()
        cfg["pegado"] = bajo
        _save_config(cfg)
        env = (os.environ.get("COGNIA_PEGADO") or "").strip()
        extra = (f" (ojo: COGNIA_PEGADO={env} en el entorno GANA a la config)"
                 if env else "")
        _print_line(f"[info_dim]colapso de pastes largos: {bajo} (guardado)"
                    f"{extra}[/info_dim]")
        return
    if bajo.startswith("umbral"):
        partes = arg[len("umbral"):].split()
        try:
            lin = int(partes[0])
            ch = int(partes[1]) if len(partes) > 1 else None
            if lin < 1 or (ch is not None and ch < 1):
                raise ValueError
        except (ValueError, IndexError):
            _print_line("[warn_cl]Uso: /pegado umbral <lineas >= 1> "
                        "[<chars >= 1>][/warn_cl]")
            return
        cfg = _load_config()
        cfg["pegado_lineas"] = str(lin)
        if ch is not None:
            cfg["pegado_chars"] = str(ch)
        _save_config(cfg)
        _print_line(f"[info_dim]pegado: colapsa desde {lin} lineas"
                    f"{'' if ch is None else f' o {ch} chars'} (guardado)"
                    f"[/info_dim]")
        return
    entradas = _peg.listar()
    if bajo in ("", "lista", "estado"):
        env = (os.environ.get("COGNIA_PEGADO") or "").strip()
        fuente = f"env COGNIA_PEGADO={env}" if env else "config pegado"
        filas = [("umbral", f"{_peg.umbral_lineas()} lineas / "
                            f"{_peg.umbral_chars()} chars")]
        if not entradas:
            filas.append(("pegados", "ninguno en esta sesion (pega >= "
                                     f"{_peg.umbral_lineas()} lineas en el prompt)"))
        else:
            for e in entradas:
                filas.append((f"#{e['n']}", f"{e['lineas']} lineas, "
                                            f"{e['chars']} chars"))
            filas.append(("ver uno", "/pegado <N>"))
        _print_line("\n".join(_estado_subsistema(
            "colapso de pastes largos", bool(_peg.activo()), filas,
            fuente=fuente)))
        return
    try:
        n = int(arg)
    except ValueError:
        _print_line("[warn_cl]Uso: /pegado [lista | N | on | off | "
                    "umbral <lineas> [<chars>]][/warn_cl]")
        return
    e = _peg.obtener(n)
    if e is None:
        _print_line(f"[warn_cl]/pegado {n}: fuera de rango (hay "
                    f"{len(entradas)} pegados; /pegado lista)[/warn_cl]")
        return
    # RAW VIEW: print pelado, sin rich — el contenido tal cual se pego.
    try:
        print(f"--- /pegado {n}: {e['lineas']} lineas, {e['chars']} chars ---")
        print(e["texto"])
    except UnicodeEncodeError:
        enc = getattr(sys.stdout, "encoding", None) or "utf-8"
        sys.stdout.write(e["texto"].encode(enc, errors="replace").decode(enc)
                         + "\n")


def _ruta_enlazada(ruta: str) -> str:
    """Una ruta para _print_line con hyperlink OSC 8 ([link=file:///...]) si la
    consola es un tty de verdad y los enlaces estan activos (harness/enlaces).
    En cualquier otro caso (pipe, config off, fallo) devuelve la ruta TAL CUAL:
    el texto visible es byte-identico con o sin link."""
    try:
        if _HAS_RICH and _console is not None and getattr(
                _console, "is_terminal", False):
            from cognia.harness import enlaces as _enl
            if _enl.activo():
                return _enl.marcar_markup(ruta)
    except Exception as exc:
        _aviso_degradado("enlaces", f"{type(exc).__name__}: {exc}")
    return ruta


def _slash_enlaces(arg: str = "") -> None:
    """`/enlaces`: rutas clicables (OSC 8) en el transcript (harness/enlaces).

    Sin args muestra el estado; on|off persiste la clave 'enlaces'
    (COGNIA_ENLACES=0 gana a la config, apagado de emergencia)."""
    try:
        from cognia.harness import enlaces as _enl
    except Exception as exc:
        _aviso_degradado("enlaces", f"modulo no importable: {exc}")
        return
    arg = (arg or "").strip().lower()
    if arg in ("on", "off"):
        cfg = _load_config()
        cfg["enlaces"] = arg
        _save_config(cfg)
        env = (os.environ.get("COGNIA_ENLACES") or "").strip()
        extra = (f" (ojo: COGNIA_ENLACES={env} en el entorno GANA a la config)"
                 if env else "")
        _print_line(f"[info_dim]enlaces de rutas (OSC 8): {arg} (guardado)"
                    f"{extra}[/info_dim]")
        return
    if arg and arg != "estado":
        _print_line("[warn_cl]Uso: /enlaces \\[estado | on | off][/warn_cl]")
        return
    tty = bool(_HAS_RICH and _console is not None
               and getattr(_console, "is_terminal", False))
    env = (os.environ.get("COGNIA_ENLACES") or "").strip()
    fuente = f"env COGNIA_ENLACES={env}" if env else "config enlaces"
    modo_tty = ("si (tty): ctrl+click abre el fichero en Windows Terminal"
                if tty else "no (pipe/CI: fallback plano byte-identico)")
    _print_line("\n".join(_estado_subsistema(
        "enlaces de rutas (OSC 8 file://)", bool(_enl.activo()), [
            ("terminal", modo_tty),
            ("alcance", "solo rutas ABSOLUTAS que existen; el target va "
                        "percent-encodeado y nunca en el texto visible"),
        ], fuente=fuente)))


def _marcar_env_sembrada(*vars_env: str) -> None:
    """Declara en harness/config_resuelta que estas envs las escribio el
    PROPIO CLI copiando la config (siembra de arranque o handler de /offload
    y /compactar): sin la marca, /config-resuelta atribuia el valor a
    'env:COGNIA_*' — la mentira de origen que F6 existe para matar."""
    try:
        from cognia.harness import config_resuelta as _cr
        _cr.marcar_sembrada(*vars_env)
    except Exception as exc:
        _aviso_degradado("config", f"no pude marcar env sembrada: {exc}")


def _env_es_sembrada(var: str) -> bool:
    """True si esa env la escribio el propio CLI (no el usuario)."""
    try:
        from cognia.harness import config_resuelta as _cr
        return _cr.es_sembrada(var)
    except Exception:
        return False


def _aplicar_config_offload() -> None:
    """Propaga la config del offload (F3) al entorno, SIN pisar lo que el
    usuario puso a mano: interceptor/tools/familias leen COGNIA_OFFLOAD del
    env, y sin esta propagacion la config diria 'on' con el subsistema muerto
    (la clase de bug del flag TX, cognia/tx/flag.py). Registra ademas el
    avisador para que un disco roto se VEA en el REPL como degradado."""
    try:
        from cognia.harness import offloading as _off
        cfg = _load_config()
        pares = (
            ("COGNIA_OFFLOAD",
             "1" if str(cfg.get("offload", "on")).lower() in ("on", "1", "true")
             else "0"),
            ("COGNIA_TOOL_RESULT_MAX", str(cfg.get("offload_umbral", "2000"))),
            ("COGNIA_OFFLOAD_CABEZA", str(cfg.get("offload_cabeza", "15"))),
            ("COGNIA_OFFLOAD_COLA", str(cfg.get("offload_cola", "5"))),
            (_off.ENV_UMBRAL_LECTURA,
             str(cfg.get("offload_umbral_lectura", "32768"))),
            (_off.ENV_CABEZA_LECTURA,
             str(cfg.get("offload_cabeza_lectura", "200"))),
        )
        for var, valor in pares:
            if not (os.environ.get(var) or "").strip():
                os.environ[var] = valor
                _marcar_env_sembrada(var)
        _off.registrar_avisador(_aviso_degradado)
    except Exception as exc:
        _aviso_degradado("offloading", f"config no aplicada: {exc}")


def _slash_offload(arg: str = "") -> None:
    """`/offload`: puerta del offloading de salidas grandes (F3).

    Sin args muestra el ESTADO: activo?, dir de spills, umbral, preview,
    ultimo spill con sus bytes y ultimo error del subsistema.
    Subcomandos (persisten via _save_config y actualizan el env de la sesion):
      on|off             -> clave 'offload' (COGNIA_OFFLOAD=0 gana a la config)
      umbral <bytes>     -> clave 'offload_umbral' (min 200)
      preview <N> [<M>]  -> claves 'offload_cabeza'/'offload_cola'
      lista              -> handles vivos de la sesion (resumen_listado)"""
    try:
        from cognia.harness import offloading as _off
    except Exception as exc:
        _aviso_degradado("offloading", f"modulo no importable: {exc}")
        return
    arg = (arg or "").strip()
    bajo = arg.lower()
    if bajo in ("on", "off"):
        cfg = _load_config()
        cfg["offload"] = bajo
        _save_config(cfg)
        os.environ["COGNIA_OFFLOAD"] = "1" if bajo == "on" else "0"
        _marcar_env_sembrada("COGNIA_OFFLOAD")
        _print_line(f"[info_dim]offload de salidas grandes: {bajo} (guardado; "
                    f"la tool recuperar {'se anuncia' if bajo == 'on' else 'deja de anunciarse'} "
                    f"en el proximo turno)[/info_dim]")
        return
    if bajo.startswith("umbral"):
        try:
            n = int(arg[len("umbral"):].strip())
            if n < 200:
                raise ValueError(n)
        except ValueError:
            _print_line("[warn_cl]Uso: /offload umbral <bytes> (>= 200; con "
                        "menos hasta un 'OK' iria a disco)[/warn_cl]")
            return
        cfg = _load_config()
        cfg["offload_umbral"] = str(n)
        _save_config(cfg)
        os.environ["COGNIA_TOOL_RESULT_MAX"] = str(n)
        _marcar_env_sembrada("COGNIA_TOOL_RESULT_MAX")
        _print_line(f"[info_dim]offload: umbral {n} bytes (guardado)[/info_dim]")
        return
    if bajo.startswith("lectura"):
        partes = arg[len("lectura"):].split()
        try:
            umb = int(partes[0])
            cab = int(partes[1]) if len(partes) > 1 else None
            if umb < 200 or (cab is not None and cab < 1):
                raise ValueError(umb)
        except (IndexError, ValueError):
            _print_line("[warn_cl]Uso: /offload lectura <bytes >= 200> "
                        "[<lineas de cabeza >= 1>] -- umbral inline para las "
                        "tools que devuelven contenido pedido por su nombre "
                        "(leer_archivo, leer_lote, recuperar, ver_salida)"
                        "[/warn_cl]")
            return
        cfg = _load_config()
        cfg["offload_umbral_lectura"] = str(umb)
        os.environ[_off.ENV_UMBRAL_LECTURA] = str(umb)
        _marcar_env_sembrada(_off.ENV_UMBRAL_LECTURA)
        if cab is not None:
            cfg["offload_cabeza_lectura"] = str(cab)
            os.environ[_off.ENV_CABEZA_LECTURA] = str(cab)
            _marcar_env_sembrada(_off.ENV_CABEZA_LECTURA)
        _save_config(cfg)
        _print_line(f"[info_dim]offload: las lecturas van inline hasta "
                    f"{umb} bytes"
                    + (f" y su preview es de {cab} lineas de cabeza"
                       if cab is not None else "")
                    + " (guardado)[/info_dim]")
        return
    if bajo.startswith("preview"):
        partes = arg[len("preview"):].split()
        try:
            cab = int(partes[0])
            cola = int(partes[1]) if len(partes) > 1 else None
            if cab < 1 or (cola is not None and cola < 0):
                raise ValueError
        except (ValueError, IndexError):
            _print_line("[warn_cl]Uso: /offload preview <cabeza >= 1> "
                        "[<cola >= 0>][/warn_cl]")
            return
        cfg = _load_config()
        cfg["offload_cabeza"] = str(cab)
        os.environ["COGNIA_OFFLOAD_CABEZA"] = str(cab)
        _marcar_env_sembrada("COGNIA_OFFLOAD_CABEZA")
        if cola is not None:
            cfg["offload_cola"] = str(cola)
            os.environ["COGNIA_OFFLOAD_COLA"] = str(cola)
            _marcar_env_sembrada("COGNIA_OFFLOAD_COLA")
        _save_config(cfg)
        _print_line(f"[info_dim]offload: preview {cab} lineas de cabeza"
                    f"{'' if cola is None else f' + {cola} de cola'} (guardado)"
                    f"[/info_dim]")
        return
    if bajo == "lista":
        _print_line(_off.resumen_listado())
        return
    if arg and bajo != "estado":
        _print_line("[warn_cl]Uso: /offload [estado | on | off | umbral <bytes> "
                    "| lectura <bytes> [<N>] | preview <N> [<M>] | lista]"
                    "[/warn_cl]")
        return
    # Estado (default): la foto entera del subsistema.
    est = _off.estado()
    env = (os.environ.get("COGNIA_OFFLOAD") or "").strip()
    # una env sembrada por el propio CLI no es fuente 'env': el valor salio
    # de la config (F6: el origen no se miente)
    fuente = (f"env COGNIA_OFFLOAD={env}"
              if env and not _env_es_sembrada("COGNIA_OFFLOAD")
              else "config offload")
    filas = [
        ("dir spills", f"{est['dir']}  (sesion {est['sesion']}, "
                       f"{est['handles']} handles, {est['bytes_sesion']} B)"),
        ("umbral", f"{est['umbral']} bytes inline"),
        # Reparto por tool (2026-08-30): lo que el agente pidio por su nombre
        # (un fichero, un handle) no es ruido de proceso y no se capa igual.
        ("umbral lectura",
         f"{est.get('umbral_lectura', est['umbral'])} bytes inline para "
         f"{', '.join(est.get('tools_lectura') or [])}"
         + ("" if est.get("tareas_largas", True)
            else "  (APAGADO por COGNIA_TAREAS_LARGAS=0)")),
        ("preview", f"{est['cabeza']} lineas de cabeza + {est['cola']} de cola"
                    f"  (lectura: {est.get('cabeza_lectura', est['cabeza'])} "
                    f"de cabeza)"),
    ]
    ult = est["ultimo_spill"]
    if ult:
        # La ruta del spill sale CLICABLE (OSC 8 file://, harness/enlaces) en
        # un tty; en pipe o con /enlaces off el texto es byte-identico.
        filas.append(("ultimo spill",
                      f"{_escape(str(ult.get('handle', '?')))} "
                      f"({_escape(str(ult.get('tool') or 'tool'))}, "
                      f"{ult.get('bytes', 0)} B, {ult.get('lineas', 0)} lineas) "
                      f"-> {_ruta_enlazada(ult.get('ruta', ''))}", "listado", True))
    else:
        filas.append(("ultimo spill", "ninguno en este proceso"))
    err = est["ultimo_error"]
    avisos = ([f"ultimo error: {err.get('motivo', '')} ({err.get('ts', '')})"]
              if err else [])
    if not err:
        filas.append(("ultimo error", "ninguno"))
    _print_line("\n".join(_estado_subsistema(
        "offload de salidas grandes", bool(est["activo"]), filas,
        fuente=fuente, avisos=avisos)))


def _aplicar_config_compactacion() -> None:
    """Propaga la config de la compactacion (F4) al entorno, SIN pisar lo que
    el usuario puso a mano: el bucle del agente (agent/loop) decide el modo
    leyendo COGNIA_COMPACT via harness/compactacion, y sin esta propagacion la
    config diria 'resumen' con el bucle en truncado (la clase de bug del flag
    TX, cognia/tx/flag.py)."""
    try:
        cfg = _load_config()
        pares = (
            ("COGNIA_COMPACT", str(cfg.get("compactacion", "resumen")).lower()),
            ("COGNIA_COMPACT_UMBRAL", str(cfg.get("compactacion_umbral", "0.8"))),
            ("COGNIA_COMPACT_RETENCION",
             str(cfg.get("compactacion_retencion", "0.16"))),
            ("COGNIA_COMPACT_CAP", str(cfg.get("compactacion_cap", "4000"))),
        )
        for var, valor in pares:
            if not (os.environ.get(var) or "").strip():
                os.environ[var] = valor
                _marcar_env_sembrada(var)
    except Exception as exc:
        _aviso_degradado("compactacion", f"config no aplicada: {exc}")


def _aplicar_config_barra() -> None:
    """Propaga la config del footer de contexto (barra_estado/contexto_vivo)
    al entorno, sin pisar lo del usuario y registrando la siembra (si no,
    /config-resuelta atribuiria el valor a la env — bug ya cazado).

    OJO: 'contexto_umbral_aviso' VACIO no siembra nada A PROPOSITO: sin env,
    contexto_vivo.umbral_aviso_pct() sigue al umbral REAL de compactacion y
    el amarillo de la barra se mueve con /compactar umbral. Sembrar un numero
    aqui congelaria ese acople."""
    try:
        cfg = _load_config()
        pares = (
            ("COGNIA_CTX_AVISO", str(cfg.get("contexto_umbral_aviso", "")).strip()),
            ("COGNIA_CTX_CRITICO", str(cfg.get("contexto_umbral_critico", "90")).strip()),
            ("COGNIA_BARRA_BLOQUES", str(cfg.get("barra_bloques", "on")).strip()),
        )
        for var, valor in pares:
            if valor and not (os.environ.get(var) or "").strip():
                os.environ[var] = valor
                _marcar_env_sembrada(var)
    except Exception as exc:
        _aviso_degradado("cli.barra_estado", f"config no aplicada: {exc}")


def _aplicar_config_revision() -> None:
    """Propaga la config de la revision profunda al entorno.

    Quien la lee es `cognia/agent/loop.py` (a traves de
    `harness/revision_profunda.activa()`), que corre por debajo del REPL y no ve
    `~/.cognia_config.json`: sin esta siembra, `/revision off` diria OFF en
    pantalla y el bucle seguiria revisando — exactamente la clase de bug del
    flag TX (la config decia ACTIVO y el subsistema estaba muerto). No pisa lo
    que el dueno ya puso en la env, y registra la siembra para que
    /config-resuelta no atribuya el valor al entorno."""
    try:
        cfg = _load_config()
        pares = (
            ("COGNIA_REVISION",
             "1" if str(cfg.get("revision", "on")).strip().lower() != "off" else "0"),
            ("COGNIA_REVISION_EJECUTAR",
             "1" if str(cfg.get("revision_ejecutar", "on")).strip().lower() != "off" else "0"),
            ("COGNIA_REVISION_RONDAS", str(cfg.get("revision_rondas", "2")).strip()),
            ("COGNIA_REVISION_SEGUNDOS", str(cfg.get("revision_segundos", "180")).strip()),
        )
        for var, valor in pares:
            if valor and not (os.environ.get(var) or "").strip():
                os.environ[var] = valor
                _marcar_env_sembrada(var)
    except Exception as exc:
        _aviso_degradado("revision", f"config no aplicada: {exc}")


def _slash_revision(arg: str = "") -> None:
    """`/revision`: puerta de la revision profunda antes de entregar.

    Sin args (o 'estado') muestra los mandos y el veredicto del ultimo turno
    revisado. Subcomandos (persisten via _save_config y actualizan el env):
      on|off             -> 'revision'
      ejecutar on|off    -> 'revision_ejecutar' (la fase que ARRANCA el producto)
      rondas <n>         -> 'revision_rondas'   (0 = revisar y solo reportar)
      segundos <n>       -> 'revision_segundos' (presupuesto de pared)
      informe            -> el ultimo informe entero, fase por fase
      ahora <ruta...>    -> revisa ESAS rutas ya mismo (diagnostico sin modelo)"""
    try:
        from cognia.harness import revision_profunda as _rp
    except Exception as exc:
        _aviso_degradado("revision", f"modulo no importable: {exc}")
        return
    arg = (arg or "").strip()
    partes = arg.split(None, 1)
    sub = partes[0].lower() if partes else ""
    resto = partes[1].strip() if len(partes) > 1 else ""
    uso = ("[warn_cl]Uso: /revision \\[estado | on | off | ejecutar on|off | "
           "rondas <n> | segundos <n> | informe | ahora <ruta...>][/warn_cl]")

    def _guardar(clave, valor, env, valor_env, texto):
        cfg = _load_config()
        cfg[clave] = valor
        _save_config(cfg)
        os.environ[env] = valor_env      # la sesion viva, no solo la proxima
        _marcar_env_sembrada(env)
        _print_line(f"[info_dim]revision: {texto} (guardado)[/info_dim]")

    if sub in ("on", "off") and not resto:
        _guardar("revision", sub, "COGNIA_REVISION",
                 "1" if sub == "on" else "0", sub)
        return
    if sub == "ejecutar":
        if resto.lower() not in ("on", "off"):
            _print_line("[warn_cl]Uso: /revision ejecutar on|off[/warn_cl]")
            return
        _guardar("revision_ejecutar", resto.lower(), "COGNIA_REVISION_EJECUTAR",
                 "1" if resto.lower() == "on" else "0",
                 f"arrancar el producto {resto.lower()}")
        return
    if sub in ("rondas", "segundos"):
        minimo = 0 if sub == "rondas" else 10
        try:
            n = int(float(resto.replace(",", ".")))
            if n < minimo:
                raise ValueError(n)
        except ValueError:
            _print_line(f"[warn_cl]Uso: /revision {sub} <entero >= {minimo}>[/warn_cl]")
            return
        _guardar(f"revision_{sub}", str(n),
                 f"COGNIA_REVISION_{sub.upper()}", str(n), f"{sub} {n}")
        return
    if sub == "ahora":
        rutas = [r for r in resto.replace(",", " ").split() if r]
        if not rutas:
            _print_line("[warn_cl]Uso: /revision ahora <ruta> [<ruta>...]"
                        "[/warn_cl]")
            return
        _print_line(f"[info_dim]revisando {len(rutas)} ruta(s) — esto EJECUTA "
                    f"lo que haya arrancable[/info_dim]")
        inf = _rp.revisar({"ficheros_editados": rutas, "workspace": os.getcwd(),
                           "pasos": 99, "superficie": "cli",
                           "on_evento": lambda m: _print_line(
                               f"[info_dim]  · {_escape(str(m))}[/info_dim]")})
        for linea in _rp.render(inf):
            _print_line(linea)
        return
    if sub == "informe":
        inf = _rp.ultimo()
        if not inf:
            _print_line("[info_dim]todavia no se reviso nada en esta sesion "
                        "(la revision corre al cerrar una tarea de /hacer que "
                        "haya escrito codigo)[/info_dim]")
            return
        for linea in _rp.render(inf):
            _print_line(linea)
        for f in (inf.get("fallos") or []):
            _print_line(f"[err_cl]{_escape(f.get('fase', ''))}: "
                        f"{_escape((f.get('detalle') or '')[:300])}[/err_cl]")
            ev = (f.get("evidencia") or "").strip()
            if ev:
                for l in ev.splitlines()[-12:]:
                    _print_line(f"[info_dim]  {_escape(l[:200])}[/info_dim]")
        return
    if sub and sub != "estado":
        _print_line(uso)
        return

    m = _rp.mandos()
    estado_col = "ok_cl" if m["activa"] else "warn_cl"
    _print_line(f"[{estado_col}]revision profunda: "
                f"{'ACTIVA' if m['activa'] else 'APAGADA'}[/{estado_col}]"
                f" [info_dim]· arrancar el producto: "
                f"{'si' if m['ejecutar_producto'] else 'no'} · rondas de "
                f"reparacion: {m['rondas']} · presupuesto: {m['presupuesto_s']} s"
                f"[/info_dim]")
    _print_line(f"[info_dim]dispara con: >= {m['ficheros']} fichero(s) de codigo, "
                f"o >= {m['lineas']} lineas utiles, o >= {m['pasos']} pasos, o si "
                f"hay algo arrancable entre lo escrito[/info_dim]")
    _print_line("[info_dim]fases: sintaxis (compile/json) · tests que CUBREN lo "
                "editado · el producto de punta a punta (se arranca con teclado "
                "guionado + brazo B; una pagina se abre en el navegador)[/info_dim]")
    inf = _rp.ultimo()
    if not inf:
        _print_line("[info_dim]ultimo turno: sin revisar todavia[/info_dim]")
    else:
        for linea in _rp.render(inf):
            _print_line(linea)
        _print_line("[info_dim]  (/revision informe para la evidencia entera)"
                    "[/info_dim]")


def _slash_compactar(arg: str = "") -> None:
    """`/compactar`: puerta de la compactacion del contexto del agente (F4).

    Sin args muestra el ESTADO: modo (y su fuente), umbral, retencion, cap,
    la ultima compactacion con tokens antes/despues y el ultimo error.
    Subcomandos (persisten via _save_config y actualizan el env de la sesion):
      resumen|truncado -> clave 'compactacion' (COGNIA_COMPACT gana a config)
      umbral <frac>    -> 'compactacion_umbral' (0.3-0.99 del n_ctx)
      retencion <frac> -> 'compactacion_retencion' (0.02-0.5 del n_ctx)
      cap <chars>      -> 'compactacion_cap' (>= 600)"""
    try:
        from cognia.harness import compactacion as _comp
    except Exception as exc:
        _aviso_degradado("compactacion", f"modulo no importable: {exc}")
        return
    arg = (arg or "").strip()
    bajo = arg.lower()
    if bajo in ("resumen", "truncado"):
        cfg = _load_config()
        cfg["compactacion"] = bajo
        _save_config(cfg)
        os.environ["COGNIA_COMPACT"] = bajo
        _marcar_env_sembrada("COGNIA_COMPACT")
        _print_line(f"[info_dim]compactacion: modo {bajo} (guardado; aplica "
                    "en la proxima compactacion del agente)[/info_dim]")
        return
    if bajo.startswith("umbral") or bajo.startswith("retencion"):
        clave = "umbral" if bajo.startswith("umbral") else "retencion"
        lo, hi = (0.3, 0.99) if clave == "umbral" else (0.02, 0.5)
        try:
            v = float(arg[len(clave):].strip())
            if not (lo <= v <= hi):
                raise ValueError(v)
        except ValueError:
            _print_line(f"[warn_cl]Uso: /compactar {clave} <fraccion de n_ctx, "
                        f"{lo}-{hi}>[/warn_cl]")
            return
        cfg = _load_config()
        cfg[f"compactacion_{clave}"] = str(v)
        _save_config(cfg)
        os.environ["COGNIA_COMPACT_" + clave.upper()] = str(v)
        _marcar_env_sembrada("COGNIA_COMPACT_" + clave.upper())
        _print_line(f"[info_dim]compactacion: {clave} {v} de n_ctx (guardado)"
                    f"[/info_dim]")
        return
    if bajo.startswith("cap"):
        try:
            n = int(arg[len("cap"):].strip())
            if n < 600:
                raise ValueError(n)
        except ValueError:
            _print_line("[warn_cl]Uso: /compactar cap <chars> (>= 600; con "
                        "menos no cabe ni el bloque de estado)[/warn_cl]")
            return
        cfg = _load_config()
        cfg["compactacion_cap"] = str(n)
        _save_config(cfg)
        os.environ["COGNIA_COMPACT_CAP"] = str(n)
        _marcar_env_sembrada("COGNIA_COMPACT_CAP")
        _print_line(f"[info_dim]compactacion: cap {n} chars (guardado)[/info_dim]")
        return
    if arg and bajo != "estado":
        _print_line("[warn_cl]Uso: /compactar \\[estado | resumen | truncado | "
                    "umbral <frac> | retencion <frac> | cap <chars>][/warn_cl]")
        return
    # Estado (default): la foto entera del subsistema.
    est = _comp.estado_puerta()
    env = (os.environ.get("COGNIA_COMPACT") or "").strip()
    # misma regla que /offload estado: sembrada por el CLI != env del usuario
    fuente = (f"env COGNIA_COMPACT={env}"
              if env and not _env_es_sembrada("COGNIA_COMPACT")
              else "config compactacion")
    filas = [
        ("umbral", f"{est['umbral']:.2f} de n_ctx util (n_ctx - headroom)"),
        ("retencion", f"{est['retencion']:.2f} de cola"),
        ("cap", f"{est['cap']} chars de resumen"),
    ]
    # Nivel ACTUAL del contexto, con la MISMA aritmetica del footer
    # (barra_estado.nivel_contexto: headroom restado y umbrales acoplados) —
    # dos cuentas distintas aqui y en la barra ya mintieron una vez (75 vs 80).
    try:
        from cognia.harness import barra_estado as _be
        d = _datos_barra_estado()
        nc = _be.nivel_contexto(d.get("ctx_usado"), d.get("ctx_total"))
        if nc["pct_usado"] is None:
            filas.append(("contexto", "ctx ? (sin n_ctx del backend; no se "
                                      "inventa un %)"))
        else:
            estilo = {"critico": "err_cl", "aviso": "warn_cl"}.get(
                nc["nivel"], "listado")
            nivel = nc["nivel"] or "normal"
            filas.append(("contexto",
                          f"{nc['libre']}% libre ({nc['pct_usado']}% usado con "
                          f"headroom {nc['headroom']}; nivel {nivel} — amarillo "
                          f"al {nc['aviso']}%, rojo al {nc['critico']}%)",
                          estilo))
    except Exception as exc:
        _aviso_degradado("cli.barra_estado",
                         f"nivel de contexto no disponible: {exc}")
    ult = est["ultima"]
    if ult:
        hace = max(0, int(time.time() - float(ult.get("ts") or 0)))
        extra = (f", {ult['mensajes_descartados']} mensajes fundidos"
                 if ult.get("mensajes_descartados") else "")
        # Volcado del historial compactado (P4, deepagents 0.7.8
        # SummarizationMiddleware: lo fundido queda en disco recuperable).
        if ult.get("historial_ruta"):
            extra += f"; historial en {ult['historial_ruta']}"
        elif ult.get("historial_error"):
            extra += f"; volcado del historial FALLO: {ult['historial_error']}"
        filas.append(("ultima", f"modo {ult.get('modo', '?')}, "
                                f"~{ult.get('tokens_antes', 0)} -> "
                                f"~{ult.get('tokens_despues', 0)} tokens "
                                f"(hace {hace}s{extra})"))
    else:
        filas.append(("ultima", "ninguna en este proceso"))
    err = est["ultimo_error"]
    avisos = ([f"ultimo error: {err.get('motivo', '')} ({err.get('ts', '')})"]
              if err else [])
    if not err:
        filas.append(("ultimo error", "ninguno"))
    _print_line("\n".join(_estado_subsistema(
        "compactacion del contexto", str(est["modo"]), filas, fuente=fuente,
        avisos=avisos)))


def _slash_lazo(arg: str = "") -> None:
    """`/debug lazo [estado | on | off]`: el LAZO CORTO del agente.

    Cada fichero arrancable que el agente escribe (HTML, Python, JS) se corre en
    el acto y el error real vuelve pegado al resultado de la tool, en el mismo
    turno. Ver cognia/harness/lazo_corto.py. on|off persisten en la config
    ('lazo_corto'); COGNIA_LAZO_CORTO=0 lo apaga ganando a la config.
    """
    try:
        from cognia.harness import lazo_corto as _lz
    except Exception as exc:
        _aviso_degradado("lazo_corto", f"modulo no importable: {exc}")
        _print_line(f"[warn_cl]lazo corto no disponible: {exc}[/warn_cl]")
        return
    arg = (arg or "").strip().lower()
    cfg = _load_config()
    if arg in ("on", "1", "si"):
        cfg["lazo_corto"] = "on"
        _save_config(cfg)
        os.environ.pop(_lz.ENV, None)
        _print_line("[ok_cl]lazo corto ON: lo que escribas se corre en el acto[/ok_cl]")
        return
    if arg in ("off", "0", "no"):
        cfg["lazo_corto"] = "off"
        _save_config(cfg)
        os.environ[_lz.ENV] = "0"
        _print_line("[ok_cl]lazo corto OFF[/ok_cl]")
        return
    if arg in ("", "estado"):
        try:
            import playwright  # noqa: F401
            nav = "Playwright disponible (HTML se abre en Chromium)"
        except Exception:
            nav = "sin Playwright: HTML NO se comprueba (pip install playwright && playwright install chromium)"
        _print_line(f"lazo corto: {'ON' if _lz.activo() else 'OFF'}"
                    f"   config={cfg.get('lazo_corto', 'on')}")
        _print_line(f"  html: {nav}")
        _print_line(f"  py: compila e importa con timeout de {int(_lz.TIMEOUT_IMPORT_S)}s"
                    f"   js: node --check")
        _print_line(f"  intervalo minimo por fichero: {int(_lz.INTERVALO_MIN_S)}s")
        return
    _print_line("[warn_cl]uso: /debug lazo [estado | on | off][/warn_cl]")


def _aplicar_config_lazo() -> None:
    """Aplica la config 'lazo_corto' al arrancar (off -> COGNIA_LAZO_CORTO=0).
    La variable puesta a mano siempre gana."""
    try:
        from cognia.harness import lazo_corto as _lz
        if os.environ.get(_lz.ENV):
            return
        if str(_load_config().get("lazo_corto", "on")).strip().lower() in ("off", "0", "no"):
            os.environ[_lz.ENV] = "0"
    except Exception as exc:
        _aviso_degradado("lazo_corto", f"no pude aplicar la config: {exc}")


def _aplicar_config_telemetria() -> None:
    """Enciende el diario del turno si la config lo dice.

    Sin esto `/telemetria on` mentiria: la clave quedaba guardada y el proceso
    siguiente arrancaba sin la variable, o sea con la telemetria apagada y el
    estado diciendo ON. COGNIA_TELEMETRIA puesta a mano SIEMPRE gana (es la que
    usan los bancos para mandar cada tarea a su propio fichero).
    """
    try:
        from cognia.harness import telemetria as _tel
        if os.environ.get(_tel.ENV):
            return
        if str(_load_config().get("telemetria", "off")).strip().lower() not in (
                "on", "1", "si", "true"):
            return
        base = Path.home() / ".cognia" / "telemetria"
        base.mkdir(parents=True, exist_ok=True)
        os.environ[_tel.ENV] = str(base / (time.strftime("%Y%m%d") + ".jsonl"))
    except Exception as exc:
        _aviso_degradado("telemetria", f"no pude aplicar la config: {exc}")


def _aplicar_config_horizonte() -> None:
    """Propaga la config del modo HORIZONTE (rondas de worker fresco con
    contrato ralph) al entorno SIN pisar lo del usuario, marcando la siembra
    (F6: /config-resuelta no miente el origen), y la VALIDA al arrancar: una
    config invalida se grita via degradado y se siembra el default."""
    try:
        from cognia.agent import horizonte as _hz
    except Exception as exc:
        _aviso_degradado("horizonte", f"modulo no importable: {exc}")
        return
    try:
        cfg = _load_config()
    except Exception as exc:
        _aviso_degradado("horizonte", f"config no aplicada: {exc}")
        return
    act = str(cfg.get("horizonte", "off")).strip().lower()
    if act not in ("on", "off"):
        _aviso_degradado("horizonte", f"config 'horizonte'={act!r} no es "
                         f"on/off; uso off")
        act = "off"
    rondas = str(cfg.get("horizonte_max_rondas", "")).strip()
    if rondas:
        try:
            if int(rondas) < 0:
                raise ValueError(rondas)
        except ValueError:
            _aviso_degradado("horizonte", f"config 'horizonte_max_rondas'="
                             f"{rondas!r} no es un entero >= 0; uso el de "
                             f"/esfuerzo")
            rondas = ""
        if rondas == "0":
            rondas = ""
    hmax = str(cfg.get("horizonte_handoff_max", "16384")).strip()
    try:
        if int(hmax) < 512:
            raise ValueError(hmax)
    except ValueError:
        _aviso_degradado("horizonte", f"config 'horizonte_handoff_max'="
                         f"{hmax!r} no es un entero >= 512; uso 16384")
        hmax = "16384"
    pares = [(_hz.FLAG, "1" if act == "on" else "0"),
             (_hz.ENV_HANDOFF_MAX, hmax)]
    if rondas:
        pares.append((_hz.ENV_CICLOS, rondas))
    for var, valor in pares:
        if not (os.environ.get(var) or "").strip():
            os.environ[var] = valor
            _marcar_env_sembrada(var)


def _slash_ventana(arg: str = "") -> None:
    """`/ventana`: puerta del PRESUPUESTO DE SALIDA (agent/presupuesto_salida).

    Muestra el numero que hasta el 2026-08-30 era invisible y que decidia si
    una tarea larga podia terminar o no: cuantos tokens de SALIDA deja la
    ventana despues del prompt. Medido ese dia contra el server del dueno, una
    peticion con max_tokens=32768 devolvio 2258 tokens porque el corte lo daba
    n_ctx, no el tope pedido — y el CLI no tenia donde enseñarlo.

    Sin args (o 'estado'): modelo, n_ctx, reserva, minimo util y el veredicto.
    Subcomandos (persisten via _save_config):
      pensamiento auto|on|off -> clave 'thinking' (COGNIA_THINKING). 'auto' es
        el default: el bucle lo apaga SOLO si un paso se le va entero en
        razonar sin llegar a llamar la herramienta.
      continuo on|off|<rondas>|tramo N -> SALIDA CONTINUA del chat
        (agent/salida_continua). 'on' (default) hace que el tope de tokens sea
        el tamano de cada TRAMO y no el techo de la respuesta: al cortarse, el
        turno sigue re-anclado en la cola de lo ya dicho. <rondas> pone el
        freno duro de tramos (0 = sin freno) y 'tramo N' fija los tokens de
        cada tramo (0 = los del nivel /esfuerzo).
    Punto de extension: los subcomandos son ramas de este if; la aritmetica
    vive entera en presupuesto_salida (disponible/clamp/es_corte_por_contexto).
    """
    try:
        from cognia.agent import presupuesto_salida as _ps
        from cognia.agent import salida_continua as _sc
        from cognia.agent.model_profiles import perfil_del_agente
    except Exception as exc:
        _aviso_degradado("ventana", f"modulo no importable: {exc}")
        return
    arg = (arg or "").strip()
    bajo = arg.lower()
    if bajo.startswith("continuo"):
        val = bajo[len("continuo"):].strip()
        cfg = _load_config()
        if val in ("on", "off"):
            cfg["salida_continua"] = val
            _save_config(cfg)
            os.environ.pop(_sc.ENV_ACTIVA, None)
            _print_line(f"[info_dim]salida continua del chat: {val} "
                        f"(guardado)[/info_dim]")
            return
        if val.startswith("tramo"):
            n = val[len("tramo"):].strip()
            if not n.isdigit():
                _print_line("[warn_cl]Uso: /ventana continuo tramo <tokens> "
                            "(0 = el max_tokens de /esfuerzo)[/warn_cl]")
                return
            cfg["salida_continua_tramo"] = int(n)
            _save_config(cfg)
            os.environ.pop(_sc.ENV_TRAMO, None)
            _print_line(f"[info_dim]tokens por tramo: "
                        f"{'los de /esfuerzo' if n == '0' else n} "
                        f"(guardado)[/info_dim]")
            return
        if val.isdigit():
            cfg["salida_continua_rondas"] = int(val)
            _save_config(cfg)
            os.environ.pop(_sc.ENV_RONDAS, None)
            _print_line(f"[info_dim]freno de tramos: "
                        f"{'sin freno' if val == '0' else val} "
                        f"(guardado)[/info_dim]")
            return
        if val:
            _print_line("[warn_cl]Uso: /ventana continuo "
                        "on|off|<rondas>|tramo <tokens>[/warn_cl]")
            return
        _rondas, _tope = _sc.limites(cfg)
        _tramo_tok = _sc.tramo(_active_effort()["max_tokens"], cfg)
        _print_line(
            f"  [mod]{'salida continua':<22}[/mod] "
            f"{'ENCENDIDA' if _sc.activa(cfg) else 'apagada'}")
        _print_line(f"  [mod]{'freno de tramos':<22}[/mod] "
                    f"{_rondas or 'sin freno'}")
        _print_line(f"  [mod]{'tope total':<22}[/mod] "
                    f"{f'{_tope:,} tokens' if _tope else 'sin tope'}")
        _print_line(f"  [mod]{'tokens por tramo':<22}[/mod] {_tramo_tok:,}")
        _print_line(f"  [mod]{'cola de re-anclaje':<22}[/mod] "
                    f"{_sc.COLA_REANCLAJE} chars por tramo")
        _print_line("[info_dim]con la salida continua el tope de /esfuerzo es "
                    "el tamano de cada TRAMO, no el techo de la respuesta: al "
                    "cortarse, el turno sigue donde murio y se pega sin "
                    "costura.[/info_dim]")
        return
    if bajo.startswith("pensamiento"):
        val = bajo[len("pensamiento"):].strip()
        if val not in ("auto", "on", "off"):
            _print_line("[warn_cl]Uso: /ventana pensamiento auto|on|off"
                        "[/warn_cl]")
            return
        cfg = _load_config()
        cfg["thinking"] = val
        _save_config(cfg)
        if val == "auto":
            os.environ.pop("COGNIA_THINKING", None)
        else:
            os.environ["COGNIA_THINKING"] = val
            _marcar_env_sembrada("COGNIA_THINKING")
        _print_line(f"[info_dim]pensamiento del agente: {val} (guardado)"
                    f"[/info_dim]")
        return
    try:
        p = perfil_del_agente()
    except Exception as exc:
        _aviso_degradado("ventana", f"perfil no disponible: {exc}")
        return
    n_ctx = p.get("n_ctx")
    if not n_ctx:
        _print_line("[warn_cl]sin n_ctx del backend: no se puede decir cuanto "
                    "cabe (arranca la flota o revisa /props)[/warn_cl]")
        return
    kw = p.get("kwargs_plantilla") or {}
    piensa = kw.get("enable_thinking")
    filas = [
        ("modelo", str(p.get("modelo") or "?")),
        ("ventana (n_ctx)", f"{int(n_ctx):,} tokens"),
        ("max_tokens del perfil", f"{p.get('max_tokens')}"),
        ("reserva del server", f"{_ps.RESERVA} tokens"),
        ("minimo util por paso", f"{_ps.MINIMO_UTIL} tokens"),
        ("pensamiento", ("no lo lee esta plantilla" if piensa is None
                         else ("encendido" if piensa else "apagado"))),
        ("override del dueno",
         os.environ.get("COGNIA_THINKING", "") or "(auto)"),
        ("salida continua",
         "ENCENDIDA (el tope corta el TRAMO, no la respuesta)"
         if _sc.activa(_load_config()) else "apagada (el tope trunca)"),
    ]
    for k, v in filas:
        _print_line(f"  [mod]{k:<22}[/mod] {_escape(v)}")
    _print_line("[info_dim]con el prompt vacio caben "
                f"{_ps.disponible(n_ctx, 0):,} tokens de salida; cada token de "
                f"contexto se los quita uno a uno. El razonamiento sale de "
                f"ESE mismo hueco.[/info_dim]")


# ---------------------------------------------------------------------------
# CUADERNO DE CLASE: los subcomandos NUEVOS de /grabar-clase (2026-08-31)
# ---------------------------------------------------------------------------
# EL PUNTO DE EXTENSION es `_CLASES_SUBCOMANDOS` (el dict del final del
# bloque): un subcomando nuevo se da de alta escribiendo su funcion
# `_clases_x(resto, ai)` y una entrada ahi, sin tocar el if/elif historico de
# `_slash_grabar_clase`. Se hizo asi y no alargando la cadena de ifs porque
# esta entrega mete DIECISEIS subcomandos de golpe y una cadena de treinta
# ramas deja de ser legible justo donde hay que buscar el bug.
#
# TODO camino de fallo sale por `_aviso_degradado`: la leccion de la casa es
# que "no lo cablearon" y "se rompio" no pueden verse igual desde afuera, y
# aqui hay ocho subsistemas opcionales (audio, whisper, matplotlib, sympy,
# PIL, red, navegador, tkinter) que pueden faltar de uno en uno.

# Lo ULTIMO que devolvio `imagen-buscar`, para que `imagen-usar <n>` sepa a
# que se refiere ese numero. Vive en un dict de modulo (y no en la config)
# porque es estado de ESTA sesion: una lista de resultados de hace tres dias
# apuntaria a urls que ya no sirven y el numero significaria otra cosa.
_CLASES_BUSQUEDA = {"consulta": "", "resultados": []}

# Los si/no que aceptan las claves de config de clases. Espejo de
# refinado._SI / refinado._NO: si divergen, un 'si' escrito a mano en
# ~/.cognia_config.json encenderia la config y dejaria la env en '0'.
_CLASES_SI = ("1", "si", "on", "true", "yes", "y")
_CLASES_NO = ("0", "no", "off", "false", "n")


def _clases_ok(mensaje: str, detalle: str = "") -> None:
    """El "salio bien" y su letra pequenia, en DOS lineas y no en una.

    NO ES COSMETICA, es un vacio silencioso cazado tecleando: `_print_line`
    tira la linea ENTERA si contiene '[detail]' (modo sencillo, que es el
    default), asi que un `[ok]...[/ok] [detail]...[/detail]` en una sola
    llamada desaparece con el detalle y el duenio ve un comando que no
    contesta nada. Separandolo, el resultado siempre sale y lo unico que se
    calla en modo sencillo es la letra pequenia, que es lo que se pretendia.
    """
    _print_line(f"[ok]{mensaje}[/ok]")
    if detalle:
        _print_line(f"[detail]{detalle}[/detail]")


def _clases_encendido(cfg, clave: str, defecto: str = "on") -> bool:
    """Lee una clave on/off de la config de clases. Un valor que no es ni si
    ni no se DICE y se cae al default: tragarselo dejaria al duenio con una
    capacidad apagada por una errata que nada nombra."""
    crudo = str(cfg.get(clave, defecto)).strip().lower()
    if crudo in _CLASES_SI:
        return True
    if crudo in _CLASES_NO:
        return False
    _aviso_degradado("clases.config",
                     f"{clave}={crudo!r} no es un si/no; uso el default "
                     f"({defecto})")
    return defecto.lower() in _CLASES_SI


def _clases_sembrar_env(cfg=None) -> None:
    """Siembra COGNIA_CLASES_REFINADO desde la config (clases_refinado).

    Los modulos de cognia/clases leen la env en CADA llamada y no conocen
    ~/.cognia_config.json, asi que sin esta traduccion 'clases_refinado' seria
    una clave que no decide nada -- el fallo que ya se pago con bots_max_hops.
    No se siembra COGNIA_CLASES_REFINADO_PERIODO: el periodo se deja al
    default medido del modulo y quien lo quiera cambiar tiene la env
    documentada en la ficha de /grabar-clase.

    Una env puesta A MANO en el shell GANA: quien exporta la variable antes de
    arrancar esta diciendo algo mas concreto que la config de ayer.
    """
    cfg = cfg if cfg is not None else _load_config()
    try:
        from cognia.clases import refinado as _cr
        var = _cr.ENV_ACTIVO
    except Exception as exc:
        # Sin el modulo no hay nada que sembrar, pero el nombre de la variable
        # es estable: se siembra igual para que la config valga aunque el
        # import de refinado se rompa (arrastra apuntes y el backend).
        _aviso_degradado("clases.refinado",
                         f"modulo no importable ({type(exc).__name__}: {exc}); "
                         f"siembro COGNIA_CLASES_REFINADO a ciegas")
        var = "COGNIA_CLASES_REFINADO"
    if (os.environ.get(var) or "").strip():
        return
    os.environ[var] = "1" if _clases_encendido(cfg, "clases_refinado") else "0"
    _marcar_env_sembrada(var)


class _FormatoSinRuidoDelModelo(logging.Formatter):
    """Envuelve al formatter de un handler de PANTALLA y resume lo ilegible.

    POR QUE AQUI Y NO EN EL MODULO QUE AVISA: la linea que le llego a la cara
    al duenio ("clases/materias: respuesta del modelo fuera de la lista
    (...)") es un `log.warning` de cognia/clases/materias.py, no un
    `_aviso_degradado`. Filtrarlo en el productor obligaria a repetir el
    saneado en cada modulo que le pase texto del modelo al log; envolviendo el
    FORMATTER de los handlers de pantalla se sanea todo lo que se pinta, una
    vez y en un solo sitio.

    Y solo los de pantalla: el handler de FICHERO conserva el registro ENTERO,
    que es donde se diagnostica. Por eso se envuelve el formatter (que
    devuelve una cadena) y no se filtra el record (que es el MISMO objeto para
    todos los handlers y quedaria mutilado tambien para el fichero).
    """

    def __init__(self, base):
        super().__init__()
        self.base = base

    def format(self, record):           # noqa: A003 (nombre de la stdlib)
        return _resumir_para_pantalla(self.base.format(record))


def _sanear_consola_de_logs() -> int:
    """Envuelve los handlers de PANTALLA del logger 'cognia'. Idempotente.

    Devuelve cuantos quedaron envueltos. El de fichero se salta a proposito
    (ahi va el texto entero) y el enrutado a la interfaz se sanea en su propio
    callback (`_log_a_interfaz`), que es donde nace y se instala mas tarde.
    """
    puestos = 0
    for h in list(logging.getLogger("cognia").handlers):
        if isinstance(h, logging.FileHandler):
            continue
        if isinstance(h.formatter, _FormatoSinRuidoDelModelo):
            continue
        h.setFormatter(_FormatoSinRuidoDelModelo(h.formatter
                                                 or logging.Formatter()))
        puestos += 1
    return puestos


# Las librerias que pisan el prompt durante una clase entera, silenciadas POR
# NOMBRE. Nunca un filtro global: un `warnings.simplefilter("ignore")` taparia
# tambien los avisos que sirven, y eso es cambiar un ruido por una ceguera.
_RUIDO_LIBRERIAS = {"soundcard": False, "ctranslate2": False}


def _silenciar_ruido_de_librerias() -> dict:
    """Calla los dos avisos que salen CADA POCOS SEGUNDOS mientras se graba.

    QUE SE CALLA Y POR QUE:
      * soundcard, SoundcardRuntimeWarning "data discontinuity in recording"
        (soundcard/mediafoundation.py): el loopback WASAPI lo emite cada vez
        que el driver entrega un bloque con hueco -- varias veces por minuto
        durante toda la clase, con su traza encima. No es accionable (el hueco
        ya paso y la grabacion sigue) y tapa el prompt. Se filtra por el TEXTO
        del mensaje, sin importar soundcard: importarlo aqui abriria el
        subsistema de audio en cada arranque.
      * ctranslate2, el aviso de que el modelo venia en float16 y este equipo
        no lo soporta, asi que convierte los pesos. Es un log del C++ y NO un
        warnings.warn, o sea que ningun filtro de `warnings` lo alcanza: se
        baja con CT2_VERBOSE=-1 (su propia variable, -1 = solo errores), y con
        setdefault -- quien la exporte a mano manda.

    SE PUEDE (Y SE DEBE) LLAMAR MAS DE UNA VEZ: `filterwarnings` mete el
    filtro DELANTE, asi que volver a llamarla recupera la prioridad cuando una
    libreria instala el suyo mas tarde -- que es justo lo que hace soundcard al
    importarse. Por eso la llama tambien '/grabar-clase iniciar'.

    Lo que NO se toca: cualquier otro aviso de esas mismas librerias sigue
    saliendo. Devuelve que se hizo para que se pueda comprobar.
    """
    import warnings
    try:
        warnings.filterwarnings(
            "ignore", message=r".*data discontinuity in recording.*")
        _RUIDO_LIBRERIAS["soundcard"] = True
    except Exception as exc:
        _aviso_degradado("cli.ruido",
                         f"no pude filtrar el aviso de soundcard: "
                         f"{type(exc).__name__}: {exc}")
    if not os.environ.get("CT2_VERBOSE"):
        os.environ["CT2_VERBOSE"] = "-1"
        _RUIDO_LIBRERIAS["ctranslate2"] = True
    return dict(_RUIDO_LIBRERIAS)


def _clases_jornada_viva(cmd: str):
    """La jornada viva, o None diciendo POR QUE no hay. Los subcomandos que
    apuntan algo en el minuto exacto de la clase la necesitan todos."""
    try:
        from cognia.clases import jornada as _cj
    except Exception as exc:
        _aviso_degradado("clases", f"modulo no importable: {exc}")
        return None
    jv = _cj.viva()
    if jv is None:
        lock = _cj.lock_actual()
        if lock.get("vivo") and lock.get("ajeno"):
            _print_line(f"[warn_cl]la grabacion la tiene OTRO proceso "
                        f"(PID {lock.get('pid')}, jornada "
                        f"{_escape(str(lock.get('jornada') or '?'))}): "
                        f"'{_escape(cmd)}' apunta en el minuto de la clase y "
                        f"eso se hace desde ese proceso[/warn_cl]")
            _print_line("[detail]/grabar-clase forzar  si sabes que ese PID ya "
                        "no es Cognia[/detail]")
            return None
        _print_line(f"[warn_cl]no hay jornada grabando: '{_escape(cmd)}' se "
                    f"apunta EN el minuto de la clase. Arranca con "
                    f"/grabar-clase iniciar[/warn_cl]")
    return jv


def _clases_materia_actual() -> str:
    """La materia sobre la que se escribe AHORA, o "" si no se sabe.

    Es lo que se le pasa a la familia doc_* al abrir el cuaderno. Se pregunta
    a `jornada.estado()` y NUNCA se adivina: '(sin clasificar aun)' no es una
    materia, y tomarla por buena crearia en el cuaderno del duenio un
    documento con ese nombre.
    """
    try:
        from cognia.agent import documento_tools as _dt
        sin_clasificar = _dt._MATERIA_SIN_CLASIFICAR
    except Exception:
        sin_clasificar = "(sin clasificar aun)"
    try:
        from cognia.clases import jornada as _cj
        est = _cj.estado()
    except Exception as exc:
        _aviso_degradado("clases", f"no pude leer el estado: "
                                   f"{type(exc).__name__}: {exc}")
        return ""
    if not est.get("grabando"):
        # La ultima jornada CERRADA devuelve la materia de la ultima clase del
        # dia: manana eso escribiria en el documento equivocado.
        return ""
    materia = str(est.get("materia") or "").strip()
    return "" if materia == sin_clasificar else materia


def _clases_encender_doc_tools(materia: str = "") -> dict:
    """Le ANUNCIA al modelo la familia doc_* -- y solo al abrir el cuaderno.

    ES EL CABLE QUE FALTABA. Las siete tools con las que la IA escribe en los
    apuntes existen desde que se registro la familia en harness/familias.py,
    pero nadie las encendia nunca: el flag COGNIA_DOC_TOOLS no lo pone ningun
    comando, asi que para el duenio no existian.

    Y se enciende AQUI y no siempre porque el catalogo tiene techo MEDIDO en
    este repo (A/B 2026-07-25, n=4+4: pasar de 14 a 46 tools baja el camino
    feliz de 4,25/5 a 2,5/5). Siete tools mas encendidas todo el rato le
    cuestan al modelo en TODAS las tareas; encendidas con el cuaderno abierto
    le cuestan solo mientras sirven.

    Devuelve el dict de familias.activar (o uno con ok=False y el motivo).
    """
    cfg = _load_config()
    if not _clases_encendido(cfg, "clases_doc_tools"):
        return {"ok": False, "familia": "documento",
                "detalle": "clases_doc_tools=off en la config: no anuncio las "
                           "tools doc_* (se enciende con /config set "
                           "clases_doc_tools on)"}
    if materia:
        try:
            from cognia.agent import documento_tools as _dt
            os.environ[_dt.ENV_MATERIA] = materia
            _marcar_env_sembrada(_dt.ENV_MATERIA)
        except Exception as exc:
            _aviso_degradado("clases.doc_tools",
                             f"no pude fijar la materia del documento: "
                             f"{type(exc).__name__}: {exc}")
    try:
        from cognia.harness import familias as _fam
        res = _fam.activar("documento")
    except Exception as exc:
        res = {"ok": False, "familia": "documento",
               "detalle": f"harness.familias no importable: "
                          f"{type(exc).__name__}: {exc}"}
    if not res.get("ok"):
        _aviso_degradado("clases.doc_tools", str(res.get("detalle") or ""))
    return res


def _clases_decir_doc_tools(res: dict) -> None:
    """Una linea con lo que quedo anunciado. Se imprime al abrir el cuaderno:
    que el modelo gane siete herramientas es un cambio de comportamiento y
    tiene que verse."""
    # info_dim y no detail (que el modo sencillo NO imprime): que el modelo
    # gane siete herramientas cambia como se comporta el agente en el turno
    # siguiente, y un cambio de comportamiento no puede ser invisible.
    if not res.get("ok"):
        detalle = str(res.get("detalle") or "")
        if detalle:
            _print_line(f"[info_dim]documento: {_escape(detalle)}[/info_dim]")
        return
    n = int(res.get("total") or 0)
    _print_line(f"[info_dim]el modelo ya puede escribir en los apuntes "
                f"({n} tools doc_*); se apaga con /config set "
                f"clases_doc_tools off[/info_dim]")


def _clases_adjuntar(jv, ruta, prefijo: str, texto: str, origen: str) -> str:
    """Copia un fichero recien generado DENTRO de la jornada y lo apunta en el
    minuto exacto. Devuelve el nombre del adjunto, o "" si no se pudo.

    Cuello de botella a proposito: formula, grafico, pegar e imagen-usar
    terminan todos igual (copiar + anotar), y tenerlo una sola vez es lo que
    hace que un adjunto nuevo no se olvide de anotarse -- el fallo que deja
    ficheros en la carpeta y el cuaderno mudo.
    """
    try:
        from cognia.clases import almacen as _ca
        from cognia.clases import cuaderno as _cc
    except Exception as exc:
        _aviso_degradado("clases", f"modulo no importable: {exc}")
        return ""
    try:
        nombre = _ca.copiar_adjunto(jv.nombre, ruta, prefijo=prefijo)
    except Exception as exc:
        _aviso_degradado(origen, f"no pude copiar {ruta} al cuaderno: "
                                 f"{type(exc).__name__}: {exc}")
        return ""
    try:
        jv.anotar(_cc.TIPO_IMAGEN, texto=texto, adjunto=nombre,
                  importante=True)
    except Exception as exc:
        _aviso_degradado(origen, f"el adjunto {nombre} se copio pero no pude "
                                 f"anotarlo: {type(exc).__name__}: {exc}")
        return ""
    return nombre


def _clases_tmp(nombre: str):
    """Un Path temporal para el PNG que despues se copia a la jornada.

    Se genera FUERA y se copia DENTRO (en vez de escribir directamente en
    adjuntos/) porque `almacen.copiar_adjunto` es quien numera y sanea el
    nombre; escribir a mano ahi duplicaria esa logica y es donde nacen los
    'img_3.png' pisados.
    """
    import tempfile
    from pathlib import Path as _P
    return _P(tempfile.mkdtemp(prefix="cognia_clase_")) / nombre


# -- widget / vivo / pdf ----------------------------------------------------

def _clases_widget(resto: str = "", ai=None) -> None:
    """`/grabar-clase widget`: enciende el cerebrito (el icono flotante).

    EN UN PROCESO APARTE, y no aqui dentro, porque el widget es una app tk con
    su propio mainloop: arrancarla en el hilo del REPL colgaria el prompt
    hasta que el duenio cerrara el icono.
    """
    try:
        from cognia.clases import widget as _wg
    except Exception as exc:
        _aviso_degradado("clases.widget", f"modulo no importable: {exc}")
        return
    try:
        lock = _wg.lock_widget_actual()
    except Exception as exc:
        _aviso_degradado("clases.widget",
                         f"no pude leer el lock del cerebrito: "
                         f"{type(exc).__name__}: {exc}")
        lock = {}
    if lock.get("vivo") and lock.get("ajeno"):
        _print_line(f"[warn_cl]ya hay un cerebrito abierto (PID "
                    f"{lock.get('pid')})[/warn_cl]")
        _print_line("[detail]cierralo desde su menu (Salir) antes de abrir "
                    "otro[/detail]")
        return
    cmd = [sys.executable, "-m", "cognia.clases"]
    kwargs = {"close_fds": True}
    if os.name == "nt":
        # DESACOPLADO: sin esto el cerebrito muere con el REPL, y el duenio
        # que cierra la terminal pierde el icono sin saber por que.
        kwargs["creationflags"] = (getattr(subprocess, "DETACHED_PROCESS", 0)
                                   | getattr(subprocess,
                                             "CREATE_NEW_PROCESS_GROUP", 0))
    else:
        kwargs["start_new_session"] = True
    try:
        proc = subprocess.Popen(cmd, **kwargs)
    except OSError as exc:
        _aviso_degradado("clases.widget",
                         f"no pude lanzar el cerebrito ({exc}); pruebalo a "
                         f"mano: {sys.executable} -m cognia.clases")
        return
    _clases_ok("cerebrito encendido",
               f"PID {proc.pid}; se arrastra con el raton y recuerda donde "
               f"lo dejaste")
    _print_line("[detail]clic en el icono -> menu (grabar / pausar / mutear / "
                "materia / ver cuaderno / salir)[/detail]")


def _clases_vivo(resto: str = "", ai=None) -> None:
    """`/grabar-clase vivo`: el cuaderno EN VIVO, en ventana propia.

    AQUI ESTA EL CABLE QUE FALTABA: `servidor_vivo.fijar_pagina(vista_viva.
    render)`. El transporte y la pagina son dos piezas a proposito -- el gancho
    existe para que el servidor pueda arrancar y probarse aunque la pagina
    reviente -- pero NADIE los unia, asi que `GET /` servia el placeholder del
    transporte y el cuaderno no se veia nunca.

    Subcomandos: sin nada arranca y abre; 'estado' diagnostica sin levantar
    nada; 'parar' lo apaga.
    """
    try:
        from cognia.clases import servidor_vivo as _sv
    except Exception as exc:
        _aviso_degradado("clases.servidor_vivo", f"no importable: {exc}")
        return
    orden = (resto or "").strip().lower()

    if orden in ("parar", "apagar", "off", "stop"):
        try:
            _sv.parar()
        except Exception as exc:
            _aviso_degradado("clases.servidor_vivo",
                             f"no pude apagarlo: {type(exc).__name__}: {exc}")
            return
        _print_line("[ok]cuaderno en vivo apagado[/ok]")
        return

    if orden in ("estado", "info"):
        try:
            est = _sv.estado()
        except Exception as exc:
            _aviso_degradado("clases.servidor_vivo",
                             f"no pude leer el estado: "
                             f"{type(exc).__name__}: {exc}")
            return
        filas = [("servidor", "VIVO" if est.get("vivo") else "apagado"),
                 ("puerto", str(est.get("puerto") or "-")),
                 ("pagina inyectada",
                  "si (el cuaderno)" if est.get("pagina_inyectada")
                  else "NO (se sirve el placeholder del transporte)"),
                 ("clientes mirando", str(est.get("clientes", 0))),
                 ("eventos enviados", str(est.get("enviados", 0))),
                 ("lentos desconectados",
                  str(est.get("desconectados_lentos", 0))),
                 ("se apaga solo tras", f"{est.get('inactividad_min', 0)} min "
                                        f"sin nadie"),
                 ("handshake", str(est.get("handshake") or "-"))]
        for k, v in filas:
            _print_line(f"  [mod]{k:<22}[/mod] {_escape(v)}")
        if est.get("vivo"):
            _print_line(f"[info_dim]{_escape(str(est.get('url') or ''))}"
                        f"[/info_dim]")
        for k in ("aviso",):
            if est.get(k):
                _print_line(f"[warn_cl]{_escape(str(est[k]))}[/warn_cl]")
        ult = est.get("ultimo_error") or {}
        if ult.get("motivo"):
            _print_line(f"[warn_cl]ultimo error: "
                        f"{_escape(str(ult.get('motivo')))}[/warn_cl]")
        return

    if orden:
        _print_line("[warn_cl]Uso: /grabar-clase vivo [estado | parar]"
                    "[/warn_cl]")
        return

    try:
        from cognia.clases import vista_viva as _vv
    except Exception as exc:
        _aviso_degradado("clases.vista_viva", f"no importable: {exc}")
        _print_line("[err_cl]sin la pagina, el servidor solo serviria el "
                    "placeholder del transporte[/err_cl]")
        return
    try:
        _sv.fijar_pagina(_vv.render)
    except Exception as exc:
        _aviso_degradado("clases.vista_viva",
                         f"el gancho de la pagina no se pudo fijar "
                         f"({type(exc).__name__}: {exc}): se serviria el "
                         f"placeholder")
        return
    try:
        info = _sv.arrancar()
    except Exception as exc:
        _aviso_degradado("clases.servidor_vivo",
                         f"no pude levantarlo: {type(exc).__name__}: {exc}")
        return

    _clases_ok(f"cuaderno en vivo "
               f"{'levantado' if info.get('nuevo') else 'ya estaba'}",
               f"puerto {info.get('puerto')}")
    _print_line(f"[info_dim]{_escape(str(info.get('url') or ''))}[/info_dim]")
    _print_line("[detail]la URL lleva el token: sin el, el servidor no "
                "contesta. /grabar-clase vivo parar para apagarlo[/detail]")

    _clases_decir_doc_tools(_clases_encender_doc_tools(_clases_materia_actual()))

    if not _abrir_en_navegador():
        _print_line("[detail]no abro ventana (sesion remota o "
                    "memorias_abrir_navegador=off): abre la URL a mano"
                    "[/detail]")
        return
    cfg = _load_config()
    if not _clases_encendido(cfg, "clases_vivo_app"):
        try:
            import webbrowser
            webbrowser.open(str(info.get("url") or ""))
        except Exception as exc:
            _aviso_degradado("clases.navegador",
                             f"no pude abrir el navegador "
                             f"({type(exc).__name__}: {exc}); la URL esta "
                             f"arriba")
        return
    try:
        from cognia.clases import widget as _wg
        ok, msg = _wg.abrir_en_app(str(info.get("url") or ""))
    except Exception as exc:
        _aviso_degradado("clases.navegador",
                         f"no pude abrir la ventana ({type(exc).__name__}: "
                         f"{exc}); la URL esta arriba")
        return
    if ok:
        _print_line(f"[detail]{_escape(str(msg))}[/detail]")
    else:
        _aviso_degradado("clases.navegador", str(msg))


def _clases_pdf(resto: str = "", ai=None) -> None:
    """`/grabar-clase pdf`: el cuaderno listo para Guardar como PDF.

    IMPRIMIR ES EL CAMINO UNIVERSAL A PDF y por eso no se genera el PDF aqui:
    hacerlo en Python exigiria un motor mas (reportlab o un Chromium
    headless), y la pagina del cuaderno YA trae su `@media print` -- se va
    todo lo que no es el documento y ningun bloque se parte entre dos hojas.
    Se exporta el cuaderno ESTATICO (imagenes embebidas en data:), que es el
    que se imprime igual sin servidor detras, se abre y se dice la tecla.
    """
    try:
        from cognia.clases import vista as _cv
    except Exception as exc:
        _aviso_degradado("clases.vista", f"no importable: {exc}")
        return
    destino = (resto or "").strip() or None
    try:
        ruta = _cv.export(path=destino, open_browser=_abrir_en_navegador())
    except Exception as exc:
        _aviso_degradado("clases.vista", f"{type(exc).__name__}: {exc}")
        _print_line("[err_cl]no pude generar el cuaderno para imprimir"
                    "[/err_cl]")
        return
    _clases_ok("cuaderno listo para imprimir", _escape(str(ruta)))
    # info_dim y no detail: ESTO es el comando. En modo sencillo (el default)
    # una linea con [detail] no se imprime, y 'pdf' se quedaria sin decir la
    # unica tecla que hay que pulsar.
    _print_line("[info_dim]en el navegador: Ctrl+P -> Destino 'Guardar como "
                "PDF'. La pagina ya se prepara sola para el papel[/info_dim]")
    if not _abrir_en_navegador():
        _print_line("[detail]no abro ventana (sesion remota o "
                    "memorias_abrir_navegador=off): abre el fichero a mano"
                    "[/detail]")


# -- pausar / reanudar / mutear / desmutear / forzar ------------------------

def _clases_interruptor(accion: str, etiquetas: tuple) -> None:
    """Las cuatro puertas de jornada que son un si/no (pausar, reanudar,
    mutear, desmutear) comparten forma: llamar, y distinguir "cambio" de "ya
    estaba asi". Decir "pausada" cuando ya lo estaba es lo que hace que el
    duenio pulse dos veces creyendo que no funciono."""
    try:
        from cognia.clases import jornada as _cj
    except Exception as exc:
        _aviso_degradado("clases", f"modulo no importable: {exc}")
        return
    try:
        res = getattr(_cj, accion)()
    except Exception as exc:
        _aviso_degradado(f"clases.jornada.{accion}",
                         f"{type(exc).__name__}: {exc}")
        return
    if not res.get("ok"):
        _print_line(f"[warn_cl]{_escape(str(res.get('motivo') or 'no se pudo'))}"
                    f"[/warn_cl]")
        return
    _print_line(f"[ok]{etiquetas[0]}[/ok]" if res.get("cambio")
                else f"[info_dim]{etiquetas[1]}[/info_dim]")


def _clases_pausar(resto: str = "", ai=None) -> None:
    """`/grabar-clase pausar`: deja de entrar audio, el reloj para y la
    jornada queda 'pausada' en disco (el olvido ya no la purga)."""
    _clases_interruptor("pausar", ("jornada PAUSADA: deja de entrar audio",
                                   "ya estaba pausada"))


def _clases_reanudar(resto: str = "", ai=None) -> None:
    """`/grabar-clase reanudar`. Si el micro seguia muteado, sigue muteado:
    son dos interruptores distintos."""
    _clases_interruptor("reanudar", ("grabando otra vez", "no estaba pausada"))


def _clases_mutear(resto: str = "", ai=None) -> None:
    """`/grabar-clase mutear`: descarta el audio SIN parar el reloj.

    Se dice la granularidad porque importa: la unidad es el TROZO de 30 s, no
    el segundo, asi que el corte real cae en el limite del trozo.
    """
    _clases_interruptor("mutear", ("micro MUTEADO: el audio se descarta y el "
                                   "reloj sigue", "ya estaba muteado"))
    _print_line("[detail]la unidad es el trozo de audio (~30 s): el corte cae "
                "en su limite, no en el segundo exacto[/detail]")


def _clases_desmutear(resto: str = "", ai=None) -> None:
    """`/grabar-clase desmutear`."""
    _clases_interruptor("desmutear", ("el audio vuelve a entrar",
                                      "no estaba muteado"))


def _clases_forzar(resto: str = "", ai=None) -> None:
    """`/grabar-clase forzar`: LA SALIDA DE EMERGENCIA del lock de grabacion.

    Existe porque los PID se reciclan: un lock olvidado cuyo numero hoy es de
    otro programa deja la grabacion bloqueada para siempre y sin ninguna forma
    de salir -- `_pid_vivo` responde VIVO tambien cuando no puede comprobar el
    proceso. El mensaje de "ya hay una grabacion" ya nombraba esta salida; sin
    el comando, el duenio se quedaba sin grabar y sin salida.

    NO se pone detras de un flag ni se hace automatico: robar el lock de una
    grabacion viva de verdad produce dos grabadores sobre la misma carpeta,
    asi que tiene que costar teclear algo.
    """
    try:
        from cognia.clases import jornada as _cj
    except Exception as exc:
        _aviso_degradado("clases", f"modulo no importable: {exc}")
        return
    if _cj.viva() is not None:
        _print_line("[warn_cl]la grabacion es de ESTE proceso: no hace falta "
                    "forzar nada, para con /grabar-clase parar[/warn_cl]")
        return
    motivo = (resto or "").strip() or "el duenio lo forzo desde el CLI"
    try:
        res = _cj.forzar_liberacion(motivo)
    except Exception as exc:
        _aviso_degradado("clases.jornada.forzar",
                         f"{type(exc).__name__}: {exc}")
        return
    lock = res.get("lock") or {}
    if not res.get("liberado"):
        _print_line(f"[info_dim]{_escape(str(res.get('aviso') or ''))}"
                    f"[/info_dim]")
        return
    _clases_ok("lock de grabacion liberado A LA FUERZA",
               f"era del PID {lock.get('pid') or 'ilegible'}, jornada "
               f"{_escape(str(lock.get('jornada') or '?'))}")
    if lock.get("vivo"):
        _print_line("[warn_cl]ese PID contestaba VIVO: si de verdad era otra "
                    "Cognia grabando, ahora hay dos grabadores sobre la misma "
                    "carpeta[/warn_cl]")
    _print_line("[detail]/grabar-clase iniciar  para grabar aqui[/detail]")


# -- refinado ---------------------------------------------------------------

def _clases_refinar(resto: str = "", ai=None) -> None:
    """`/grabar-clase refinar on|off|estado`: el refinado EN CALIENTE.

    'on' es lo UNICO que reabre un refinado que el disyuntor apago. El
    disyuntor lo apaga solo tras dos vueltas esteriles (~10 min sin backend) y
    la regla 11 de CLAUDE.md dice que solo una intervencion HUMANA resetea esa
    ventana: por eso encender es teclearlo y no un reintento automatico.
    """
    try:
        from cognia.clases import refinado as _cr
    except Exception as exc:
        _aviso_degradado("clases.refinado", f"no importable: {exc}")
        return
    orden = (resto or "").strip().lower()

    if orden in ("on", "off"):
        cfg = _load_config()
        cfg["clases_refinado"] = orden
        try:
            _save_config(cfg)
        except Exception as exc:
            _aviso_degradado("clases.refinado",
                             f"no pude guardar la config "
                             f"({type(exc).__name__}: {exc}): el cambio vale "
                             f"solo para esta sesion")
        os.environ[_cr.ENV_ACTIVO] = "1" if orden == "on" else "0"
        _marcar_env_sembrada(_cr.ENV_ACTIVO)
        _clases_ok(f"refinado en caliente: {orden}", "guardado en la config")
        if orden == "on":
            try:
                from cognia.clases import jornada as _cj
                jv = _cj.viva()
            except Exception as exc:
                _aviso_degradado("clases", f"no pude mirar la jornada viva: "
                                           f"{type(exc).__name__}: {exc}")
                jv = None
            if jv is not None:
                try:
                    res = _cr.encender(jv.nombre)
                except Exception as exc:
                    _aviso_degradado("clases.refinado",
                                     f"no pude reabrir el disyuntor: "
                                     f"{type(exc).__name__}: {exc}")
                    return
                if res.get("venia_apagado"):
                    _clases_ok("disyuntor del refinado reabierto",
                               f"lo habia apagado: "
                               f"{_escape(str(res['venia_apagado']))}")
        return

    if orden and orden not in ("estado", "info"):
        _print_line("[warn_cl]Uso: /grabar-clase refinar on|off|estado"
                    "[/warn_cl]")
        return

    try:
        est = _cr.estado()
    except Exception as exc:
        _aviso_degradado("clases.refinado",
                         f"no pude leer el estado: {type(exc).__name__}: {exc}")
        return
    # 'backend' es lo que devuelve llm_local.describir(): una CADENA
    # ("llama en http://127.0.0.1:8080"), no un dict. Se cazo tecleandolo
    # (AttributeError: 'str' object has no attribute 'get'), que es justo lo
    # que la suite no ve porque nadie ejecuta este render.
    filas = [("refinado", "ENCENDIDO" if est.get("activo") else "apagado"),
             ("cada", "%.0f s" % float(est.get("periodo") or 0.0)),
             ("tramo minimo", f"{est.get('min_tramo_chars', 0)} chars"),
             ("ventanas por vuelta", str(est.get("ventanas_por_vuelta", 0))),
             ("backend", str(est.get("backend") or "-"))]
    for k, v in filas:
        _print_line(f"  [mod]{k:<22}[/mod] {_escape(str(v))}")
    for nombre, j in (est.get("jornadas") or {}).items():
        _print_line(f"  [mod]{'jornada':<22}[/mod] {_escape(str(nombre))}: "
                    f"{j.get('vueltas', 0)} vueltas, "
                    f"{j.get('llamadas', 0)} llamadas, "
                    f"{j.get('aniadidos', 0)} anadidos, "
                    f"{j.get('esteriles', 0)} esteriles")
        if j.get("apagado"):
            _print_line(f"[warn_cl]APAGADO por el disyuntor: "
                        f"{_escape(str(j['apagado']))}[/warn_cl]")
            _print_line("[detail]/grabar-clase refinar on  lo reabre (es la "
                        "unica via)[/detail]")
        for a in (j.get("avisos") or [])[-3:]:
            _print_line(f"[warn_cl]{_escape(str(a))}[/warn_cl]")
    ult = est.get("ultimo_fallo") or {}
    if ult.get("motivo"):
        _print_line(f"[warn_cl]ultimo fallo: "
                    f"{_escape(str(ult.get('motivo')))}[/warn_cl]")


# -- mates: formula y grafico ----------------------------------------------

def _clases_dibujar(resto: str, cmd: str, prefijo: str, dibujar) -> None:
    """El tronco comun de `formula` y `grafico`: comprobar mates, dibujar el
    PNG, y meterlo en el cuaderno SI hay clase grabando.

    SIN JORNADA NO SE TIRA EL TRABAJO: el PNG ya esta hecho y se dice donde
    quedo. Negarse ahi seria perder una formula que el duenio acaba de
    teclear porque todavia no habia pulsado 'iniciar'.
    """
    if not resto:
        _print_line(f"[warn_cl]Uso: /grabar-clase {_escape(cmd)} <...>"
                    f"[/warn_cl]")
        return
    try:
        from cognia.clases import mates as _cm
    except Exception as exc:
        _aviso_degradado("clases.mates", f"no importable: {exc}")
        return
    ok, motivo = _cm.disponible()
    if not ok:
        _aviso_degradado("clases.mates", motivo)
        _print_line(f"[err_cl]{_escape(motivo)}[/err_cl]")
        return
    destino = _clases_tmp(prefijo + ".png")
    try:
        res = dibujar(_cm, destino)
    except _cm.ErrorDeMates as exc:
        # El mensaje de mates DICE donde esta el fallo (que caracter, que
        # tope): es lo unico util, asi que se ensenia entero.
        _print_line(f"[err_cl]{_escape(str(exc))}[/err_cl]")
        return
    except Exception as exc:
        _aviso_degradado("clases.mates", f"{type(exc).__name__}: {exc}")
        return
    for a in (res.get("avisos") or []):
        _print_line(f"[warn_cl]{_escape(str(a))}[/warn_cl]")
    try:
        from cognia.clases import jornada as _cj
        jv = _cj.viva()
    except Exception as exc:
        _aviso_degradado("clases", f"no pude mirar la jornada viva: "
                                   f"{type(exc).__name__}: {exc}")
        jv = None
    if jv is None:
        _clases_ok(f"{_escape(cmd)} dibujada en "
                   f"{_escape(str(res.get('ruta')))}",
                   f"{res.get('ancho_px')}x{res.get('alto_px')} px, "
                   f"{int(res.get('bytes') or 0) // 1024} KB")
        _print_line("[warn_cl]no hay jornada grabando: el PNG no entra al "
                    "cuaderno. /grabar-clase iniciar y vuelve a "
                    "teclearlo[/warn_cl]")
        return
    nombre = _clases_adjuntar(jv, res.get("ruta"), prefijo,
                              str(res.get("texto") or ""), "clases.mates")
    if not nombre:
        _print_line(f"[warn_cl]el PNG quedo en "
                    f"{_escape(str(res.get('ruta')))}[/warn_cl]")
        return
    _clases_ok(f"{_escape(cmd)} en el cuaderno ({_escape(nombre)})",
               f"{res.get('ancho_px')}x{res.get('alto_px')} px")


def _clases_formula(resto: str = "", ai=None) -> None:
    """`/grabar-clase formula <latex>`: la dibuja y la apunta en el minuto.

    Sin instalacion de LaTeX: la pinta `matplotlib.mathtext`.
    """
    latex = (resto or "").strip()
    _clases_dibujar(latex, "formula", "formula",
                    lambda _cm, destino: _cm.formula_a_png(latex, destino))


def _clases_numeros(texto: str):
    """(y, etiquetas) si `texto` es una serie de datos; (None, None) si es una
    expresion.

    LA DEDUCCION ES DEL CLI y no de mates a proposito: mates ya tiene la
    puerta unica `graficar(expresion=..., y=..., etiquetas=...)` y lo que
    falta aqui es traducir UNA linea tecleada a esos argumentos. Se acepta
    '3,5,8' (serie) y 'lunes=3, martes=5' (barras con etiqueta); cualquier
    otra cosa se manda como expresion, que es lo que hace que 'sin(x)*x'
    funcione sin que nadie escriba 'tipo='.
    """
    partes = [p.strip() for p in texto.split(",") if p.strip()]
    if len(partes) < 2:
        return None, None
    ys, etiquetas = [], []
    for p in partes:
        if "=" in p:
            etq, _, val = p.partition("=")
            etq, val = etq.strip(), val.strip()
        else:
            etq, val = "", p
        try:
            ys.append(float(val))
        except ValueError:
            return None, None
        etiquetas.append(etq)
    return ys, (etiquetas if all(etiquetas) else None)


def _clases_grafico(resto: str = "", ai=None) -> None:
    """`/grabar-clase grafico <expresion|datos>`: la grafica, al cuaderno.

    'sin(x)*x' dibuja la curva; '3,5,8' una linea de datos; 'lunes=3,
    martes=5' unas barras con su etiqueta.
    """
    texto = (resto or "").strip()
    ys, etiquetas = _clases_numeros(texto)

    def _dibuja(_cm, destino):
        if ys is None:
            return _cm.graficar(destino, expresion=texto)
        return _cm.graficar(destino, y=ys, etiquetas=etiquetas)

    _clases_dibujar(texto, "grafico", "grafica", _dibuja)


# -- imagenes: buscar, usar, pegar ------------------------------------------

def _clases_imagen_buscar(resto: str = "", ai=None) -> None:
    """`/grabar-clase imagen-buscar <consulta>`: imagenes REUTILIZABLES.

    Wikimedia Commons + Openverse, con autor y licencia en cada linea. No
    descarga nada: deja la lista numerada para `imagen-usar <n>`, que es lo
    que la baja CON su atribucion. Separarlo en dos pasos es lo que permite
    mirar la licencia antes de meter una foto en el cuaderno.
    """
    consulta = (resto or "").strip()
    if not consulta:
        _print_line("[warn_cl]Uso: /grabar-clase imagen-buscar <consulta>"
                    "[/warn_cl]")
        return
    try:
        from cognia import busqueda_imagenes as _bi
    except Exception as exc:
        _aviso_degradado("clases.imagenes", f"no importable: {exc}")
        return
    cfg = _load_config()
    crudo = str(cfg.get("clases_imagenes", "8")).strip()
    if crudo.isdigit() and int(crudo) > 0:
        n = int(crudo)
    else:
        n = 8
        _aviso_degradado("clases.config",
                         f"clases_imagenes={crudo!r} no es un entero > 0; "
                         f"uso 8")
    _print_line(f"[detail]buscando '{_escape(consulta)}' en Commons y "
                f"Openverse...[/detail]")
    try:
        resultados, avisos = _bi.buscar_con_avisos(consulta, n)
    except _bi.ErrorBusquedaImagenes as exc:
        _aviso_degradado("clases.imagenes", str(exc))
        _print_line(f"[err_cl]{_escape(str(exc))}[/err_cl]")
        return
    except Exception as exc:
        _aviso_degradado("clases.imagenes", f"{type(exc).__name__}: {exc}")
        return
    for a in avisos:
        _print_line(f"[warn_cl]{_escape(str(a))}[/warn_cl]")
    _CLASES_BUSQUEDA["consulta"] = consulta
    _CLASES_BUSQUEDA["resultados"] = list(resultados)
    if not resultados:
        _print_line("[info_dim]ninguna imagen reutilizable para esa consulta"
                    "[/info_dim]")
        return
    # NI UNA sola marca [detail] en estas dos lineas: `_print_line` tira la
    # linea ENTERA si la lleva y el modo sencillo es el default, asi que la
    # lista de resultados desaparecia y el comando no contestaba nada. Cazado
    # tecleando '/grabar-clase imagen-buscar celula animal': salida VACIA.
    for i, r in enumerate(resultados, 1):
        marca = "" if r.get("atribucion_completa") else "  [SIN AUTOR]"
        _print_line(f"  [mod]{i:>2}.[/mod] "
                    f"{_escape(str(r.get('titulo') or ''))}  "
                    f"({r.get('ancho')}x{r.get('alto')}, "
                    f"{_escape(str(r.get('fuente') or ''))}){_escape(marca)}")
        _print_line(f"      {_escape(str(r.get('autor') or '(sin autor)'))}"
                    f" - {_escape(str(r.get('licencia') or '(sin licencia)'))}")
    _print_line(f"[info_dim]/grabar-clase imagen-usar <1-{len(resultados)}>  "
                f"la baja al cuaderno con su atribucion[/info_dim]")


def _clases_imagen_usar(resto: str = "", ai=None) -> None:
    """`/grabar-clase imagen-usar <n>`: baja la n-esima y la apunta CON su
    atribucion.

    La atribucion viaja como el TEXTO de la entrada del cuaderno (la linea ya
    la redacta busqueda_imagenes: titulo - autor - licencia - url): una imagen
    con licencia CC que acaba en un cuaderno sin credito es exactamente lo que
    la licencia prohibe, y adjuntarla sin el texto lo haria en silencio.
    """
    crudo = (resto or "").strip()
    resultados = _CLASES_BUSQUEDA["resultados"]
    if not resultados:
        _print_line("[warn_cl]no hay ninguna busqueda en esta sesion: "
                    "/grabar-clase imagen-buscar <consulta> primero[/warn_cl]")
        return
    if not crudo.isdigit() or not (1 <= int(crudo) <= len(resultados)):
        _print_line(f"[warn_cl]Uso: /grabar-clase imagen-usar <1-"
                    f"{len(resultados)}>  (de la busqueda "
                    f"'{_escape(str(_CLASES_BUSQUEDA['consulta']))}')"
                    f"[/warn_cl]")
        return
    elegida = resultados[int(crudo) - 1]
    jv = _clases_jornada_viva("imagen-usar")
    if jv is None:
        return
    try:
        from cognia.clases import almacen as _ca
        from cognia.clases import cuaderno as _cc
    except Exception as exc:
        _aviso_degradado("clases", f"modulo no importable: {exc}")
        return
    _print_line(f"[detail]bajando {_escape(str(elegida.get('titulo') or ''))}"
                f"...[/detail]")
    try:
        nombre = _ca.descargar_adjunto(jv.nombre,
                                       str(elegida.get("url_imagen") or ""),
                                       prefijo="img")
    except Exception as exc:
        _aviso_degradado("clases.imagenes",
                         f"no pude bajar la imagen: {type(exc).__name__}: "
                         f"{exc}")
        return
    atribucion = str(elegida.get("atribucion") or "")
    try:
        jv.anotar(_cc.TIPO_IMAGEN, texto=atribucion, adjunto=nombre,
                  importante=True)
    except Exception as exc:
        _aviso_degradado("clases.imagenes",
                         f"la imagen {nombre} se bajo pero no pude anotarla: "
                         f"{type(exc).__name__}: {exc}")
        return
    _clases_ok(f"imagen en el cuaderno ({_escape(nombre)})")
    _print_line(f"  [mod]{'credito':<16}[/mod] {_escape(atribucion)}")
    if not elegida.get("atribucion_completa"):
        _print_line("[warn_cl]esta imagen no trae autor o licencia completos: "
                    "revisa la pagina de origen antes de publicarla[/warn_cl]")


def _clases_pegar(resto: str = "", ai=None) -> None:
    """`/grabar-clase pegar`: la imagen del portapapeles, al cuaderno.

    Es el gesto real de una clase: recortar la pizarra con Win+Shift+S y
    pegar. Sin esto habria que guardar el recorte a un fichero y teclear su
    ruta, que es justo el paso donde se abandona.

    PIL.ImageGrab existe en Windows y macOS; en Linux depende de que haya
    xclip/wl-paste. Se dice en vez de callarse: 'el portapapeles no trae una
    imagen' y 'aqui no hay portapapeles' son dos arreglos distintos.
    """
    jv = _clases_jornada_viva("pegar")
    if jv is None:
        return
    try:
        from PIL import ImageGrab
    except Exception as exc:
        _aviso_degradado("clases.pegar",
                         f"PIL.ImageGrab no disponible ({type(exc).__name__}: "
                         f"{exc}); instala pillow")
        return
    try:
        dato = ImageGrab.grabclipboard()
    except Exception as exc:
        # En Linux sin xclip/wl-paste esto lanza; el mensaje dice que instalar.
        _aviso_degradado("clases.pegar",
                         f"no pude leer el portapapeles ({type(exc).__name__}: "
                         f"{exc}); en Linux hace falta xclip o wl-clipboard")
        return
    if isinstance(dato, list):
        # Copiar un FICHERO de imagen en el explorador da la lista de rutas.
        rutas = [str(p) for p in dato if str(p).strip()]
        if not rutas:
            _print_line("[warn_cl]el portapapeles trae una lista vacia"
                        "[/warn_cl]")
            return
        origen = rutas[0]
    elif dato is None:
        _print_line("[warn_cl]el portapapeles no trae ninguna imagen "
                    "(copia una con Win+Shift+S y vuelve a teclearlo)"
                    "[/warn_cl]")
        return
    else:
        origen = _clases_tmp("pegada.png")
        try:
            dato.convert("RGB").save(str(origen), format="PNG")
        except Exception as exc:
            _aviso_degradado("clases.pegar",
                             f"no pude guardar la imagen pegada: "
                             f"{type(exc).__name__}: {exc}")
            return
    nombre = _clases_adjuntar(jv, origen, "pegada", "imagen pegada",
                              "clases.pegar")
    if not nombre:
        return
    _clases_ok(f"imagen pegada en el cuaderno ({_escape(nombre)})")


# -- documento --------------------------------------------------------------

def _clases_doc(resto: str = "", ai=None) -> None:
    """`/grabar-clase doc estado`: el diagnostico del documento de bloques.

    Es la puerta que CLAUDE.md exige para una capa sin uso directo: dice que
    documentos hay, cuantos bloques y cuantos fijados, cuanto diario lleva sin
    compactar, cuantos bloques escribio la IA y cuantos RESPETO por estar
    fijados -- y si las tools doc_* estan anunciadas ahora mismo.
    """
    orden = (resto or "").strip()
    partes = orden.split(None, 1)
    sub = partes[0].lower() if partes else "estado"
    materia = partes[1].strip() if len(partes) > 1 else ""
    if sub not in ("estado", "info"):
        # `doc <materia>` es lo que teclea quien no lee la ayuda: se acepta.
        materia = orden
        sub = "estado"
    try:
        from cognia.clases import documento as _cd
    except Exception as exc:
        _aviso_degradado("clases.documento", f"no importable: {exc}")
        return
    try:
        est = _cd.estado(materia or None)
    except Exception as exc:
        _aviso_degradado("clases.documento", f"{type(exc).__name__}: {exc}")
        return
    docs = est.get("documentos") or []
    _print_line(f"  [mod]{'raiz':<22}[/mod] {_escape(str(est.get('raiz','')))}")
    _print_line(f"  [mod]{'documentos':<22}[/mod] "
                f"{_escape(', '.join(str(d) for d in docs) or '(ninguno)')}")
    if materia:
        filas = [("materia", str(est.get("materia", ""))),
                 ("bloques", str(est.get("bloques", 0))),
                 ("fijados (del duenio)", str(est.get("fijados", 0))),
                 ("escritos por la IA", str(est.get("de_la_ia", 0))),
                 ("respetados", str(est.get("respetados", 0))),
                 ("ops sin compactar",
                  f"{est.get('ops_sin_compactar', 0)} de "
                  f"{est.get('ops_por_instantanea', 0)}")]
        for k, v in filas:
            _print_line(f"  [mod]{k:<22}[/mod] {_escape(v)}")
        for a in (est.get("avisos") or [])[-3:]:
            _print_line(f"[warn_cl]{_escape(str(a))}[/warn_cl]")
    elif docs:
        _print_line("[detail]/grabar-clase doc estado <materia>  para el "
                    "detalle de uno[/detail]")
    try:
        from cognia.agent.tools import TOOLS as _T
        anunciadas = sorted(t for t in _T if t.startswith("doc_"))
    except Exception as exc:
        _aviso_degradado("clases.doc_tools",
                         f"no pude leer el registro de tools: "
                         f"{type(exc).__name__}: {exc}")
        anunciadas = []
    encendida = (os.environ.get("COGNIA_DOC_TOOLS", "").strip().lower()
                 in _CLASES_SI)
    _print_line(f"  [mod]{'tools doc_*':<22}[/mod] "
                f"{len(anunciadas)} cargadas, "
                f"{'ANUNCIADAS' if encendida else 'no anunciadas'}")
    _print_line(f"  [mod]{'materia del modelo':<22}[/mod] "
                f"{_escape(os.environ.get('COGNIA_DOC_MATERIA', '') or '(la de la jornada viva)')}")
    ult = est.get("ultimo_fallo") or {}
    if ult.get("motivo"):
        _print_line(f"[warn_cl]ultimo fallo: "
                    f"{_escape(str(ult.get('motivo')))}[/warn_cl]")
    if not encendida:
        _print_line("[detail]se encienden solas al abrir el cuaderno "
                    "(/grabar-clase ver | vivo)[/detail]")


# -- parar: EL CIERRE EN DOS FASES -----------------------------------------
# LO URGENTE Y LO CARO NO SON LO MISMO, y meterlos en el mismo turno dejaba el
# REPL mudo durante minutos: medido por el verificador 4 veces sobre jornadas
# de 35-90 s, 3 de 4 NO devolvieron el prompt (>300 s, >420 s, >165 s: hubo que
# matar el proceso). `jornada.parar()` hace cuatro cosas seguidas -- para la
# captura, vacia la transcripcion pendiente, detecta las materias DEFINITIVAS y
# genera los apuntes -- y las dos ultimas hablan con el modelo local: minutos,
# y si el server esta ocupado cada llamada se come el timeout de 152 s.
#
# LAS DOS FASES:
#   1) URGENTE (en el turno): que deje de ENTRAR AUDIO. Cuando
#      `jv.grabador.viva` pasa a False, la captura solto sus hilos y todos los
#      trozos estan escritos (captura.Grabador escribe cada trozo al
#      cerrarlo). Ahi se dice lo que ya esta hecho y el prompt VUELVE.
#   2) CARO (en un hilo daemon): vaciar la transcripcion pendiente, cortes
#      definitivos, refinado y apuntes. Todo eso solo AGREGA sobre el audio ya
#      guardado; si Cognia muere en medio, la clase sigue estando y se
#      completa tecleando '/grabar-clase transcribir' y '/grabar-clase
#      apuntes'.
#
# LA FRONTERA ESTA MEDIDA, no elegida a ojo. Con la fase 1 esperando a que se
# vaciara TAMBIEN la transcripcion (`jv.viva`), una jornada real de 40 s
# devolvia el prompt a los 30,01 s: whisper carga su modelo y transcribe los
# trozos pendientes, y su propio join se da 120 s. Eso es otra vez un REPL
# secuestrado. El audio, en cambio, para en decimas.
#
# POR QUE ESTE CARRIL Y NO `_lanzar_en_fondo`. El repo tiene dos carriles de
# fondo. El del agente (`_lanzar_en_fondo`) es hilo + prompt de espera con el
# teclado vivo: sirve cuando el duenio ESPERA el resultado del turno, porque lo
# que teclea mientras tanto se ANOTA en cola y no se ejecuta. Aqui no vale --
# el duenio acaba de dar la clase y tiene que poder seguir usando Cognia. El
# otro es el de las rutinas (`_arrancar_carril_rutinas`): hilo daemon que
# trabaja solo y deja lo suyo en una cola que el REPL DRENA ENTRE TURNOS, justo
# antes de pedir la linea siguiente. Ese es el que encaja, y por la misma razon
# que alli: imprimir DESDE el hilo pisa la linea a medio teclear.
#
# CTRL-C corta LA ESPERA, no el cierre: el hilo sigue y termina de escribir.
# Matarlo a media escritura es lo unico que podria corromper el cuaderno, y no
# hay forma de pedirlo desde aqui.
#
# LO QUE CUESTA (dicho, no escondido): mientras el hilo genera los apuntes usa
# el UNICO slot del backend local, asi que un chat tecleado en ese rato compite
# con el. Es el mismo trato que ya acepta el carril de las rutinas, y es
# preferible a un REPL secuestrado: el trabajo se ve, se consulta y no bloquea.

# Tope de la fase 1, MEDIDO en una jornada real (no elegido a ojo):
#   * esperar a la transcripcion (`jv.viva`)      -> el prompt volvia a 30,01 s
#   * esperar al grabador (`jv.grabador.viva`)    -> volvia a 10,02 s
#   * con este tope                               -> vuelve a ~2,5 s
# Los 10 s son el join de `captura.Grabador.parar`: su hilo esta dentro de
# `rec.record(numframes=30 s)` y no mira la senal de parada hasta que el trozo
# se llena, asi que el join se agota entero. Esperarle es esperar POR NADA: la
# senal ya esta puesta desde el primer instante de `jornada.parar()`, el bucle
# de captura no empieza ningun trozo mas (`while not self._parar.is_set()`) y
# el que estuviera a medias se escribe igual cuando `record()` devuelve. Por
# eso el tope es corto y el mensaje dice exactamente eso, sin prometer de mas.
_CLASES_ESPERA_CAPTURA_S = 2.5

# El cierre en curso (o el ultimo de esta sesion). Vive en un dict de modulo,
# como `_CLASES_BUSQUEDA`, porque es estado de ESTA sesion: el cierre de ayer
# no dice nada de lo que hay que mirar hoy.
_CLASES_CIERRE = {"jornada": "", "hilo": None, "jv": None, "t0": 0.0,
                  "t_captura": 0.0, "t_fin": 0.0, "resumen": None,
                  "error": "", "inline": False}

# Lo que el hilo del cierre deja dicho para que lo imprima el REPL entre
# turnos (mismo patron que `_COLA_RUTINAS`).
_CLASES_CIERRE_AVISOS: list = []


def _clases_cierre_vivo() -> bool:
    """True mientras el hilo del cierre sigue trabajando."""
    hilo = _CLASES_CIERRE.get("hilo")
    return hilo is not None and hilo.is_alive()


def _clases_captura_viva(jv) -> bool:
    """True mientras el grabador todavia tiene hilos de audio vivos.

    ES EL MILESTONE DE LA FASE URGENTE. Cuando esto es False ya no entra audio
    y los trozos estan escritos; lo que quede (transcribir, materias, apuntes)
    solo agrega. Se mira el GRABADOR y no `jv.viva` -- que es grabador O
    transcripcion -- porque la transcripcion pendiente tarda decenas de
    segundos (whisper) y esperarla devolvia el prompt a los 30 s en una
    jornada real de 40 s.
    """
    return bool(getattr(getattr(jv, "grabador", None), "viva", False))


def _clases_cierre_fase() -> str:
    """En que anda el cierre AHORA, deducido de lo OBSERVABLE.

    No se le mete un canal de progreso a `jornada.parar()`: el orden de sus
    pasos es su contrato y ese fichero no es este. La fase se lee de `jv.viva`,
    que es exactamente lo que distingue "todavia vacia la transcripcion" de
    "ya esta hablando con el modelo".
    """
    if not _CLASES_CIERRE.get("hilo") and not _CLASES_CIERRE.get("inline"):
        return ""
    if _clases_cierre_vivo():
        jv = _CLASES_CIERRE.get("jv")
        if _clases_captura_viva(jv):
            return "cerrando la captura de audio"
        if jv is not None and getattr(jv, "viva", False):
            return "transcribiendo lo que quedo pendiente"
        return "detectando materias y generando apuntes (habla con el modelo)"
    return "fallo" if _CLASES_CIERRE.get("error") else "terminado"


def _clases_hay_carril() -> bool:
    """True si conviene mandar el cierre a un hilo. DOS condiciones:

      * que exista carril de fondo (`_sin_carril()`: hay PromptSession y no
        esta puesto COGNIA_SIN_FONDO=1);
      * y que la sesion sea INTERACTIVA de verdad (stdin es una consola).

    LA SEGUNDA LA ENSENIO EL TECLEADO. Con la entrada por pipe (un guion,
    `echo ... | cognia`, el CI) prompt_toolkit SI logra crear la PromptSession
    en esta maquina, asi que `_sin_carril()` decia que habia carril: el cierre
    se fue al hilo, el guion siguio hasta '/salir' y el proceso salio con el
    hilo daemon a medias -- la jornada se quedo SIN apuntes. Un guion no tiene
    a quien devolverle el prompt: ahi el cierre se hace en el turno.
    """
    if _sin_carril():
        return False
    try:
        return bool(sys.stdin.isatty())
    except Exception as exc:
        _aviso_degradado("clases.cierre",
                         f"no pude saber si hay consola "
                         f"({type(exc).__name__}: {exc}); cierro en el turno")
        return False


def _clases_esperar_cierre_al_salir(tope_s: float = 180.0) -> None:
    """Antes de cerrar Cognia, ESPERAR al cierre que quedo en el hilo.

    El hilo del cierre es daemon: si el proceso termina, muere en el acto y la
    jornada se queda sin apuntes. MEDIDO tecleando un guion entero: el REPL
    llego a '/salir' con el cierre en marcha y salio, y los apuntes no se
    generaron nunca.

    Es una espera CON TOPE y cortable con Ctrl-C, no una carcel: lo urgente ya
    esta en disco y nadie tiene que quedarse preso de su portatil por unos
    apuntes. Lo que no se puede es irse en SILENCIO, que es el modo de fallo
    historico de la casa.
    """
    if not _clases_cierre_vivo():
        _clases_cierre_drenar()
        return
    _print_line(f"[warn_cl]todavia se esta cerrando la jornada "
                f"{_escape(str(_CLASES_CIERRE.get('jornada') or ''))}: "
                f"{_escape(_clases_cierre_fase())}[/warn_cl]")
    _print_line("[info_dim]el audio ya esta en disco; esto son los apuntes. "
                "Ctrl-C para salir ya (se completan luego con /grabar-clase "
                "apuntes)[/info_dim]")
    hilo = _CLASES_CIERRE.get("hilo")
    try:
        hilo.join(timeout=tope_s)
    except KeyboardInterrupt:
        _print_line("[warn_cl]salida forzada: los apuntes quedan a medias. "
                    "/grabar-clase apuntes los regenera[/warn_cl]")
        return
    if hilo.is_alive():
        _aviso_degradado("clases.cierre",
                         f"el cierre seguia despues de {tope_s:.0f} s: salgo "
                         f"igual, el audio y la transcripcion estan en disco y "
                         f"'/grabar-clase apuntes' completa la jornada")
        return
    _clases_cierre_drenar()


def _clases_cierre_correr(parar_fn) -> None:
    """El cuerpo del hilo del cierre. NO imprime nada: ENCOLA.

    Imprimir desde aqui pisaria la linea que el duenio esta tecleando (es la
    razon por la que el carril de las rutinas tampoco imprime). Y no muere
    mudo: si `parar()` revienta, el motivo viaja en la cola y sale por
    `_aviso_degradado` desde el hilo principal.
    """
    est = _CLASES_CIERRE
    try:
        est["resumen"] = parar_fn() or {}
    except BaseException as exc:      # noqa: BLE001 -- el hilo no muere mudo
        est["error"] = f"{type(exc).__name__}: {exc}"
    finally:
        est["t_fin"] = time.time()
        _CLASES_CIERRE_AVISOS.append(
            {"jornada": est.get("jornada", ""),
             "resumen": est.get("resumen") or {},
             "error": est.get("error", ""),
             "segundos": max(0.0, est["t_fin"]
                             - float(est.get("t0") or est["t_fin"]))})


def _clases_cierre_pintar(aviso: dict) -> None:
    """El parte FINAL del cierre: lo mismo que imprimia `parar` cuando lo hacia
    todo dentro del turno, pero cuando de verdad esta hecho."""
    jornada = str(aviso.get("jornada") or "")
    if aviso.get("error"):
        _print_line(f"[err_cl]el cierre de la jornada {_escape(jornada)} "
                    f"fallo[/err_cl]")
        _aviso_degradado("clases.cierre", str(aviso.get("error") or ""))
        _print_line("[info_dim]lo grabado NO se pierde: /grabar-clase apuntes "
                    "regenera los apuntes de esa jornada[/info_dim]")
        return
    res = aviso.get("resumen") or {}
    materias, sesiones = "-", 0
    try:
        from cognia.clases import cuaderno as _cc
        ses = _cc.sesiones_de(jornada)
        sesiones = len(ses)
        materias = ", ".join(sorted({s.materia for s in ses})) or "-"
    except Exception as exc:
        _aviso_degradado("clases.cuaderno",
                         f"no pude leer las sesiones de {jornada}: "
                         f"{type(exc).__name__}: {exc}")
    mins = int(float(res.get("segundos") or 0.0) // 60)
    _clases_ok(f"jornada {_escape(jornada)} cerrada del todo",
               f"el cierre tardo {int(aviso.get('segundos') or 0)} s")
    _print_line(f"  [mod]{'duracion':<22}[/mod] {mins} min")
    _print_line(f"  [mod]{'materias':<22}[/mod] {_escape(materias)}")
    _print_line(f"  [mod]{'sesiones':<22}[/mod] {sesiones}")
    for a in (res.get("avisos") or [])[-3:]:
        _print_line(f"[warn_cl]{_escape(str(a))}[/warn_cl]")
    _print_line("[info_dim]/grabar-clase ver  para abrir el cuaderno"
                "[/info_dim]")


def _clases_cierre_drenar() -> None:
    """Lo que dejo dicho el hilo del cierre, impreso ENTRE TURNOS.

    Lo llama el bucle del REPL justo antes de pedir la linea siguiente, en el
    mismo sitio y por la misma razon que el drenaje de las rutinas: desde el
    hilo, cada linea pisaria el prompt a medio teclear.
    """
    while _CLASES_CIERRE_AVISOS:
        _clases_cierre_pintar(_CLASES_CIERRE_AVISOS.pop(0))


def _clases_parar(resto: str = "", ai=None) -> None:
    """`/grabar-clase parar`: DEJA DE GRABAR ya, y lo caro va detras.

    Devuelve el prompt en cuanto el audio y la transcripcion estan a salvo en
    disco; la deteccion definitiva de materias y los apuntes siguen en un hilo
    daemon que se consulta con `/grabar-clase cierre` y que anuncia el final
    entre dos turnos. Ver el comentario grande de arriba: por que dos fases,
    por que este carril y no el del agente, y que garantiza cada una.
    """
    try:
        from cognia.clases import jornada as _cj
    except Exception as exc:
        _aviso_degradado("clases", f"modulo no importable: {exc}")
        return
    if _clases_cierre_vivo():
        _print_line(f"[warn_cl]ya se esta cerrando la jornada "
                    f"{_escape(str(_CLASES_CIERRE.get('jornada') or ''))}: "
                    f"{_escape(_clases_cierre_fase())}[/warn_cl]")
        _print_line("[info_dim]/grabar-clase cierre  para ver como va"
                    "[/info_dim]")
        return
    jv = _cj.viva()
    if jv is None:
        _print_line("[warn_cl]no hay ninguna jornada grabando[/warn_cl]")
        _clases_cierre_drenar()
        return
    nombre = str(getattr(jv, "nombre", "") or "")
    _CLASES_CIERRE.update({"jornada": nombre, "jv": jv, "hilo": None,
                           "t0": time.time(), "t_captura": 0.0, "t_fin": 0.0,
                           "resumen": None, "error": "", "inline": False})

    if not _clases_hay_carril():
        # Sin consola interactiva (pipes, CI, scripts) el hilo seria una
        # TRAMPA: el proceso terminaria antes que el y los apuntes no se
        # generarian nunca. Ahi se cierra INLINE, que es el camino de siempre.
        # COGNIA_SIN_FONDO=1 fuerza esta rama (el brazo de control del repo).
        _CLASES_CIERRE["inline"] = True
        _print_line("[info_dim]cerrando: transcribo lo pendiente, detecto "
                    "materias y genero apuntes (sin carril de fondo: esto "
                    "tarda minutos)[/info_dim]")
        _clases_cierre_correr(_cj.parar)
        _clases_cierre_drenar()
        return

    hilo = threading.Thread(target=_clases_cierre_correr, args=(_cj.parar,),
                            name="cognia-clases-cierre", daemon=True)
    _CLASES_CIERRE["hilo"] = hilo
    try:
        hilo.start()
    except RuntimeError as exc:
        # Sin hilo no hay carril: se cierra aqui mismo (lento, pero la jornada
        # se cierra) y se DICE, que es lo contrario de quedarse mudo.
        _CLASES_CIERRE["hilo"] = None
        _CLASES_CIERRE["inline"] = True
        _aviso_degradado("clases.cierre",
                         f"no pude lanzar el hilo del cierre "
                         f"({type(exc).__name__}: {exc}); cierro en el turno")
        _clases_cierre_correr(_cj.parar)
        _clases_cierre_drenar()
        return

    cortado = False
    t0 = time.time()
    try:
        while hilo.is_alive() and _clases_captura_viva(jv):
            if time.time() - t0 > _CLASES_ESPERA_CAPTURA_S:
                break
            time.sleep(0.05)
    except KeyboardInterrupt:
        cortado = True
    _CLASES_CIERRE["t_captura"] = time.time() - t0

    if not _clases_captura_viva(jv):
        _clases_ok(f"grabacion cerrada: ya no entra audio y la jornada "
                   f"{_escape(nombre)} esta en disco",
                   f"la captura paro en {_CLASES_CIERRE['t_captura']:.1f} s; "
                   f"la transcripcion pendiente y los apuntes van detras")
    else:
        # Ni un warn ni una promesa de mas: esto es lo que se sabe con
        # certeza. La senal de parada esta puesta, el bucle de captura no
        # empieza ningun trozo nuevo y el que estuviera a medias se guarda
        # cuando su record() devuelva (hasta 30 s, el tamanio del trozo).
        _clases_ok(f"grabacion cortada: la jornada {_escape(nombre)} no "
                   f"recibe mas audio",
                   f"el trozo en vuelo (hasta 30 s) se guarda solo al "
                   f"cerrarse; lo anterior ya esta en disco")
    if cortado:
        _print_line("[info_dim]Ctrl-C corta la ESPERA, no el cierre: el hilo "
                    "termina de escribir (matarlo a medias es lo unico que "
                    "podria corromper el cuaderno)[/info_dim]")
    if _clases_cierre_vivo():
        _print_line(f"[info_dim]sigue en segundo plano: "
                    f"{_escape(_clases_cierre_fase())}. El prompt es tuyo; "
                    f"/grabar-clase cierre  dice como va[/info_dim]")
    else:
        _clases_cierre_drenar()


def _clases_cierre(resto: str = "", ai=None) -> None:
    """`/grabar-clase cierre`: como va el cierre de la ultima jornada.

    La puerta que exige CLAUDE.md para el trabajo que ya no ocurre delante del
    duenio: en que fase esta, cuanto lleva y -- lo que de verdad se pregunta a
    los cinco minutos -- si su clase ya esta guardada.
    """
    _clases_cierre_drenar()          # si acabo mientras tanto, se dice aqui
    est = _CLASES_CIERRE
    fase = _clases_cierre_fase()
    if not fase:
        _print_line("[info_dim]ningun cierre en curso ni reciente en esta "
                    "sesion[/info_dim]")
        _print_line("[detail]/grabar-clase parar  cierra la jornada que este "
                    "grabando[/detail]")
        return
    lleva = ((est["t_fin"] if est.get("t_fin") else time.time())
             - float(est.get("t0") or 0.0))
    a_salvo = "cerrando" if _clases_captura_viva(est.get("jv")) else "SI"
    filas = [("jornada", str(est.get("jornada") or "")),
             ("fase", fase),
             ("lleva", "%d min %02d s" % (int(lleva) // 60, int(lleva) % 60)),
             ("audio en disco", a_salvo),
             ("carril", "en el turno (sin carril de fondo)"
                        if est.get("inline") else "hilo de fondo")]
    for k, v in filas:
        _print_line(f"  [mod]{k:<22}[/mod] {_escape(str(v))}")
    if est.get("error"):
        _print_line(f"[err_cl]{_escape(str(est['error']))}[/err_cl]")
        _print_line("[info_dim]lo grabado NO se pierde: /grabar-clase apuntes"
                    "[/info_dim]")
        return
    if _clases_cierre_vivo():
        _print_line("[info_dim]tu clase YA esta guardada (el audio esta en "
                    "disco): lo que falta solo agrega texto y apuntes"
                    "[/info_dim]")
    else:
        _print_line("[info_dim]terminado: /grabar-clase ver  abre el cuaderno"
                    "[/info_dim]")


# EL PUNTO DE EXTENSION. Un subcomando nuevo = una funcion `_clases_x(resto,
# ai)` y una linea aqui. Los alias van al lado de su nombre canonico para que
# se vea de un vistazo que 'grafica' y 'grafico' son lo mismo.
_CLASES_SUBCOMANDOS = {
    "parar": _clases_parar,
    "fin": _clases_parar,
    "stop": _clases_parar,
    "off": _clases_parar,
    "cierre": _clases_cierre,
    "widget": _clases_widget,
    "cerebrito": _clases_widget,
    "vivo": _clases_vivo,
    "pausar": _clases_pausar,
    "reanudar": _clases_reanudar,
    "mutear": _clases_mutear,
    "desmutear": _clases_desmutear,
    "forzar": _clases_forzar,
    "refinar": _clases_refinar,
    "refinado": _clases_refinar,
    "formula": _clases_formula,
    "grafico": _clases_grafico,
    "grafica": _clases_grafico,
    "imagen-buscar": _clases_imagen_buscar,
    "imagen-usar": _clases_imagen_usar,
    "pegar": _clases_pegar,
    "pdf": _clases_pdf,
    "imprimir": _clases_pdf,
    "doc": _clases_doc,
}


def _slash_grabar_clase(arg: str = "", ai=None) -> None:
    """`/grabar-clase`: puerta del CUADERNO DE CLASE (paquete cognia/clases).

    Graba la jornada entera capturando el audio que SUENA en el equipo (una
    clase virtual entra por los altavoces, no por el microfono), la transcribe
    en caliente, detecta los cambios de asignatura y arma un cuaderno por
    materias con apuntes, imagenes y clips.

    EL PUNTO DE EXTENSION es `_CLASES_SUBCOMANDOS` (arriba): un subcomando
    nuevo se da de alta con su funcion `_clases_x(resto, ai)` y una linea en
    ese dict, SIN alargar el if/elif de aqui abajo -- que se queda con los
    subcomandos historicos porque moverlos no aportaria nada y arriesgaria una
    regresion en lo unico que ya estaba entregado.

    Subcomandos (la logica vive entera en cognia/clases/, aqui solo la puerta):
      (sin arg)              estado: si graba, que materia, si esta pausada o
                             muteada, si el lock lo tiene OTRO proceso, como
                             va el refinado y que dijo la migracion de apuntes
      iniciar [micro|ambas]  arranca la jornada (default: audio del sistema)
      parar                  DEJA DE GRABAR ya (el audio queda en disco) y
                             devuelve el prompt; las materias definitivas y
                             los apuntes siguen en un hilo de fondo
      cierre                 en que fase va ese trabajo y si la clase ya esta
                             guardada
      pausar / reanudar      congela el audio sin cerrar la jornada
      mutear / desmutear     descarta el audio sin parar el reloj
      forzar                 quita el lock de grabacion (salida de emergencia)
      ver                    abre el CUADERNO estatico en el navegador
      vivo [estado|parar]    el cuaderno EN VIVO en ventana propia
      widget                 enciende el cerebrito (icono flotante)
      pdf [ruta]             el cuaderno listo para Ctrl+P -> Guardar como PDF
      materia <nombre>       corrige a mano la asignatura en curso
      nota <texto>           apunta algo en el minuto exacto en que estas
      importante <texto>     igual, pero marcado: no se resume ni se olvida
      imagen <ruta>          mete una foto de la pizarra en el cuaderno
      audio <ruta>           mete un clip de audio
      pegar                  la imagen del portapapeles (Win+Shift+S)
      formula <latex>        la dibuja (mathtext) y la apunta en el minuto
      grafico <expr|datos>   una curva de 'sin(x)*x' o barras de 'lunes=3, ...'
      imagen-buscar <q>      imagenes reutilizables, con autor y licencia
      imagen-usar <n>        baja la n-esima CON su atribucion
      marcar                 marca este instante sin escribir nada
      materias <a,b,c>       declara las asignaturas (mejora la deteccion)
      apuntes                regenera los apuntes de la ultima jornada
      transcribir            transcribe el audio que quedo pendiente
      refinar on|off|estado  el refinado en caliente ('on' reabre el disyuntor)
      doc estado [materia]   diagnostico del documento de bloques
      olvidar [plan]         aplica el olvido ('plan' solo lo ensenia)
    """
    try:
        from cognia.clases import jornada as _cj
        from cognia.clases import cuaderno as _cc
        from cognia.clases import almacen as _ca
    except Exception as exc:
        _aviso_degradado("clases", f"modulo no importable: {exc}")
        return

    arg = (arg or "").strip()
    partes = arg.split(None, 1)
    cmd = partes[0].lower() if partes else ""
    resto = partes[1].strip() if len(partes) > 1 else ""

    if cmd in ("ayuda", "-h", "--help"):
        _show_response(_CMD_DETAILS.get("/grabar-clase", ""), "listado")
        return

    # El registro se consulta ANTES que el if/elif: un subcomando nuevo no
    # tiene que colarse entre las ramas viejas para existir.
    manejador = _CLASES_SUBCOMANDOS.get(cmd)
    if manejador is not None:
        manejador(resto, ai)
        return

    # -- arrancar ----------------------------------------------------------
    if cmd in ("iniciar", "empezar", "start", "on"):
        fuente = (resto or "sistema").lower()
        if fuente not in ("sistema", "micro", "ambas"):
            _print_line("[warn_cl]Uso: /grabar-clase iniciar "
                        "[sistema|micro|ambas][/warn_cl]")
            return
        if _clases_cierre_vivo():
            # jornada.py suelta el lock de grabacion al FINAL de parar(), o
            # sea cuando terminan los apuntes: arrancar ahora fallaria con un
            # "ya hay una grabacion" que no explica nada.
            _print_line(f"[warn_cl]todavia se esta cerrando la jornada "
                        f"{_escape(str(_CLASES_CIERRE.get('jornada') or ''))}"
                        f": {_escape(_clases_cierre_fase())}[/warn_cl]")
            _print_line("[info_dim]el lock de grabacion se suelta al acabar "
                        "los apuntes; /grabar-clase cierre  dice como va"
                        "[/info_dim]")
            return
        _orch = getattr(ai, "_orchestrator", None) if ai is not None else None
        jv, motivo = _cj.arrancar(fuente=fuente, orch=_orch)
        if jv is None:
            _print_line(f"[err_cl]no puedo grabar: {_escape(motivo)}[/err_cl]")
            _aviso_degradado("clases.captura", motivo)
            return
        # LA TRAMPA DEL MODO SENCILLO, cazada TECLEANDO. `_print_line` tira
        # la linea ENTERA si lleva '[detail]' y el modo sencillo es el DEFAULT:
        # este "[ok]grabando la jornada X[/ok] [detail](...)[/detail]" iba en
        # UNA sola llamada, asi que desaparecia con su detalle y el duenio
        # tecleaba 'iniciar' y le volvia el prompt PELADO -- sin saber si
        # grababa, que jornada era ni por que fuente. `_clases_ok` separa el
        # resultado (siempre visible) de la letra pequenia.
        # OTRA VEZ, y no es redundante: soundcard hace
        # `warnings.simplefilter('always', SoundcardRuntimeWarning)` AL
        # IMPORTARSE (mediafoundation.py:26) y ese filtro se mete DELANTE del
        # nuestro. Como el import ocurre aqui dentro (captura lo carga al
        # arrancar), el silenciado del arranque del REPL queda pisado y la
        # traza vuelve a salir cada pocos segundos durante toda la clase.
        # Medido: sin esta segunda llamada, dos avisos en los primeros 40 s de
        # grabacion real.
        _silenciar_ruido_de_librerias()
        _clases_ok(f"grabando la jornada {_escape(jv.nombre)}",
                   f"fuente {_escape(fuente)}; {_escape(motivo)}")
        # info_dim y no detail: COMO se cierra la jornada es lo unico que hay
        # que saber al empezar, y en sencillo un [detail] no se imprime.
        _print_line("[info_dim]sigue usando Cognia con normalidad; "
                    "/grabar-clase parar cuando acabes[/info_dim]")
        return

    # -- el cuaderno -------------------------------------------------------
    if cmd in ("ver", "cuaderno", "abrir"):
        try:
            from cognia.clases import vista as _cv
        except Exception as exc:
            _aviso_degradado("clases.vista", f"no importable: {exc}")
            return
        try:
            ruta = _cv.export(open_browser=_abrir_en_navegador())
        except Exception as exc:
            _aviso_degradado("clases.vista", f"{type(exc).__name__}: {exc}")
            _print_line("[err_cl]no pude generar el cuaderno[/err_cl]")
            return
        _print_line(f"[info_dim]cuaderno: {_escape(str(ruta))}[/info_dim]")
        # Con el cuaderno abierto, el modelo gana las 7 tools doc_* con las
        # que escribe en los apuntes. Ver _clases_encender_doc_tools: se
        # encienden AQUI y no siempre porque el catalogo tiene techo medido.
        _clases_decir_doc_tools(
            _clases_encender_doc_tools(_clases_materia_actual()))
        _print_line("[detail]/grabar-clase pdf  lo abre listo para imprimir; "
                    "/grabar-clase vivo  lo abre EN VIVO y editable[/detail]")
        return

    # -- lo que aniade el duenio -------------------------------------------
    if cmd in ("nota", "importante", "imagen", "audio", "marcar", "materia"):
        jv = _cj.viva()
        if jv is None:
            _print_line("[warn_cl]no hay jornada grabando: esto se apunta EN "
                        "el minuto de la clase. Arranca con "
                        "/grabar-clase iniciar[/warn_cl]")
            return
        if cmd == "materia":
            if not resto:
                _print_line("[warn_cl]Uso: /grabar-clase materia <nombre>"
                            "[/warn_cl]")
                return
            jv.marcar_materia(resto)
            _print_line(f"[ok]desde ahora: {_escape(resto)}[/ok]")
            return
        if cmd == "marcar":
            jv.anotar(_cc.TIPO_MARCA, texto="", importante=True)
            _print_line("[ok]marcado este instante[/ok]")
            return
        if cmd in ("nota", "importante"):
            if not resto:
                _print_line(f"[warn_cl]Uso: /grabar-clase {cmd} <texto>"
                            f"[/warn_cl]")
                return
            jv.anotar(_cc.TIPO_NOTA, texto=resto,
                      importante=(cmd == "importante"))
            _print_line("[ok]apuntado[/ok]" if cmd == "nota"
                        else "[ok]apuntado y marcado como importante[/ok]")
            return
        # imagen / audio: se COPIA dentro de la jornada
        if not resto:
            _print_line(f"[warn_cl]Uso: /grabar-clase {cmd} <ruta>[/warn_cl]")
            return
        try:
            nombre = _ca.copiar_adjunto(
                jv.nombre, resto, prefijo="img" if cmd == "imagen" else "clip")
        except Exception as exc:
            _print_line(f"[err_cl]no pude copiar {_escape(resto)}: "
                        f"{_escape(str(exc))}[/err_cl]")
            return
        jv.anotar(_cc.TIPO_IMAGEN if cmd == "imagen" else _cc.TIPO_AUDIO,
                  texto="", adjunto=nombre, importante=True)
        _print_line(f"[ok]{cmd} anadida al cuaderno ({_escape(nombre)})[/ok]")
        return

    # -- mantenimiento -----------------------------------------------------
    if cmd == "materias":
        if not resto:
            _print_line(f"  [mod]{'materias':<16}[/mod] "
                        f"{_escape(', '.join(_cc.materias_conocidas()) or '(ninguna)')}")
            _print_line("[detail]/grabar-clase materias Fisica, Historia, Ingles"
                        "[/detail]")
            return
        decl = _cc.declarar_materias([x.strip() for x in resto.split(",")])
        _print_line(f"[ok]materias del curso: {_escape(', '.join(decl))}[/ok]")
        return

    if cmd == "apuntes":
        ult = _ca.jornadas()
        if not ult:
            _print_line("[warn_cl]no hay ninguna jornada todavia[/warn_cl]")
            return
        try:
            from cognia.clases import apuntes as _ap
        except Exception as exc:
            _aviso_degradado("clases.apuntes", f"no importable: {exc}")
            return
        _orch = getattr(ai, "_orchestrator", None) if ai is not None else None
        # info_dim y no detail: esto tarda MINUTOS con el modelo local y en
        # modo sencillo un [detail] no se imprime -- el duenio se quedaba
        # mirando un prompt congelado sin una sola letra.
        _print_line(f"[info_dim]generando apuntes de {_escape(ult[0])}... "
                    f"(habla con el modelo; Ctrl-C corta)[/info_dim]")
        try:
            hechos = _ap.generar_jornada(ult[0], orch=_orch)
        except Exception as exc:
            _aviso_degradado("clases.apuntes", f"{type(exc).__name__}: {exc}")
            return
        _print_line(f"[ok]apuntes de {len(hechos)} sesiones[/ok]")
        return

    if cmd == "transcribir":
        ult = _ca.jornadas()
        if not ult:
            _print_line("[warn_cl]no hay ninguna jornada todavia[/warn_cl]")
            return
        try:
            from cognia.clases import transcripcion as _tr
        except Exception as exc:
            _aviso_degradado("clases.transcripcion", f"no importable: {exc}")
            return
        _print_line(f"[info_dim]transcribiendo lo pendiente de "
                    f"{_escape(ult[0])}... (Ctrl-C corta)[/info_dim]")
        try:
            res = _tr.transcribir_pendientes(ult[0])
        except Exception as exc:
            _aviso_degradado("clases.transcripcion",
                             f"{type(exc).__name__}: {exc}")
            return
        _print_line(f"[ok]{res['transcritos']} trozos nuevos "
                    f"({res['ya_estaban']} ya estaban, "
                    f"{res['silencios']} en silencio)[/ok]")
        return

    if cmd == "olvidar":
        try:
            from cognia.clases import olvido as _ol
        except Exception as exc:
            _aviso_degradado("clases.olvido", f"no importable: {exc}")
            return
        solo_plan = resto.lower().startswith("plan")
        try:
            if solo_plan:
                acciones = _ol.plan()
                if not acciones:
                    _print_line("[info_dim]no hay nada que olvidar todavia"
                                "[/info_dim]")
                    return
                # La fila y su letra pequenia, en DOS lineas: juntas, el
                # '[detail]' del final se llevaba la fila ENTERA en modo
                # sencillo y 'olvidar plan' no listaba nada (mismo bug que
                # 'iniciar').
                for a in acciones[:20]:
                    _print_line(f"  [mod]{str(a.get('accion','')):<22}[/mod] "
                                f"{_escape(str(a.get('objetivo','')))}  "
                                f"({int(a.get('bytes',0))//1024} KB)")
                    _print_line(f"[detail]      "
                                f"{_escape(str(a.get('por_que','')))}[/detail]")
                return
            res = _ol.aplicar()
        except Exception as exc:
            _aviso_degradado("clases.olvido", f"{type(exc).__name__}: {exc}")
            return
        _print_line(f"[ok]{res.get('acciones',0)} acciones, "
                    f"{int(res.get('bytes_liberados',0))//1024} KB liberados "
                    f"({res.get('protegido',0)} elementos protegidos)[/ok]")
        return

    if cmd:
        _print_line(f"[warn_cl]subcomando desconocido: {_escape(cmd)}. "
                    f"/grabar-clase ayuda[/warn_cl]")
        return

    # -- estado (sin subcomando) -------------------------------------------
    est = _cj.estado()
    lock = est.get("lock") or {}
    if est.get("grabando"):
        seg = int(float(est.get("segundos") or 0))
        _print_line(f"[ok]{'PAUSADA' if est.get('pausada') else 'GRABANDO'}"
                    f"[/ok] jornada {_escape(str(est.get('jornada','')))}")
        filas = [("materia", str(est.get("materia") or "")),
                 ("lleva", "%d min %02d s" % (seg // 60, seg % 60)),
                 # pausada/muteada son DOS interruptores distintos y se
                 # imprimen los dos: reanudar no des-mutea, asi que "no entra
                 # audio" tiene dos causas posibles y hay que poder verlas.
                 ("pausada", "SI (/grabar-clase reanudar)" if est.get("pausada")
                             else "no"),
                 ("micro muteado", "SI (/grabar-clase desmutear)"
                                   if est.get("muteada") else "no"),
                 ("trozos de audio", str(est.get("trozos", 0))),
                 ("transcritos", str(est.get("transcritos", 0))),
                 ("en silencio", str(est.get("silencios", 0))),
                 ("descartados", str(est.get("descartados", 0)))]
    else:
        if not est.get("jornada"):
            _print_line("[info_dim]el cuaderno esta vacio todavia.[/info_dim]")
            if est.get("otro_proceso"):
                _print_line(f"[warn_cl]pero hay una grabacion en el proceso "
                            f"PID {lock.get('pid')} (jornada "
                            f"{_escape(str(lock.get('jornada') or '?'))}): "
                            f"para ahi, o /grabar-clase forzar si sabes que "
                            f"ese PID ya no es Cognia[/warn_cl]")
            _print_line("[detail]/grabar-clase iniciar  para grabar tu jornada"
                        "[/detail]")
            return
        filas = [("ultima jornada", str(est.get("jornada", ""))),
                 ("estado", str(est.get("estado", ""))),
                 ("duracion", "%d min" % (int(float(est.get("segundos") or 0)) // 60)),
                 ("sesiones", str(est.get("sesiones", 0))),
                 ("materias", ", ".join(est.get("materias") or []) or "-")]
    # EL LOCK DE OTRO PROCESO. Sin esta linea, un REPL abierto al lado del que
    # graba se pinta como "no graba" y ofrece un iniciar que solo puede
    # fallar: "no hay grabacion" y "la grabacion no es mia" son dos cosas.
    if est.get("otro_proceso"):
        filas.append(("la graba OTRO proceso",
                      "PID %s (jornada %s)" % (lock.get("pid"),
                                               lock.get("jornada") or "?")))
    if lock.get("absurdo"):
        filas.append(("lock sospechoso",
                      "tiene %d h: casi seguro un PID reciclado"
                      % (int(float(lock.get("edad") or 0.0)) // 3600)))
    # El refinado en caliente: si el disyuntor lo apago, esto es lo unico que
    # lo dice fuera de '/grabar-clase refinar estado'.
    _apagado = ""
    try:
        from cognia.clases import refinado as _cr_e
        _ref = _cr_e.estado(str(est.get("jornada") or ""))
    except Exception as _exc_ref:
        _aviso_degradado("clases.refinado",
                         f"no pude leer su estado: "
                         f"{type(_exc_ref).__name__}: {_exc_ref}")
        _ref = {}
    if _ref:
        for _j in (_ref.get("jornadas") or {}).values():
            if _j.get("apagado"):
                _apagado = str(_j["apagado"])
        filas.append(("refinado en caliente",
                      "APAGADO por el disyuntor" if _apagado
                      else ("encendido" if _ref.get("activo") else "apagado")))
    # EL CIERRE EN CURSO. Desde que 'parar' devuelve el prompt en el acto, el
    # trabajo caro sigue en un hilo: sin esta fila, el estado diria "ultima
    # jornada cerrada" mientras los apuntes se estan escribiendo todavia.
    # Solo mientras SIGUE (o si fallo): un "terminado" pegado en el estado el
    # resto de la sesion seria ruido, y para eso esta '/grabar-clase cierre'.
    _fase_cierre = (_clases_cierre_fase()
                    if (_clases_cierre_vivo() or _CLASES_CIERRE.get("error"))
                    else "")
    if _fase_cierre:
        filas.append(("cierre de %s" % (_CLASES_CIERRE.get("jornada") or "?"),
                      _fase_cierre))
    for k, v in filas:
        _print_line(f"  [mod]{k:<22}[/mod] {_escape(v)}")
    if _clases_cierre_vivo():
        _print_line("[info_dim]/grabar-clase cierre  dice como va (tu clase "
                    "ya esta guardada)[/info_dim]")
    for a in (est.get("avisos") or []):
        _print_line(f"[warn_cl]{_escape(str(a))}[/warn_cl]")
    if _ref and _apagado:
        _print_line(f"[warn_cl]refinado apagado: {_escape(_apagado)}. "
                    f"/grabar-clase refinar on lo reabre (es la unica via)"
                    f"[/warn_cl]")
    # AVISOS DE MIGRACION DE APUNTES: lo que la migracion de claves tuvo que
    # conservar aparte (huerfanos, empates de segundo). apuntes.py pedia
    # EXACTAMENTE este cableado; hasta hoy solo se veian en el log y dentro
    # del propio apuntes.json.
    if est.get("jornada"):
        try:
            from cognia.clases import apuntes as _ap_e
            for _a in _ap_e.avisos_migracion(str(est["jornada"])):
                _aviso_degradado("clases.apuntes", str(_a))
        except Exception as _exc_ap:
            _aviso_degradado("clases.apuntes",
                             f"no pude leer los avisos de migracion: "
                             f"{type(_exc_ap).__name__}: {_exc_ap}")
    if not est.get("grabando"):
        _print_line("[detail]/grabar-clase ver  abre el cuaderno  |  vivo  lo "
                    "abre EN VIVO  |  widget  enciende el cerebrito[/detail]")


def _slash_compilar(arg: str = "", ai=None) -> None:
    """`/compilar`: Cognia se fabrica sus PROPIAS herramientas como comandos.

    De una frase a un comando del CLI que funciona: especifica, genera el
    codigo y los tests, lo injerta en los 5 sitios del catalogo, lo evalua
    EJECUTANDOLO y lo registra. Si la evaluacion lo rechaza, lo retira y deja
    el repo como estaba.

    Edita cli.py de verdad. El duenio lo autorizo; las defensas son que el
    injerto solo INSERTA en anclas conocidas, que todo es transaccional con
    copia y rollback, y que los 4 guardianes del catalogo tienen que quedar
    verdes o se revierte.

    Subcomandos (punto de extension: este if/elif; la logica vive en
    cognia/compilador/):
      (sin arg)          estado: que sabe el compilador y que ha compilado
      <descripcion>      COMPILA una herramienta nueva
      ensayo <desc>      lo mismo pero SIN tocar el CLI (ensenia que saldria)
      lista              las herramientas compiladas y su estado
      ver <cmd>          la ficha de una, con su evidencia
      retirar <cmd>      la quita del CLI y borra sus ficheros
      receta             la receta de como se da de alta un comando
      copias             las copias de seguridad del CLI
      revertir <sello>   restaura el CLI desde una copia
    """
    try:
        from cognia.compilador import orquesta as _co
        from cognia.compilador import receta as _cr
        from cognia.compilador import injertador as _ci
    except Exception as exc:
        _aviso_degradado("compilador", f"modulo no importable: {exc}")
        return

    arg = (arg or "").strip()
    partes = arg.split(None, 1)
    cmd = partes[0].lower() if partes else ""
    resto = partes[1].strip() if len(partes) > 1 else ""

    if cmd in ("ayuda", "-h", "--help"):
        _show_response(_CMD_DETAILS.get("/compilar", ""), "listado")
        return

    if cmd == "receta":
        _show_response(_cr.RECETA_PROSA, "listado")
        _print_line("[detail]trampas conocidas:[/detail]")
        for t in _cr.TRAMPAS:
            _print_line(f"  [mod]*[/mod] {_escape(t)}")
        return

    if cmd == "copias":
        cs = _ci.copias()
        if not cs:
            _print_line("[info_dim]no hay copias todavia[/info_dim]")
            return
        for c in cs[:20]:
            _print_line(f"  [mod]{_escape(c)}[/mod]")
        _print_line("[detail]/compilar revertir <sello>[/detail]")
        return

    if cmd == "revertir":
        if not resto:
            _print_line("[warn_cl]Uso: /compilar revertir <sello>[/warn_cl]")
            return
        res = _ci.revertir_a(resto)
        if res.get("ok"):
            _print_line(f"[ok]CLI restaurado desde {_escape(resto)}[/ok]")
            _print_line("[warn_cl]reinicia Cognia para que cargue el CLI "
                        "restaurado[/warn_cl]")
        else:
            _print_line(f"[err_cl]{_escape(str(res.get('motivo','')))}[/err_cl]")
        return

    if cmd in ("lista", "listar"):
        try:
            from cognia.compilador import bitacora as _cb
            hs = _cb.listar()
        except Exception as exc:
            _aviso_degradado("compilador.bitacora", f"{type(exc).__name__}: {exc}")
            return
        if not hs:
            _print_line("[info_dim]todavia no has compilado ninguna "
                        "herramienta[/info_dim]")
            _print_line('[detail]/compilar "lo que quieres que haga"[/detail]')
            return
        for h in hs:
            _print_line(f"  [mod]{str(h.get('cmd','')):<22}[/mod] "
                        f"{str(h.get('estado','')):<10} "
                        f"[detail]{_escape(str(h.get('veredicto','')))}[/detail]")
        return

    if cmd == "ver":
        if not resto:
            _print_line("[warn_cl]Uso: /compilar ver <comando>[/warn_cl]")
            return
        try:
            from cognia.compilador import bitacora as _cb
            _show_response(_cb.ficha(resto if resto.startswith("/")
                                     else "/" + resto), "listado")
        except Exception as exc:
            _aviso_degradado("compilador.bitacora", f"{type(exc).__name__}: {exc}")
        return

    if cmd == "retirar":
        if not resto:
            _print_line("[warn_cl]Uso: /compilar retirar <comando>[/warn_cl]")
            return
        objetivo = resto if resto.startswith("/") else "/" + resto
        res = _co.retirar(objetivo)
        if res.get("ok"):
            _print_line(f"[ok]{_escape(objetivo)} retirada del CLI[/ok]")
            _print_line("[warn_cl]reinicia Cognia para que deje de estar"
                        "[/warn_cl]")
        else:
            _print_line(f"[err_cl]{_escape(str(res.get('motivo','')))}[/err_cl]")
        return

    # -- compilar de verdad -------------------------------------------------
    if cmd:
        seco = (cmd == "ensayo")
        descripcion = resto if seco else arg
        if not descripcion:
            _print_line("[warn_cl]Uso: /compilar ensayo <que quieres que haga>"
                        "[/warn_cl]")
            return
        _orch = getattr(ai, "_orchestrator", None) if ai is not None else None
        _print_line("[detail]especificando, generando, injertando y "
                    "evaluando... esto tarda: se ejecutan los guardianes y "
                    "los tests de verdad[/detail]")
        try:
            res = _co.compilar(descripcion, orch=_orch, seco=seco)
        except Exception as exc:
            _aviso_degradado("compilador", f"{type(exc).__name__}: {exc}")
            _print_line("[err_cl]el compilador reventó; el CLI no se toco"
                        "[/err_cl]")
            return
        for f in (res.get("fases") or []):
            marca = "[ok]OK [/ok]" if f.get("ok") else "[err_cl]NO [/err_cl]"
            _print_line(f"  {marca} [mod]{str(f.get('fase','')):<16}[/mod] "
                        f"{_escape(str(f.get('detalle',''))[:120])}")
        if res.get("ok"):
            _print_line(f"[ok]{_escape(str(res.get('cmd','')))} lista"
                        f"[/ok] [detail]{_escape(str(res.get('motivo','')))}"
                        f"[/detail]")
            if not res.get("seco"):
                _print_line("[warn_cl]reinicia Cognia para poder teclearla"
                            "[/warn_cl]")
        else:
            _print_line(f"[err_cl]{_escape(str(res.get('motivo','')))}[/err_cl]")
        return

    # -- estado (sin subcomando) -------------------------------------------
    est = _co.estado()
    filas = [("comandos en el CLI", str(est.get("comandos", 0))),
             ("herramientas compiladas", str(len(est.get("compiladas") or []))),
             ("de ellas vivas", str(len(est.get("vivas") or []))),
             ("sitios por comando", str(len(est.get("sitios_obligatorios") or []))),
             ("guardianes", str(len(est.get("guardianes") or []))),
             ("categorias con hueco",
              ", ".join((est.get("categorias_con_hueco") or [])[:3]) or "-"),
             ("copias del CLI", str(len(est.get("copias") or [])))]
    for k, v in filas:
        _print_line(f"  [mod]{k:<24}[/mod] {_escape(v)}")
    if est.get("sin_clasificar"):
        _print_line(f"[warn_cl]comandos sin cubo: "
                    f"{_escape(', '.join(est['sin_clasificar'][:5]))}[/warn_cl]")
    if est.get("aviso"):
        _print_line(f"[warn_cl]{_escape(str(est['aviso']))}[/warn_cl]")
    _print_line('[detail]/compilar "lo que quieres que haga"  para crear una'
                '[/detail]')
    _print_line("[detail]/compilar receta  para ver como lo hace[/detail]")


def _slash_horizonte(arg: str = "") -> None:
    """`/horizonte`: puerta del modo HORIZONTE (rondas de worker fresco con
    el contrato ralph de report de 5 campos + sello GoalContract).

    Sin args (o 'estado') muestra modo, rondas, tope del traspaso, el contrato
    y la ultima corrida (rondas, ultimo report resumido, cierre). Subcomandos
    (persisten via _save_config y siembran el env de la sesion):
      on|off            -> clave 'horizonte' (COGNIA_HORIZONTE)
      rondas <n>        -> 'horizonte_max_rondas' (COGNIA_HORIZONTE_CICLOS)
      handoff <chars>   -> 'horizonte_handoff_max' (COGNIA_HORIZONTE_HANDOFF_MAX)
    Punto de extension: los subcomandos son ramas de este if; el contrato del
    report vive en horizonte.validar_report / SCHEMA_REPORT."""
    try:
        from cognia.agent import horizonte as _hz
    except Exception as exc:
        _aviso_degradado("horizonte", f"modulo no importable: {exc}")
        return
    arg = (arg or "").strip()
    bajo = arg.lower()
    if bajo in ("on", "off"):
        cfg = _load_config()
        cfg["horizonte"] = bajo
        _save_config(cfg)
        os.environ[_hz.FLAG] = "1" if bajo == "on" else "0"
        _marcar_env_sembrada(_hz.FLAG)
        _print_line(f"[info_dim]modo horizonte: {bajo} (guardado; aplica a "
                    f"los proximos /hacer)[/info_dim]")
        return
    if bajo.startswith("rondas"):
        crudo = arg[len("rondas"):].strip()
        try:
            n = int(crudo)
            if n < 0:
                raise ValueError(n)
        except ValueError:
            _print_line("[warn_cl]Uso: /horizonte rondas <n> (entero >= 0; "
                        "0 = segun /esfuerzo)[/warn_cl]")
            return
        if n > _hz._TECHO_CICLOS:
            _print_line(f"[warn_cl]horizonte: el techo duro es "
                        f"{_hz._TECHO_CICLOS} rondas; uso {_hz._TECHO_CICLOS}"
                        f"[/warn_cl]")
            n = _hz._TECHO_CICLOS
        cfg = _load_config()
        cfg["horizonte_max_rondas"] = str(n) if n else ""
        _save_config(cfg)
        if n:
            os.environ[_hz.ENV_CICLOS] = str(n)
            _marcar_env_sembrada(_hz.ENV_CICLOS)
        else:
            os.environ.pop(_hz.ENV_CICLOS, None)
        _print_line(f"[info_dim]horizonte: rondas max "
                    f"{n if n else 'segun /esfuerzo'} (guardado)[/info_dim]")
        return
    if bajo.startswith("handoff"):
        crudo = arg[len("handoff"):].strip()
        try:
            n = int(crudo)
            if n < 512:
                raise ValueError(n)
        except ValueError:
            _print_line("[warn_cl]Uso: /horizonte handoff <chars> (entero >= "
                        "512; dsh usa 16384)[/warn_cl]")
            return
        cfg = _load_config()
        cfg["horizonte_handoff_max"] = str(n)
        _save_config(cfg)
        os.environ[_hz.ENV_HANDOFF_MAX] = str(n)
        _marcar_env_sembrada(_hz.ENV_HANDOFF_MAX)
        _print_line(f"[info_dim]horizonte: tope del traspaso {n} chars "
                    f"(guardado)[/info_dim]")
        return
    if arg and bajo != "estado":
        _print_line("[warn_cl]Uso: /horizonte \\[estado | on | off | rondas <n> "
                    "| handoff <chars>][/warn_cl]")
        return
    # Estado (default).
    cfg = _load_config()

    def _fuente(var, clave):
        env = (os.environ.get(var) or "").strip()
        return (f"env {var}={env}" if env and not _env_es_sembrada(var)
                else f"config '{clave}'")

    activo = _hz.habilitado()
    rondas_env = _hz.max_ciclos_env()
    rondas_txt = (f"{rondas_env}" if rondas_env
                  else f"{_active_effort().get('ciclos_horizonte', 2)} "
                       f"(segun /esfuerzo {cfg.get('esfuerzo', 'medio')})")
    _print_line(f"[info_dim]modo horizonte: {'ACTIVO' if activo else 'apagado'} "
                f"({_fuente(_hz.FLAG, 'horizonte')})[/info_dim]")
    _print_line(f"[info_dim]rondas max: {rondas_txt}; techo duro "
                f"{_hz._TECHO_CICLOS} ({_fuente(_hz.ENV_CICLOS, 'horizonte_max_rondas')})"
                f"[/info_dim]")
    _print_line(f"[info_dim]traspaso max: {_hz.handoff_max_env()} chars "
                f"({_fuente(_hz.ENV_HANDOFF_MAX, 'horizonte_handoff_max')})[/info_dim]")
    _print_line(f"[info_dim]contrato del report: {{{_hz.FIRMA_REPORT}}} con status "
                f"{'|'.join(_hz.ESTADOS_REPORT)}; validado 2 veces; blocked "
                f"aceptado tras {_hz.BLOCKED_RONDAS_MIN} rondas iguales[/info_dim]")
    foto = _hz.estado_actual()
    if not foto:
        # Sin corrida en este proceso: la ultima del disco, si hay.
        try:
            from cognia.agent import estado_tarea as _et
            dirs = sorted((d for d in _et.dir_tareas().iterdir() if d.is_dir()),
                          key=lambda d: d.name, reverse=True)
            # El primero CON estado.json: el directorio comparte raiz con
            # TX ('tx-...' ordena despues de '2026...' y no tiene estado);
            # tomar dirs[0] a secas decia 'ninguna' con corridas en disco
            # (cazado tecleando /horizonte estado, 2026-08-24).
            est = None
            for d in dirs:
                est = _et.cargar(d.name)
                if est:
                    break
        except Exception as exc:
            _aviso_degradado("horizonte", f"no pude leer el estado durable: {exc}")
            est = None
        if not est:
            _print_line("[info_dim]ultima corrida: ninguna (ni en este proceso "
                        "ni en disco)[/info_dim]")
            return
        ciclos = est.get("ciclos", [])
        ultimo = ciclos[-1] if ciclos else {}
        foto = {"task_id": est.get("task_id", ""), "tarea": est.get("tarea", ""),
                "activa": est.get("status") == "en_curso",
                "rondas": len(ciclos), "max_rondas": "?",
                "criterios": len(est.get("criterios", [])),
                "contrato_ok": est.get("status"),
                "report": ultimo.get("report"),
                "report_error": ultimo.get("report_error", ""),
                "cierre": est.get("cierre_worker", "")}
    _print_line(f"[info_dim]ultima corrida: {foto.get('task_id', '')} "
                f"({'EN CURSO' if foto.get('activa') else 'cerrada'}); rondas "
                f"{foto.get('rondas')}/{foto.get('max_rondas')}; criterios "
                f"{foto.get('criterios')}; contrato: {foto.get('contrato_ok')}"
                f"[/info_dim]")
    _print_line(f"[info_dim]  tarea: {_escape((foto.get('tarea') or '')[:120])}"
                f"[/info_dim]")
    rep_ = foto.get("report")
    if rep_:
        _print_line(f"[info_dim]  ultimo report: {rep_.get('status')} -- "
                    f"{_escape(rep_.get('summary', '')[:200])}[/info_dim]")
        _print_line(f"[info_dim]    evidence {len(rep_.get('evidence', []))}, "
                    f"nextSteps {len(rep_.get('nextSteps', []))}"
                    + (f", blocker: {_escape(rep_.get('blocker', '')[:120])}"
                       if rep_.get("blocker") else "") + "[/info_dim]")
    else:
        _print_line(f"[info_dim]  ultimo report: ninguno"
                    + (f" ({_escape(str(foto.get('report_error'))[:160])})"
                       if foto.get("report_error") else "") + "[/info_dim]")
    if foto.get("cierre"):
        _print_line(f"[info_dim]  cierre: "
                    f"{_escape(str(foto['cierre'])[:400])}[/info_dim]")


def _aplicar_config_bucle() -> None:
    """Propaga la config de la higiene del lazo (repeticion + timeout por
    tool) al entorno SIN pisar lo del usuario y marcando la siembra (F6), y
    VALIDA las dos al arrancar: una config invalida se grita via degradado y
    se siembra el default en su lugar (el REPL no puede reventar por un
    umbral mal tecleado, pero tampoco puede callarselo: patron dsh)."""
    try:
        from cognia.harness import repeticion as _rep
        from cognia.harness import timeout_tool as _tt
    except Exception as exc:
        _aviso_degradado("repeticion", f"modulo no importable: {exc}")
        return
    _rep.registrar_avisador(_aviso_degradado)
    _tt.registrar_avisador(_aviso_degradado)
    try:
        cfg = _load_config()
    except Exception as exc:
        _aviso_degradado("repeticion", f"config no aplicada: {exc}")
        return
    # umbrales: validar ANTES de sembrar; basura -> default y grito
    umb = str(cfg.get("repeticion_umbrales", "3,5,8")).strip()
    try:
        _rep.parsear_umbrales(umb)
    except _rep.ConfigInvalida as exc:
        _aviso_degradado("repeticion", f"config 'repeticion_umbrales' "
                         f"invalida ({exc}); uso 3,5,8")
        umb = "3,5,8"
    act = str(cfg.get("repeticion", "on")).strip().lower()
    if act not in ("on", "off"):
        _aviso_degradado("repeticion", f"config 'repeticion'={act!r} no es "
                         f"on/off; uso on")
        act = "on"
    # umbral por fichero (ContadorFichero): misma regla, basura -> 3 y grito
    umb_f = str(cfg.get("repeticion_umbral_fichero", "3")).strip()
    try:
        _rep.parsear_umbral_fichero(umb_f)
    except _rep.ConfigInvalida as exc:
        _aviso_degradado("repeticion", f"config 'repeticion_umbral_fichero' "
                         f"invalida ({exc}); uso 3")
        umb_f = "3"
    tmo = str(cfg.get("tool_timeout_s", "120")).strip()
    try:
        if int(float(tmo)) < 0:
            raise ValueError(tmo)
    except ValueError:
        _aviso_degradado("timeout_tool", f"config 'tool_timeout_s'={tmo!r} "
                         f"no es un entero >= 0; uso 120")
        tmo = "120"
    pares = [
        (_rep.ENV_ACTIVO, "1" if act == "on" else "0"),
        (_rep.ENV_UMBRALES, umb),
        (_rep.ENV_UMBRAL_FICHERO, umb_f),
        (_tt.ENV_TIMEOUT, tmo),
    ]
    # Razonamiento en bucle: misma regla que los de arriba (validar, gritar si
    # es basura, sembrar el default). Su import va aparte para que una
    # instalacion sin el modulo no deje sin higiene de lazo al resto.
    try:
        from cognia.harness import razonamiento as _raz
        act_r = str(cfg.get("razonamiento", "on")).strip().lower()
        if act_r not in ("on", "off"):
            _aviso_degradado("razonamiento", f"config 'razonamiento'={act_r!r} "
                             f"no es on/off; uso on")
            act_r = "on"
        for clave, env, minimo, defecto in (
                ("razonamiento_umbral", _raz.ENV_UMBRAL, 200, "4000"),
                ("razonamiento_racha", _raz.ENV_RACHA, 2, "3")):
            crudo = str(cfg.get(clave, defecto)).strip()
            try:
                _raz.parsear_entero(crudo, minimo)
            except _raz.ConfigInvalida as exc:
                _aviso_degradado("razonamiento", f"config {clave!r} invalida "
                                 f"({exc}); uso {defecto}")
                crudo = defecto
            pares.append((env, crudo))
        pares.append((_raz.ENV_ACTIVO, "1" if act_r == "on" else "0"))
    except Exception as exc:
        _aviso_degradado("razonamiento", f"config no aplicada: {exc}")
    for var, valor in pares:
        if not (os.environ.get(var) or "").strip():
            os.environ[var] = valor
            _marcar_env_sembrada(var)
    # y si el USUARIO puso una env basura, tambien se dice al arrancar
    try:
        _rep.validar_config()
    except _rep.ConfigInvalida as exc:
        _aviso_degradado("repeticion", f"env invalida, guard apagado: {exc}")
    try:
        _tt.validar_config()
    except _tt.ConfigInvalida as exc:
        _aviso_degradado("timeout_tool", f"env invalida, sin deadline: {exc}")


# ── /confianza: niveles de confianza del chat (2026-08-24) ─────────────────
# Medido hoy: a "cuantos suscriptores tiene The Acua Boy en YouTube?" el
# modelo confiesa "no tengo acceso a datos en tiempo real" y el REPL lo
# imprimia con la misma cara que una respuesta buena; el dato estaba en la
# web (4,63 mil, @theacuaboy170). La logica (clasificar / investigar /
# evaluar) vive en cognia.agent.confianza_chat; aca SOLO la puerta
# (/confianza), la config persistida y los dos ganchos del turno de chat
# (previa y posterior), que el REPL llama desde el fast-path. Contrato: el
# subsistema no puede tumbar un turno (todo en try) ni callarse (todo fallo
# via _aviso_degradado 'confianza*'); _CONFIANZA_ULTIMO guarda la foto del
# ultimo turno investigado para que /confianza estado la muestre.
_CONFIANZA_ENV = "COGNIA_CONFIANZA"
_CONFIANZA_ULTIMO: dict = {
    "pregunta": "", "modo": "", "via": "", "aviso": "", "fuentes": [],
    "segundos": 0.0, "veredicto": None, "linea": "",
}
# Estilo de la linea final por nivel. alta/media = verde; baja va en
# info_dim (VISIBLE en modo sencillo: un '[detail]' se suprime ahi y la
# senal "sin verificar" es justo la que no puede desaparecer); nula = rojo.
_CONFIANZA_ESTILO = {"alta": "ok_cl", "media": "ok_cl", "baja": "info_dim",
                     "nula": "err_cl"}


def _confianza_config():
    """ConfigConfianza resuelta: config persistida + la env COGNIA_CONFIANZA=0
    apaga TODO ganando a la config (mismo patron que COGNIA_REPETICION y
    COGNIA_ANIMACION). Se lee a call-time: /confianza on|off vale en el
    turno siguiente sin reiniciar."""
    from cognia.agent.confianza_chat import config_desde
    cfg = config_desde(_load_config())
    if (os.environ.get(_CONFIANZA_ENV) or "").strip() == "0":
        cfg.on = False
    return cfg


def _confianza_remoto() -> bool:
    """True bajo COGNIA_REMOTO=1. Hasta la paridad remota (2026-08-24) este
    guard APAGABA los dos ganchos de confianza en el remoto, porque su prosa
    ('◐ confianza a priori BAJA…', '● confianza ALTA (0,90) · …') llegaba al
    chat del movil como si fuera otra respuesta. Ya no apaga nada: decide
    solo el CANAL de esa prosa (_linea_o_aviso) y el veredicto viaja como
    evento tipado Confianza (ux/events.py) que el movil pinta como chip."""
    return os.environ.get("COGNIA_REMOTO", "").strip() == "1"


def _linea_o_aviso(markup: str, plano: str, origen: str) -> None:
    """Una linea de PROGRESO de un subsistema (confianza, lazo): en el
    terminal se pinta con su markup; bajo COGNIA_REMOTO va como Aviso por el
    bus (el sink stdout la entrega al movil como actividad, con ecos
    registrados) y NO se imprime, porque como prosa el clasificador del movil
    la tomaria por una respuesta. emitir() es no-lanzante."""
    if _confianza_remoto():
        try:
            from cognia.ux import events as _ev
            _ev.emitir(_ev.Aviso(texto=plano, origen=origen))
            return
        except Exception as exc:
            _aviso_degradado(origen, f"aviso no emitido: {exc}")
    _print_line(markup)


def _confianza_evento(msg: str) -> None:
    _linea_o_aviso(f"[detail]  · {_escape(str(msg))}[/detail]",
                   f"· {msg}", "confianza")


def _confianza_registrar(inv, modo: str) -> None:
    _CONFIANZA_ULTIMO.update({
        "pregunta": inv.pregunta, "modo": modo, "via": inv.via,
        "aviso": inv.aviso, "fuentes": list(inv.fuentes),
        "segundos": inv.segundos, "veredicto": None, "linea": "",
    })


def _confianza_sin_evidencias(inv) -> None:
    """Los DOS estados vacios se muestran distintos (Investigacion.aviso):
    aviso = se rompio algo -> ambar degradado; sin aviso = se busco y no
    habia nada -> una linea de detalle, no es un fallo."""
    if inv.aviso:
        _aviso_degradado("confianza.web", inv.aviso)
    else:
        _linea_o_aviso(f"[detail]  · la web no devolvió evidencias para "
                       f"«{_escape(inv.consulta)}»[/detail]",
                       f"· la web no devolvió evidencias para «{inv.consulta}»",
                       "confianza")


def _confianza_previa(raw: str, cfg=None):
    """Gancho PREVIA: si la pregunta pide un dato volatil, investiga ANTES de
    gastar el turno del modelo. Devuelve la Investigacion (con o sin
    evidencias) si la pregunta se clasifico volatil; None si no hay nada que
    hacer (y entonces no imprime nada: una pregunta normal no ve el
    subsistema). La cabecera va en info_dim para que se vea tambien en modo
    sencillo: son hasta `cfg.segundos` de espera y un REPL mudo parece
    colgado (memoria: spinner huerfano)."""
    from cognia.agent import confianza_chat as _cc
    cfg = cfg or _confianza_config()
    if not (cfg.on and cfg.previa):
        return None
    clasif = _cc.clasificar_pregunta(raw)
    if not clasif.volatil:
        return None
    _linea_o_aviso(f"[info_dim]◐ confianza a priori BAJA: {_escape(clasif.motivo)} "
                   f"→ investigando en la web…[/info_dim]",
                   f"◐ confianza a priori BAJA: {clasif.motivo} → investigando "
                   "en la web…", "confianza")
    inv = _cc.investigar(raw, clasif, presupuesto_s=cfg.segundos,
                         max_paginas=cfg.max_paginas,
                         on_evento=_confianza_evento)
    _confianza_registrar(inv, "previa")
    if not inv.evidencias:
        _confianza_sin_evidencias(inv)
    return inv


def _confianza_prefijo(inv) -> str:
    """Bloque de evidencias que se antepone al texto que VE el modelo (no al
    que guarda _history: ahi va `raw`, como con stepwise). '' sin
    evidencias."""
    from cognia.agent.confianza_chat import bloque_evidencia
    return bloque_evidencia(inv) if (inv is not None and inv.evidencias) else ""


def _confianza_veredicto(respuesta: str, inv, investigado: bool = True):
    """Evalua la respuesta contra la evidencia, imprime la linea de nivel
    (estilo por nivel) y la deja en _CONFIANZA_ULTIMO. Devuelve el
    Veredicto."""
    from cognia.agent import confianza_chat as _cc
    ver = _cc.evaluar_respuesta(respuesta, inv)
    linea = _cc.linea_confianza(ver, inv, investigado=investigado)
    nivel = _cc.nivel_de(ver.confianza)
    estilo = _CONFIANZA_ESTILO.get(nivel, "info_dim")
    # El veredicto como DATO por el bus (paridad remota 2026-08-24): el movil
    # pinta un chip bajo la burbuja; en el terminal el renderer no tiene
    # handler para Confianza y la linea la pinta esta funcion. Las fuentes son
    # las que la linea nombra (inv.fuentes: las paginas que hablan de la
    # entidad), no las de busqueda.
    fuentes = list(inv.fuentes) if (inv is not None and inv.fuentes) else list(ver.fuentes or [])
    try:
        from cognia.ux import events as _ev
        _ev.emitir(_ev.Confianza(nivel=nivel, glifo=_cc.glifo_de(nivel),
                                 valor=float(ver.confianza), fuentes=fuentes,
                                 texto=linea))
    except Exception as exc:
        _aviso_degradado("confianza", f"evento Confianza no emitido: {exc}")
    if not _confianza_remoto():
        _print_line(f"[{estilo}]{_escape(linea)}[/{estilo}]")
    _CONFIANZA_ULTIMO.update({"veredicto": ver, "linea": linea})
    return ver


def _confianza_posterior(raw: str, respuesta: str, pedir, cfg=None,
                         mostrar=None):
    """Gancho POSTERIOR: la respuesta CONFIESA no saber -> investigar y
    re-preguntar con las fuentes. `pedir(texto_usuario) -> str` es la
    segunda llamada al backend (la arma el REPL con el mismo system,
    historial y presupuesto del turno; aca no se conoce nada de eso);
    `mostrar(final)` pinta la respuesta nueva ANTES de la linea de nivel
    (el orden que ve el usuario: respuesta, luego su confianza).

    Devuelve (final, inv, veredicto): `final` es la respuesta nueva si hubo
    evidencias y el backend contesto, o la original intacta. None si la
    respuesta no confiesa nada (no se imprime nada). Sin evidencias: aviso
    degradado (o linea de detalle) + linea '○ confianza BAJA · sin
    verificar'. Un backend que devuelve vacio en la segunda llamada se
    declara y deja la respuesta original."""
    from cognia.agent import confianza_chat as _cc
    cfg = cfg or _confianza_config()
    if not (cfg.on and cfg.posterior):
        return None
    confiesa, motivo = _cc.detectar_incertidumbre(respuesta)
    if not confiesa:
        return None
    _linea_o_aviso(f"[info_dim]◐ la respuesta declara incertidumbre "
                   f"({_escape(motivo)}) → investigando en la web…[/info_dim]",
                   f"◐ la respuesta declara incertidumbre ({motivo}) → "
                   "investigando en la web…", "confianza")
    inv = _cc.investigar(raw, _cc.clasificar_pregunta(raw),
                         presupuesto_s=cfg.segundos,
                         max_paginas=cfg.max_paginas,
                         on_evento=_confianza_evento)
    _confianza_registrar(inv, "posterior")
    if not inv.evidencias:
        _confianza_sin_evidencias(inv)
        return respuesta, inv, _confianza_veredicto(respuesta, inv)
    _linea_o_aviso("[detail]  · respondiendo con las fuentes…[/detail]",
                   "· respondiendo con las fuentes…", "confianza")
    final = (pedir(_confianza_prefijo(inv) + raw) or "").strip()
    if not final:
        _aviso_degradado("confianza",
                         "la segunda llamada con las fuentes volvio vacia; "
                         "se conserva la respuesta original")
        final = respuesta
    elif final != respuesta and mostrar is not None:
        mostrar(final)
    return final, inv, _confianza_veredicto(final, inv)


# ---------------------------------------------------------------------------
# EL CHAT NO EJECUTA NADA (transcript del dueno 2026-08-25, 11:52-11:57):
# "Quiero que limpies todas las capturas de pantalla" fue al chat, que
# respondio con comandos de LINUX en Windows; "hazlo tu" siguio en chat y el
# modelo INVENTO "Ejecute los dos comandos... veintinueve archivos
# eliminados" (cero tools corridas); "no los ejecutaste" repitio el invento.
# Dos piezas: (1) _tarea_reencaminada arma la tarea REAL para el agente
# cuando el turno es un reclamo/"hazlo tu"; (2) _chat_afirmaciones_cierre
# revisa la respuesta del fast-path y, si AFIRMA acciones, avisa, no la
# persiste y reencamina al agente. Puerta: /confianza acciones on|off
# (config 'chat_afirmaciones'); la env COGNIA_CHAT_AFIRMACIONES=0 apaga
# ganando a la config.
# ---------------------------------------------------------------------------
_CHAT_AFIRMACIONES_ENV = "COGNIA_CHAT_AFIRMACIONES"


def _chat_afirmaciones_activo() -> bool:
    """on por defecto; la env =0 gana a la config (patron COGNIA_CONFIANZA)."""
    if (os.environ.get(_CHAT_AFIRMACIONES_ENV) or "").strip() == "0":
        return False
    try:
        cfg = _load_config()
    except Exception as exc:
        _aviso_degradado("chat.afirma_accion",
                         f"config ilegible ({type(exc).__name__}: {exc}); "
                         "asumo on")
        return True
    return str(cfg.get("chat_afirmaciones", "on")).strip().lower() != "off"


def _tarea_reencaminada(raw: str, previa: str = None) -> str:
    """La tarea REAL detras de un "hazlo tu"/"no los ejecutaste": el ultimo
    mensaje del usuario que PEDIA la accion, con la respuesta previa del chat
    como contexto. Si no hay peticion sustantiva en el historial, cae al
    ultimo mensaje del usuario y, en ultima instancia, a `raw` tal cual."""
    from cognia.agent.intent import detect as _d

    def _es_sustantiva(msg: str) -> bool:
        # Un reclamo o un "hazlo" NO es la peticion: es el dedo que la senala.
        try:
            d = _d(msg)
        except Exception:
            return False
        return (d.needs_agent and d.reason != "accion:hazlo"
                and not d.reason.startswith(("reclamo:", "continuacion:")))

    peticion, ultima_user = "", ""
    if _es_sustantiva(raw):
        peticion = raw
    else:
        # Los 12 mensajes mas recientes bastan: el reclamo llega 1-2 turnos
        # despues de la peticion (transcript: peticion -> chat -> "hazlo tu").
        for h in reversed(_history[-12:]):
            if h.get("role") != "user":
                continue
            c = (h.get("content") or "").strip()
            if not c or c.lower() == raw.strip().lower():
                continue
            if not ultima_user:
                ultima_user = c
            if _es_sustantiva(c):
                peticion = c
                break
    if previa is None:
        previa = (_history[-1].get("content") or ""
                  if _history and _history[-1].get("role") == "assistant"
                  else "")
    previa = (previa or "").strip()[:600]
    if not peticion:
        peticion = ultima_user or raw
    if peticion == raw and not previa:
        return raw
    tarea = peticion
    if previa:
        # El contexto declara que NADA se ejecuto: sin esto el agente podia
        # creer que la mitad ya estaba hecha. Y los comandos citados pueden
        # ser de OTRO sistema operativo (el chat propuso `find -delete` y
        # `gnome-screenshot` en Windows): se le exige verificar.
        tarea += ("\n\n[Contexto: el chat ya respondio a esto SIN ejecutar "
                  "nada (no tiene herramientas). Su respuesta fue:\n«"
                  + previa + "»\nAhora ejecuta la peticion DE VERDAD con las "
                  "herramientas; verifica que cada comando corresponda al "
                  "sistema operativo real antes de correrlo.]")
    return tarea


def _chat_afirmaciones_cierre(ai, raw: str, respuesta: str):
    """Cierre del fast-path: devuelve (respuesta_final, disparado).

    Si la respuesta del CHAT afirma acciones ejecutadas (el fast-path no
    corre tools JAMAS, asi que toda afirmacion es inventada): (i) aviso
    visible + ambar; (ii) la respuesta inventada NO se devuelve (el llamador
    persiste lo que devolvemos: la del agente); (iii) la peticion original se
    reencamina al agente, cuyo gate de modo-permiso pide confirmacion antes
    de acciones destructivas."""
    if not _chat_afirmaciones_activo():
        return respuesta, False
    from cognia.agent.intent import afirma_accion_ejecutada
    frag = afirma_accion_ejecutada(respuesta)
    if not frag:
        return respuesta, False
    _print_line("[warn_cl]⚠ el chat no ejecuta nada: esa respuesta AFIRMA "
                "acciones que no ocurrieron[/warn_cl]")
    _aviso_degradado("chat.afirma_accion",
                     f"afirmacion sin tools: «{frag[:120]}» — reencamino la "
                     "peticion al agente (apagable: /confianza acciones off)")
    tarea = _tarea_reencaminada(raw, previa=respuesta)
    _print_line("[detail]Reencamino la peticion al agente para ejecutarla "
                "de verdad...[/detail]")
    resp2 = _run_agent_task(ai, tarea, _print_line)
    _mostrar_cierre_agente(resp2)
    return resp2, True


def _slash_confianza(arg: str = "") -> None:
    """`/confianza`: puerta de los niveles de confianza del chat.

    Sin args (o 'estado') muestra los mandos, la via web disponible y el
    ultimo turno investigado. Subcomandos (persisten via _save_config):
      on|off               -> 'confianza'
      previa on|off        -> 'confianza_previa'
      posterior on|off     -> 'confianza_posterior'
      segundos <n>         -> 'confianza_segundos'
      paginas <n>          -> 'confianza_paginas'
      probar <pregunta>    -> clasifica e investiga SIN llamar al modelo"""
    try:
        from cognia.agent import confianza_chat as _cc
    except Exception as exc:
        _aviso_degradado("confianza", f"modulo no importable: {exc}")
        return
    arg = (arg or "").strip()
    partes = arg.split(None, 1)
    sub = partes[0].lower() if partes else ""
    resto = partes[1].strip() if len(partes) > 1 else ""
    uso = ("[warn_cl]Uso: /confianza \\[estado | on | off | previa on|off | "
           "posterior on|off | acciones on|off | segundos <n> | paginas <n> | "
           "probar <pregunta>][/warn_cl]")

    def _guardar(clave, valor, texto):
        cfg = _load_config()
        cfg[clave] = valor
        _save_config(cfg)
        _print_line(f"[info_dim]confianza: {texto} (guardado)[/info_dim]")

    if sub in ("on", "off") and not resto:
        _guardar("confianza", sub, f"{sub}")
        return
    if sub in ("previa", "posterior"):
        if resto.lower() not in ("on", "off"):
            _print_line(f"[warn_cl]Uso: /confianza {sub} on|off[/warn_cl]")
            return
        _guardar(f"confianza_{sub}", resto.lower(), f"{sub} {resto.lower()}")
        return
    if sub == "acciones":
        # detector de afirmaciones del chat (cierre del fast-path): la clave
        # vive en la config general porque la lee _chat_afirmaciones_activo
        # en cada turno; la env COGNIA_CHAT_AFIRMACIONES=0 le gana.
        if resto.lower() not in ("on", "off"):
            _print_line("[warn_cl]Uso: /confianza acciones on|off[/warn_cl]")
            return
        _guardar("chat_afirmaciones", resto.lower(),
                 f"acciones (chat que afirma ejecutar) {resto.lower()}")
        return
    if sub in ("segundos", "paginas"):
        try:
            n = int(float(resto.replace(",", ".")))
            if n < 1:
                raise ValueError(n)
        except ValueError:
            _print_line(f"[warn_cl]Uso: /confianza {sub} <entero >= 1>[/warn_cl]")
            return
        _guardar(f"confianza_{sub}", str(n), f"{sub} {n}")
        return
    if sub == "probar":
        if not resto:
            _print_line("[warn_cl]Uso: /confianza probar <pregunta>[/warn_cl]")
            return
        cfg = _confianza_config()
        clasif = _cc.clasificar_pregunta(resto)
        _print_line(f"[info_dim]clasificacion: {'VOLATIL' if clasif.volatil else 'no volatil'}"
                    f" · motivo: {_escape(clasif.motivo or '-')}"
                    f" · entidad: {_escape(clasif.entidad or '-')}"
                    f" · plataforma: {_escape(clasif.plataforma or '-')}"
                    f" · consulta: {_escape(clasif.consulta or '-')}[/info_dim]")
        if not clasif.volatil:
            _print_line("[info_dim]  (en un turno real NO se investigaria; "
                        "investigo igual para el diagnostico)[/info_dim]")
        inv = _cc.investigar(resto, clasif, presupuesto_s=cfg.segundos,
                             max_paginas=cfg.max_paginas,
                             on_evento=lambda m: _print_line(
                                 f"[info_dim]  · {_escape(str(m))}[/info_dim]"))
        _confianza_registrar(inv, "probar")
        _print_line(f"[info_dim]via: {_escape(inv.via or '-')} · "
                    f"{inv.segundos:.1f} s · {len(inv.evidencias)} evidencia(s)"
                    f"[/info_dim]")
        for i, e in enumerate(inv.evidencias, 1):
            _print_line(f"[ok_cl]  [{i}] {_escape(e.titulo)} — {_escape(e.url)}"
                        f"[/ok_cl]")
            if e.dato:
                _print_line(f"[info_dim]      {_escape(e.dato[:300])}[/info_dim]")
        if inv.fuentes:
            _print_line(f"[info_dim]fuentes: {_escape(', '.join(inv.fuentes))}"
                        f"[/info_dim]")
        if inv.aviso:
            _print_line(f"[warn_cl]aviso: {_escape(inv.aviso)}[/warn_cl]")
        elif not inv.evidencias:
            _print_line("[warn_cl]la web no devolvio evidencias (sin fallo "
                        "declarado)[/warn_cl]")
        return
    if sub and sub != "estado":
        _print_line(uso)
        return
    # Estado (default).
    cfg = _confianza_config()
    env = (os.environ.get(_CONFIANZA_ENV) or "").strip()
    try:
        from cognia.knowledge.navegador import via_busqueda_disponible
        via_web = via_busqueda_disponible()
    except Exception as exc:
        via_web = f"ninguna: navegador no importable ({type(exc).__name__}: {exc})"
    estado_on = ("OFF (env COGNIA_CONFIANZA=0 gana a la config)" if env == "0"
                 else ("on" if cfg.on else "off"))
    u = _CONFIANZA_ULTIMO
    filas = [
        ("confianza", estado_on),
        ("previa", "on" if cfg.previa else "off"),
        ("posterior", "on" if cfg.posterior else "off"),
        ("segundos", f"{cfg.segundos:g}"),
        ("paginas", str(cfg.max_paginas)),
        ("acciones (chat que afirma ejecutar)",
         ("OFF (env COGNIA_CHAT_AFIRMACIONES=0 gana a la config)"
          if (os.environ.get(_CHAT_AFIRMACIONES_ENV) or "").strip() == "0"
          else ("on" if _chat_afirmaciones_activo() else "off"))),
        ("via web", via_web),
        ("ultimo turno", (f"[{u['modo']}] «{u['pregunta'][:60]}» · via "
                          f"{u['via'] or '-'} · {u['segundos']:.1f} s · fuentes: "
                          f"{', '.join(u['fuentes']) or '-'}")
                         if u["pregunta"] else "ninguno todavia"),
        ("ultimo aviso", u["aviso"] or "-"),
        ("ultimo veredicto", u["linea"] or "-"),
    ]
    _print_line("[info_dim]/confianza — niveles: ● alta ◐ media ○ baja ✕ nula"
                "[/info_dim]")
    for k, v in filas:
        _print_line(f"[info_dim]  {k:<17}[/info_dim]{_escape(str(v))}")


def _slash_bucle(arg: str = "") -> None:
    """`/bucle`: puerta de la higiene del lazo (repeticion + timeout).

    Sin args muestra el ESTADO de los dos subsistemas. Subcomandos (persisten
    via _save_config y actualizan el env de la sesion, marcado como sembrado):
      on|off              -> clave 'repeticion' (COGNIA_REPETICION)
      umbrales <a,b,c>    -> clave 'repeticion_umbrales' (validados)
      fichero <n>         -> clave 'repeticion_umbral_fichero' (>= 2; nudge
                             a la n-esima edicion del MISMO fichero, pedido
                             por el bucle nativo a ContadorFichero)
      timeout <s>         -> clave 'tool_timeout_s' (0 = sin limite)
      razonamiento on|off       -> clave 'razonamiento' (COGNIA_RAZONAMIENTO)
      razonamiento umbral <n>   -> clave 'razonamiento_umbral' (chars de
                                   razonamiento que hacen "pesado" un paso)
      razonamiento racha <n>    -> clave 'razonamiento_racha' (pasos pesados
                                   seguidos SIN AVANCE antes de apagar el
                                   pensamiento extendido)"""
    try:
        from cognia.harness import repeticion as _rep
        from cognia.harness import timeout_tool as _tt
    except Exception as exc:
        _aviso_degradado("repeticion", f"modulo no importable: {exc}")
        return
    try:
        from cognia.harness import razonamiento as _raz
    except Exception as exc:
        _raz = None
        _aviso_degradado("razonamiento", f"modulo no importable: {exc}")
    arg = (arg or "").strip()
    bajo = arg.lower()
    if bajo in ("on", "off"):
        cfg = _load_config()
        cfg["repeticion"] = bajo
        _save_config(cfg)
        os.environ[_rep.ENV_ACTIVO] = "1" if bajo == "on" else "0"
        _marcar_env_sembrada(_rep.ENV_ACTIVO)
        _rep._AVISADO[0] = False
        _print_line(f"[info_dim]recordatorio de repeticion: {bajo} "
                    f"(guardado)[/info_dim]")
        return
    if bajo.startswith("umbrales"):
        crudo = arg[len("umbrales"):].strip()
        try:
            lista = _rep.parsear_umbrales(crudo)
            if not crudo:
                raise _rep.ConfigInvalida("faltan los umbrales")
        except _rep.ConfigInvalida as exc:
            _print_line(f"[warn_cl]Uso: /bucle umbrales <a,b,c> (enteros >= 2, "
                        f"crecientes; p.ej. 3,5,8) -- {exc}[/warn_cl]")
            return
        texto = ",".join(str(v) for v in lista)
        cfg = _load_config()
        cfg["repeticion_umbrales"] = texto
        _save_config(cfg)
        os.environ[_rep.ENV_UMBRALES] = texto
        _marcar_env_sembrada(_rep.ENV_UMBRALES)
        _rep._AVISADO[0] = False
        _print_line(f"[info_dim]repeticion: umbrales {texto} (guardado; suave "
                    f"al {lista[0]}, detallado en {lista[1:] or 'ninguno mas'})"
                    f"[/info_dim]")
        return
    if bajo.startswith("fichero"):
        crudo = arg[len("fichero"):].strip()
        try:
            n = _rep.parsear_umbral_fichero(crudo)
            if not crudo:
                raise _rep.ConfigInvalida("falta el umbral")
        except _rep.ConfigInvalida as exc:
            _print_line(f"[warn_cl]Uso: /bucle fichero <n> (entero >= 2; "
                        f"ediciones al mismo fichero antes del nudge) -- "
                        f"{exc}[/warn_cl]")
            return
        cfg = _load_config()
        cfg["repeticion_umbral_fichero"] = str(n)
        _save_config(cfg)
        os.environ[_rep.ENV_UMBRAL_FICHERO] = str(n)
        _marcar_env_sembrada(_rep.ENV_UMBRAL_FICHERO)
        _rep._AVISADO[0] = False
        _print_line(f"[info_dim]bucle por fichero: nudge a las {n} ediciones "
                    f"del mismo fichero (guardado)[/info_dim]")
        return
    if bajo.startswith("razonamiento"):
        if _raz is None:
            _print_line("[warn_cl]el vigilante de razonamiento no esta "
                        "disponible en esta instalacion[/warn_cl]")
            return
        resto = arg[len("razonamiento"):].strip()
        sub = resto.lower()
        if sub in ("on", "off"):
            cfg = _load_config()
            cfg["razonamiento"] = sub
            _save_config(cfg)
            os.environ[_raz.ENV_ACTIVO] = "1" if sub == "on" else "0"
            _marcar_env_sembrada(_raz.ENV_ACTIVO)
            _print_line(f"[info_dim]recordatorio de razonamiento en bucle: "
                        f"{sub} (guardado)[/info_dim]")
            return
        for clave, env, minimo, que in (
                ("umbral", _raz.ENV_UMBRAL, 200,
                 "caracteres de razonamiento que hacen PESADO un paso"),
                ("racha", _raz.ENV_RACHA, 2,
                 "pasos pesados seguidos SIN AVANCE antes de apagar el "
                 "pensamiento")):
            if not sub.startswith(clave):
                continue
            try:
                n = _raz.parsear_entero(resto[len(clave):], minimo)
            except _raz.ConfigInvalida as exc:
                _print_line(f"[warn_cl]Uso: /bucle razonamiento {clave} <n> "
                            f"(entero >= {minimo}; {que}) -- {exc}[/warn_cl]")
                return
            cfg = _load_config()
            cfg[f"razonamiento_{clave}"] = str(n)
            _save_config(cfg)
            os.environ[env] = str(n)
            _marcar_env_sembrada(env)
            _print_line(f"[info_dim]razonamiento: {clave} = {n} "
                        f"({que}; guardado)[/info_dim]")
            return
        if resto:
            _print_line("[warn_cl]Uso: /bucle razonamiento \\[on | off | "
                        "umbral <n> | racha <n>][/warn_cl]")
            return
        # `/bucle razonamiento` a secas: solo la foto de este subsistema.
        _print_line("\n".join(_estado_razonamiento(_raz)))
        return
    if bajo.startswith("timeout"):
        crudo = arg[len("timeout"):].strip()
        try:
            n = int(crudo)
            if n < 0:
                raise ValueError(n)
        except ValueError:
            _print_line("[warn_cl]Uso: /bucle timeout <segundos> (entero >= 0; "
                        "0 = sin limite)[/warn_cl]")
            return
        cfg = _load_config()
        cfg["tool_timeout_s"] = str(n)
        _save_config(cfg)
        os.environ[_tt.ENV_TIMEOUT] = str(n)
        _marcar_env_sembrada(_tt.ENV_TIMEOUT)
        _print_line(f"[info_dim]timeout por tool: "
                    f"{'sin limite' if n == 0 else f'{n}s'} (guardado; "
                    f"ejecutar/tests conservan su timeout interno si es mayor)"
                    f"[/info_dim]")
        return
    if arg and bajo != "estado":
        _print_line("[warn_cl]Uso: /bucle \\[estado | on | off | umbrales <a,b,c> "
                    "| fichero <n> | timeout <s> | razonamiento ...][/warn_cl]")
        return
    # Estado (default): la foto de los dos subsistemas.
    er = _rep.estado()
    et = _tt.estado()

    def _fuente(var, clave):
        env = (os.environ.get(var) or "").strip()
        return (f"env {var}={env}" if env and not _env_es_sembrada(var)
                else f"config '{clave}'")

    ult = er["ultimo"]
    ult_f = er.get("ultimo_fichero") or {}
    filas_r = [
        ("umbrales", f"{','.join(str(v) for v in er['umbrales'])} (suave al "
                     f"{er['umbrales'][0]}, detallado despues; "
                     f"{_fuente(_rep.ENV_UMBRALES, 'repeticion_umbrales')})"),
        # ContadorFichero (deepagents 0.7.8): ediciones al MISMO fichero
        ("por fichero", f"nudge a las {er['umbral_fichero']} ediciones del "
                        f"mismo fichero ({_fuente(_rep.ENV_UMBRAL_FICHERO, 'repeticion_umbral_fichero')}); "
                        f"{er.get('umbral_apendice', er['umbral_fichero'])} "
                        f"si son apendices (construir por partes no es "
                        f"reeditar); {er['total_fichero']} en este proceso"
                        + (f"; ultimo: {ult_f.get('ruta')} x{ult_f.get('n')} "
                           f"({ult_f.get('tool')})" if ult_f else "")),
        ("transparentes", ", ".join(er["exentas"]) or "ninguna"),
        ("recordatorios", (f"{er['total']} en este proceso; ultimo: "
                           f"{ult.get('tool')} x{ult.get('n')} "
                           f"({ult.get('tipo')}, {ult.get('ts')})") if ult
                          else "0 en este proceso"),
    ]
    avisos_r = []
    if er["config_error"]:
        avisos_r.append(f"config invalida (guard apagado): {er['config_error']}")
    if er["ultimo_error"]:
        avisos_r.append(f"ultimo error: {er['ultimo_error'].get('motivo', '')} "
                        f"({er['ultimo_error'].get('ts', '')})")
    _print_line("\n".join(_estado_subsistema(
        "recordatorio de repeticion", bool(er["activo"]), filas_r,
        fuente=_fuente(_rep.ENV_ACTIVO, "repeticion"), avisos=avisos_r)))
    tmo = et["timeout_s"]
    ult = et["ultimo"]
    filas_t = [
        ("gracia", f"{et['gracia_s']}s"),
        ("ejecutar/tests", "su timeout interno manda si es mayor"),
        ("sin deadline", f"{len(et['sin_deadline'])} tools que llaman al modelo"),
        ("timeouts", (f"{et['total']} en este proceso; ultimo: {ult.get('tool')} "
                      f"tras {ult.get('limite_s')}s "
                      f"({'quiescente' if ult.get('quiescente') else 'NO quiescio'}, "
                      f"{ult.get('ts')})") if ult else "0 en este proceso"),
    ]
    avisos_t = []
    if et["config_error"]:
        avisos_t.append(f"config invalida (sin deadline): {et['config_error']}")
    if et["ultimo_error"]:
        avisos_t.append(f"ultimo error: {et['ultimo_error'].get('motivo', '')} "
                        f"({et['ultimo_error'].get('ts', '')})")
    _print_line("\n".join(_estado_subsistema(
        "timeout por tool", "sin limite" if tmo == 0 else f"{tmo}s", filas_t,
        fuente=_fuente(_tt.ENV_TIMEOUT, "tool_timeout_s"), avisos=avisos_t)))
    # El TERCER detector de bucle, el que mira el canal que los otros dos no
    # miran: el razonamiento. Ver harness/razonamiento.py.
    if _raz is not None:
        _print_line("\n".join(_estado_razonamiento(_raz)))


def _estado_razonamiento(_raz) -> list:
    """Las lineas de estado del vigilante de razonamiento en bucle.

    Aparte de `_slash_bucle` porque tambien la usa `/bucle razonamiento` a
    secas, que es la puerta de diagnostico del subsistema.
    """
    er = _raz.estado()
    ult = er.get("ultimo") or {}

    def _fuente(var, clave):
        env = (os.environ.get(var) or "").strip()
        return (f"env {var}={env}" if env and not _env_es_sembrada(var)
                else f"config '{clave}'")

    filas = [
        ("paso pesado", f"{er['umbral']} chars de razonamiento "
                        f"({_fuente(_raz.ENV_UMBRAL, 'razonamiento_umbral')})"),
        ("racha dura", f"{er['racha']} pasos pesados seguidos SIN AVANCE "
                       f"verificado -> se apaga el pensamiento extendido "
                       f"({_fuente(_raz.ENV_RACHA, 'razonamiento_racha')})"),
        ("aviso en vivo", ", ".join(f"{h:,}".replace(",", ".")
                                    for h in er["hitos"]) + " chars"),
        ("se repite si", f"solapamiento >= {er['umbral_repeticion']} con el "
                         "razonamiento del paso anterior"),
        ("recordatorios", (f"{er['total']} en este proceso; ultimo: "
                           f"{_num_seguro(ult.get('chars'))} chars, racha "
                           f"{ult.get('racha')} ({ult.get('ts')})")
                          if ult else "0 en este proceso"),
        ("pensamiento apagado", f"{er['apagados']} vez/veces en este proceso"),
    ]
    return _estado_subsistema(
        "razonamiento en bucle", bool(er["activo"]), filas,
        fuente=_fuente(_raz.ENV_ACTIVO, "razonamiento"))


def _num_seguro(n) -> str:
    try:
        return f"{int(n):,}".replace(",", ".")
    except (TypeError, ValueError):
        return "?"


def _slash_entrega(arg: str = "") -> None:
    """`/entrega`: que dejo el agente EN DISCO en su ultima tarea.

    Sin args (o `estado`) imprime la foto del ultimo cierre; `on`/`off`
    persisten la clave 'entrega' y propagan COGNIA_ENTREGA a la sesion.
    """
    try:
        from cognia.harness import entrega as _ent
    except Exception as exc:
        _aviso_degradado("entrega", f"modulo no importable: {exc}")
        return
    bajo = (arg or "").strip().lower()
    if bajo in ("on", "off"):
        cfg = _load_config()
        cfg["entrega"] = bajo
        _save_config(cfg)
        os.environ[_ent.ENV_ACTIVO] = "1" if bajo == "on" else "0"
        _marcar_env_sembrada(_ent.ENV_ACTIVO)
        _print_line(f"[info_dim]bloque de entrega: {bajo} (guardado)[/info_dim]")
        return
    if bajo and bajo != "estado":
        _print_line("[warn_cl]Uso: /entrega \\[estado | on | off][/warn_cl]")
        return
    e = _ent.estado()
    env = (os.environ.get(_ent.ENV_ACTIVO) or "").strip()
    fuente = (f"env {_ent.ENV_ACTIVO}={env}"
              if env and not _env_es_sembrada(_ent.ENV_ACTIVO)
              else "config 'entrega'")
    filas = [
        ("entregas", f"{e['total']} en este proceso"),
        ("ultima", (f"{e['ficheros']} fichero(s): {e['enteros']} entero(s), "
                    f"{e['rotos']} roto(s) ({e['ts']})")
                   if e["ficheros"] or e["ts"] else "ninguna todavia"),
    ]
    _err = e.get("ultimo_error") or {}
    _avisos = ([f"ultimo error: {_err.get('motivo', '')} ({_err.get('ts', '')})"]
               if _err else [])
    _print_line("\n".join(_estado_subsistema(
        "entrega", bool(e["activo"]), filas, fuente=fuente, avisos=_avisos)))
    ult = _ent.ultimo()
    if ult:
        # El bloque TAL CUAL lo vio el dueno al cerrar la tarea: repetirlo aca
        # es el punto de la puerta (volver a mirar la entrega sin rebuscar en
        # el scrollback).
        _print_line(_escape(_ent.bloque(ult)))


def _aplicar_config_entrega() -> None:
    """Propaga la config del bloque de entrega al entorno (F6: sin pisar lo
    del usuario y marcando la siembra). Una config que no sea on/off grita."""
    try:
        from cognia.harness import entrega as _ent
        cfg = _load_config()
    except Exception as exc:
        _aviso_degradado("entrega", f"config no aplicada: {exc}")
        return
    act = str(cfg.get("entrega", "on")).strip().lower()
    if act not in ("on", "off"):
        _aviso_degradado("entrega", f"config 'entrega'={act!r} no es on/off; "
                         f"uso on")
        act = "on"
    if not (os.environ.get(_ent.ENV_ACTIVO) or "").strip():
        os.environ[_ent.ENV_ACTIVO] = "1" if act == "on" else "0"
        _marcar_env_sembrada(_ent.ENV_ACTIVO)


def _aplicar_config_notificaciones() -> None:
    """Registra el avisador del subsistema de notificaciones (F5): un fallo
    emitiendo el toast se VE como degradado en el REPL (una vez por sesion,
    el propio modulo de-duplica). No hay env que propagar: harness/
    notificaciones lee la config a call-time via sys.modules['cognia.cli']."""
    try:
        from cognia.harness import notificaciones as _notif
        _notif.registrar_avisador(_aviso_degradado)
    except Exception as exc:
        _aviso_degradado("notificaciones", f"config no aplicada: {exc}")


def _notificar_mensaje(mensaje: str) -> None:
    """`/notificar <mensaje>`: la feature VIEJA (popup de escritorio con el
    texto). Vivia como elif propio en el repl y la puerta F5 la tapaba en
    silencio — mismo bug ya pagado con /flujo y /vigilar (revision adversarial
    2026-08-23). Hoy _slash_notificar cae aca con cualquier texto que no sea
    un subcomando de F5."""
    try:
        if sys.platform == "win32":
            import subprocess as _sp3
            seguro = mensaje.replace("'", "''")   # comilla simple de PS
            _ps_notif = (
                f"Add-Type -AssemblyName System.Windows.Forms; "
                f"[System.Windows.Forms.MessageBox]::Show('{seguro}', 'Cognia')"
            )
            _sp3.Popen(
                ["powershell.exe", "-WindowStyle", "Hidden", "-Command", _ps_notif],
                creationflags=0x08000000,  # CREATE_NO_WINDOW
            )
        else:
            import subprocess as _sp3
            _sp3.Popen(["notify-send", "Cognia", mensaje])
        _print_line(f"[ok_cl]Notificacion enviada: {_escape(mensaje)}[/ok_cl]")
    except Exception as _e:
        _print_line(f"[err_cl]notificar error: {_e}[/err_cl]")


def _slash_notificar(arg: str = "") -> None:
    """`/notificar`: puerta de las notificaciones de escritorio OSC 9 (F5).

    Sin args muestra el ESTADO: modo efectivo (y su fuente), umbral del turno
    largo, opt-in de degradados, si hay consola interactiva, eventos
    registrados y la ultima notificacion / ultimo error.
    Subcomandos (persisten via _save_config):
      on|off              -> clave 'notificar' (COGNIA_NOTIFY gana a la config)
      prueba              -> emite una notificacion DE VERDAD a la consola real
      modo <auto|osc|bell|toast> -> clave 'notificar_modo' (auto: BEL bajo
                             Windows Terminal — el OSC 9 plano es un no-op
                             ahi, issue #8592 — y OSC 9 en el resto; toast:
                             notificacion nativa del SO)
      umbral <segundos>   -> clave 'notificar_umbral_s' (>= 1)
      degradados on|off   -> clave 'notificar_degradado' (toast al degradarse)
    Cualquier otro texto es el uso VIEJO: '/notificar <mensaje>' manda un
    popup de escritorio con el mensaje (_notificar_mensaje)."""
    try:
        from cognia.harness import notificaciones as _notif
    except Exception as exc:
        _aviso_degradado("notificaciones", f"modulo no importable: {exc}")
        return
    arg = (arg or "").strip()
    bajo = arg.lower()
    if bajo in ("on", "off"):
        cfg = _load_config()
        cfg["notificar"] = bajo
        _save_config(cfg)
        _print_line(f"[info_dim]notificaciones de escritorio: {bajo} "
                    "(guardado; la env COGNIA_NOTIFY gana si esta puesta)"
                    "[/info_dim]")
        return
    if bajo == "prueba":
        # Prueba REAL con el modo EFECTIVO resuelto como en produccion:
        # auto -> bell bajo Windows Terminal (el OSC 9 plano es un NO-OP ahi,
        # issue microsoft/terminal#8592 abierto: WT interpreta 9;x como
        # ConEmu) u osc en el resto; osc/bell/toast se prueban tal cual.
        modo = _notif.modo_activo()
        if modo == "off":
            _print_line("[warn_cl]notificaciones apagadas (modo off): "
                        "/notificar on o quitar COGNIA_NOTIFY=off[/warn_cl]")
            return
        modo_ef = modo
        if modo == "auto":
            modo_ef = "bell" if _notif.en_wt() else "osc"
        # Los bytes se muestran SIEMPRE (aunque el gate de tty no deje
        # emitirlos, p.ej. bajo un pipe): la prueba tambien es documentacion
        # de que hace exactamente el modo efectivo.
        if modo_ef == "toast":
            _print_line("[info_dim]  modo efectivo toast: notificacion nativa "
                        "del SO (plyer o PowerShell NotifyIcon), sin bytes "
                        "al terminal[/info_dim]")
        else:
            seq = (_notif.secuencia_osc9("Cognia", "notificacion de prueba")
                   if modo_ef == "osc" else "\a")
            _print_line(f"[info_dim]  modo efectivo {modo_ef}: bytes "
                        f"{_escape(repr(seq))}[/info_dim]")
        if modo_ef == "osc" and _notif.en_wt():
            _print_line("[warn_cl]  OJO: Windows Terminal NO pinta el "
                        "OSC 9 plano (#8592): usa /notificar modo toast, "
                        "o deja auto (BEL + anillo 9;4)[/warn_cl]")
        if _notif.en_wt():
            _print_line(f"[info_dim]  anillo 9;4 de WT — inicio: "
                        f"{_escape(repr(_notif.secuencia_progreso(3)))} | "
                        f"fin ok: {_escape(repr(_notif.secuencia_progreso(0)))} | "
                        f"error: {_escape(repr(_notif.secuencia_progreso(2, 100)))}"
                        f"[/info_dim]")
        emitido = _notif.notificar("Cognia", "notificacion de prueba",
                                   modo=modo_ef)
        if emitido:
            _print_line(f"[ok_cl]notificacion emitida (modo {modo_ef})"
                        f"[/ok_cl]")
        else:
            est_p = _notif.estado()
            err = est_p["ultimo_error"]
            motivo = ""
            if err:
                motivo = ": " + err.get("motivo", "")
            elif not est_p["consola_interactiva"]:
                # No es un fallo: es el gate anti-escape trabajando (un
                # pipe/CI jamas recibe bytes de escape; revision 2026-08-23).
                motivo = (": el fd real no es un terminal (pipe/CI) y el "
                          "gate anti-escape no emite ahi")
            elif est_p["en_fondo"]:
                motivo = ": subagente (jamas notifica)"
            _print_line(f"[warn_cl]no se pudo emitir{motivo}[/warn_cl]")
        return
    if bajo.startswith("modo"):
        v = arg[len("modo"):].strip().lower()
        if v not in ("auto", "osc", "bell", "toast"):
            _print_line("[warn_cl]Uso: /notificar modo <auto|osc|bell|toast> "
                        "(off es /notificar off)[/warn_cl]")
            return
        cfg = _load_config()
        cfg["notificar_modo"] = v
        _save_config(cfg)
        _print_line(f"[info_dim]notificaciones: modo {v} (guardado)[/info_dim]")
        if v == "osc":
            from cognia.harness import notificaciones as _n2
            if _n2.en_wt():
                _print_line("[warn_cl]  OJO: estas bajo Windows Terminal y "
                            "WT NO pinta el OSC 9 plano (#8592) — este modo "
                            "es para WezTerm/ConEmu; aqui conviene auto o "
                            "toast[/warn_cl]")
        return
    if bajo.startswith("umbral"):
        try:
            s = float(arg[len("umbral"):].strip())
            if s < 1:
                raise ValueError(s)
        except ValueError:
            _print_line("[warn_cl]Uso: /notificar umbral <segundos> (>= 1)"
                        "[/warn_cl]")
            return
        cfg = _load_config()
        cfg["notificar_umbral_s"] = str(s)
        _save_config(cfg)
        _print_line(f"[info_dim]notificaciones: umbral {s:g}s de turno "
                    "(guardado)[/info_dim]")
        return
    if bajo.startswith("degradados"):
        v = arg[len("degradados"):].strip().lower()
        if v not in ("on", "off"):
            _print_line("[warn_cl]Uso: /notificar degradados on|off[/warn_cl]")
            return
        cfg = _load_config()
        cfg["notificar_degradado"] = v
        _save_config(cfg)
        _print_line(f"[info_dim]notificaciones: toast al degradarse {v} "
                    "(guardado)[/info_dim]")
        return
    if arg and bajo != "estado":
        # No es ningun subcomando de F5: es el uso VIEJO documentado
        # ('/notificar termino el build' -> popup de escritorio).
        _notificar_mensaje(arg)
        return
    # Estado (default): la foto entera del subsistema.
    est = _notif.estado()
    ult = est["ultima"]
    filas = [
        ("umbral", f"{est['umbral_s']:g}s de turno largo"),
        ("toast al degradarse", "on" if est["degradado_optin"] else "off"),
        ("consola interactiva", "si" if est["consola_interactiva"] else "no"),
        ("Windows Terminal",
         ("si — el OSC 9 plano NO esta soportado (#8592, modo osc seria un "
          "no-op aqui); anillo 9;4 en pestana/taskbar activo"
          + (" | error ROJO pendiente de limpiar"
             if est.get("error_pendiente") else ""))
         if est.get("wt") else
         "no (sin WT_SESSION) — el anillo 9;4 no se emite y el modo auto usa "
         "OSC 9 plano"),
        ("eventos", ", ".join(est["eventos"]) or "ninguno"),
        ("ultima", (f"«{ult.get('titulo', '')}: {ult.get('cuerpo', '')}» "
                    f"(modo {ult.get('modo', '?')}, {ult.get('ts', '')})") if ult
                   else "ninguna en este proceso"),
    ]
    err = est["ultimo_error"]
    avisos = ([f"ultimo error: {err.get('motivo', '')} ({err.get('ts', '')})"]
              if err else [])
    if not err:
        filas.append(("ultimo error", "ninguno"))
    _print_line("\n".join(_estado_subsistema(
        "notificaciones de escritorio", str(est["modo"]), filas,
        fuente=str(est.get("fuente") or ""), avisos=avisos)))


def _slash_telemetria(arg: str = "") -> None:
    """`/telemetria [estado | on | off | ultimo | ruta]`: el diario objetivo del turno.

    QUE ES. Con la telemetria encendida, cada tarea deja un JSONL con lo que el
    bucle YA sabe y hasta hoy tiraba: tokens de entrada y de salida por paso,
    finish_reason, cada tool call con su exit y su duracion, compactaciones,
    cortes y el motivo de cierre. Es lo que hace falta para responder "por que
    fallo esta tarea" sin leer prosa coloreada de stderr.

    on|off persisten en la config ('telemetria'); COGNIA_TELEMETRIA con una ruta
    gana a la config y manda el diario a ese fichero (es lo que usan los bancos).
    """
    try:
        from cognia.harness import telemetria as _tel
    except Exception as exc:
        _aviso_degradado("telemetria", f"modulo no importable: {exc}")
        _print_line(f"[warn_cl]telemetria no disponible: {exc}[/warn_cl]")
        return

    arg = (arg or "").strip().lower()
    cfg = _load_config()

    def _ruta_sesion():
        base = Path.home() / ".cognia" / "telemetria"
        base.mkdir(parents=True, exist_ok=True)
        return base / (time.strftime("%Y%m%d") + ".jsonl")

    if arg in ("on", "1", "si"):
        cfg["telemetria"] = "on"
        _save_config(cfg)
        os.environ[_tel.ENV] = str(_ruta_sesion())
        _print_line(f"[ok_cl]telemetria ON -> {os.environ[_tel.ENV]}[/ok_cl]")
        return
    if arg in ("off", "0", "no"):
        cfg["telemetria"] = "off"
        _save_config(cfg)
        os.environ.pop(_tel.ENV, None)
        _print_line("[ok_cl]telemetria OFF[/ok_cl]")
        return
    if arg == "ruta":
        _print_line(_tel.ruta() or "(apagada)")
        return
    if arg in ("", "estado"):
        activa = _tel.activa()
        _print_line(f"telemetria: {'ON' if activa else 'OFF'}"
               f"   config={cfg.get('telemetria', 'off')}")
        _print_line(f"  diario: {_tel.ruta() or '(sin fichero)'}")
        _print_line("  /debug telemetria on       enciende y fija el diario del dia")
        _print_line("  /debug telemetria ultimo   resumen del diario actual")
        return
    if arg == "ultimo":
        ruta = _tel.ruta()
        if not ruta or not Path(ruta).exists():
            _print_line("[warn_cl]no hay diario: enciendelo con /telemetria on[/warn_cl]")
            return
        try:
            r = _tel.resumir(ruta)
        except Exception as exc:
            _aviso_degradado("telemetria", f"resumir fallo: {exc}")
            _print_line(f"[warn_cl]no pude resumir el diario: {exc}[/warn_cl]")
            return
        _print_line(f"[bold]diario:[/bold] {ruta}")
        _print_line(f"  turnos {r.get('turnos')}   tool calls {r.get('tool_calls')}"
               f" ({r.get('tool_calls_fallidas')} fallidas)")
        _print_line(f"  tokens  entrada {r.get('tokens_entrada')}"
               f"  salida {r.get('tokens_salida')}"
               f"  ({r.get('tok_s_salida')} tok/s de salida)")
        _print_line(f"  prompt maximo {r.get('prompt_tokens_max')} tokens"
               f"   duracion {r.get('duracion_s')}s")
        _print_line(f"  cortados por el tope: {r.get('turnos_cortados_por_tope')}"
               f"   compactaciones: {r.get('n_compactaciones')}")
        if r.get("cierre_razon"):
            _print_line(f"  cierre: {r.get('cierre_razon')} (ok={r.get('cierre_ok')},"
                   f" pasos={r.get('cierre_pasos')})")
        por_nombre = r.get("tool_calls_por_nombre") or {}
        if por_nombre:
            top = sorted(por_nombre.items(), key=lambda kv: -kv[1])[:6]
            _print_line("  tools: " + ", ".join(f"{k}x{v}" for k, v in top))
        for inc in (r.get("incidencias") or [])[:5]:
            _print_line(f"  [warn_cl]{inc.get('tipo')}[/warn_cl] t={inc.get('t')}s"
                   f" {str(inc.get('detalle'))[:90]}")
        return
    _print_line("[warn_cl]uso: /debug telemetria [estado | on | off | ultimo | ruta]"
                "[/warn_cl]")


def _slash_spinner(arg: str = "") -> None:
    """`/spinner [estado | on | off | verbos ...]`: la linea de estado VIVA
    del turno (F2, ux/spinner_vivo + ticker del renderer): verbo gato
    rotatorio + segundos + ~tokens del stream + 'ctrl+c corta'.

    Subcomandos de config (persisten via _save_config):
      on|off           -> clave 'spinner_info' (off = spinner clasico
                          'pensando… (Ns)'; COGNIA_SPINNER_INFO gana a la config)
      verbos           -> lista vigente
      verbos <a, b>    -> clave 'spinner_verbos' (separados por comas)
      verbos reset     -> vuelve a los VERBOS_GATO del modulo"""
    try:
        from cognia.ux import spinner_vivo
    except Exception as exc:
        _aviso_degradado("spinner", f"spinner_vivo no importable: {exc}")
        return
    arg = (arg or "").strip()
    bajo = arg.lower()
    if bajo in ("on", "off"):
        cfg = _load_config()
        cfg["spinner_info"] = bajo
        _save_config(cfg)
        env = (os.environ.get("COGNIA_SPINNER_INFO") or "").strip()
        extra = (f" (ojo: COGNIA_SPINNER_INFO={env} en el entorno GANA "
                 f"a la config)" if env else "")
        _print_line(f"[info_dim]linea de estado viva: {bajo}"
                    f" (guardado){extra}[/info_dim]")
        return
    if bajo == "verbos" or bajo.startswith("verbos "):
        resto = arg[len("verbos"):].strip()
        if not resto:
            _, verbos = spinner_vivo.config()
            propios = bool(str(_load_config().get("spinner_verbos", "")).strip())
            origen = "propios (config)" if propios else "default (verbos gato)"
            _print_line(f"[info_dim]{len(verbos)} verbos — {origen}:[/info_dim]")
            for v in verbos:
                _print_line(f"[info_dim]  · {_escape(v)}[/info_dim]")
            return
        if resto.lower() == "reset":
            cfg = _load_config()
            cfg["spinner_verbos"] = ""
            _save_config(cfg)
            _print_line(f"[info_dim]verbos: de vuelta a los "
                        f"{len(spinner_vivo.VERBOS_GATO)} verbos gato "
                        f"(guardado)[/info_dim]")
            return
        nuevos = spinner_vivo.verbos_config(resto)
        if nuevos == list(spinner_vivo.VERBOS_GATO):
            # verbos_config cae al default cuando la lista quedo vacia tras
            # sanear: eso aqui es un error de uso, no una config valida
            _print_line("[warn_cl]Uso: /spinner verbos <v1, v2, ...> "
                        "(separados por comas; sin corchetes)[/warn_cl]")
            return
        cfg = _load_config()
        cfg["spinner_verbos"] = nuevos
        _save_config(cfg)
        _print_line(f"[info_dim]{len(nuevos)} verbos propios guardados "
                    f"(ej: {_escape(nuevos[0])}…)[/info_dim]")
        return
    if bajo not in ("", "estado"):
        _print_line("[warn_cl]Uso: /spinner [estado | on | off | verbos "
                    "[<v1, v2, ...> | reset]][/warn_cl]")
        return
    # estado: modo actual, verbo de ejemplo, linea de muestra y env vars
    activo, verbos = spinner_vivo.config()
    spinner_env = (os.environ.get("COGNIA_SPINNER") or "").strip()
    info_env = (os.environ.get("COGNIA_SPINNER_INFO") or "").strip()
    if spinner_env == "0":
        modo, detalle = "off", "COGNIA_SPINNER=0: ni viva ni clasica"
        fuente = "env COGNIA_SPINNER=0"
    elif activo:
        modo, detalle = "viva", "verbo + segundos + ~tokens + ctrl+c corta"
        fuente = (f"env COGNIA_SPINNER_INFO={info_env}" if info_env
                  else "config spinner_info")
    else:
        modo, detalle = "clasica", "'pensando… (Ns)'; /spinner on para la viva"
        fuente = (f"env COGNIA_SPINNER_INFO={info_env}" if info_env
                  else "config spinner_info")
    ejemplo = spinner_vivo.componer_linea(
        spinner_vivo.verbo_rotante(time.time(), time.time(), verbos),
        segundos=7, tokens=340)
    propios = bool(str(_load_config().get("spinner_verbos", "")).strip())
    _print_line("\n".join(_estado_subsistema(
        "linea de estado viva", modo, [
            ("modo", detalle),
            ("ejemplo", f"· {ejemplo}"),
            ("verbos", f"{len(verbos)} ({'propios' if propios else 'default gato'}; "
                       f"/spinner verbos para verlos)"),
        ], fuente=fuente)))


def _slash_markdown(arg: str = "") -> None:
    """`/markdown [estado | on | off | tema <pygments>]`: markdown en
    STREAMING sin flicker para la respuesta (ux/markdown_vivo: la maquina de
    Aider — ventana viva + commit de estables — con el reloj de CodeWhale).

    Subcomandos de config (persisten via _save_config):
      on|off         -> clave 'markdown_stream' (COGNIA_MARKDOWN gana:
                        0 apaga, 1 fuerza aun sin tty)
      tema <nombre>  -> clave 'markdown_tema' (tema pygments de los bloques
                        de codigo, default 'monokai'; COGNIA_CODE_THEME gana)"""
    try:
        from cognia.ux import markdown_vivo
    except Exception as exc:
        _aviso_degradado("markdown", f"markdown_vivo no importable: {exc}")
        return
    arg = (arg or "").strip()
    bajo = arg.lower()
    if bajo in ("on", "off"):
        cfg = _load_config()
        cfg["markdown_stream"] = bajo
        _save_config(cfg)
        env = (os.environ.get("COGNIA_MARKDOWN") or "").strip()
        extra = (f" (ojo: COGNIA_MARKDOWN={env} en el entorno GANA "
                 f"a la config)" if env else "")
        _print_line(f"[info_dim]markdown en streaming: {bajo}"
                    f" (guardado){extra}[/info_dim]")
        return
    if bajo == "tema" or bajo.startswith("tema "):
        resto = arg[len("tema"):].strip()
        if not resto:
            _, tema = markdown_vivo.config()
            _print_line(f"[info_dim]tema de codigo: {_escape(tema)} "
                        f"(/markdown tema <nombre pygments> para cambiarlo)"
                        f"[/info_dim]")
            return
        try:
            from pygments.styles import get_style_by_name
            get_style_by_name(resto)
        except Exception:
            # sugerir algunos reales para no dejar al dueno adivinando
            try:
                from pygments.styles import get_all_styles
                muestra = ", ".join(sorted(get_all_styles())[:12]) + ", …"
            except Exception:
                muestra = "monokai, dracula, github-dark, solarized-dark, …"
            _print_line(f"[warn_cl]tema '{_escape(resto)}' no existe en "
                        f"pygments. Algunos: {muestra}[/warn_cl]")
            return
        cfg = _load_config()
        cfg["markdown_tema"] = resto
        _save_config(cfg)
        env_t = (os.environ.get("COGNIA_CODE_THEME") or "").strip()
        extra = (f" (ojo: COGNIA_CODE_THEME={env_t} en el entorno GANA "
                 f"a la config)" if env_t else "")
        _print_line(f"[info_dim]tema de codigo: {resto} (guardado){extra}"
                    f"[/info_dim]")
        return
    if bajo not in ("", "estado"):
        _print_line("[warn_cl]Uso: /markdown \\[estado | on | off | "
                    "tema <pygments>][/warn_cl]")
        return
    # estado: activo?, por que, tema vigente y quien manda
    act, tema = markdown_vivo.config()
    md_env = (os.environ.get("COGNIA_MARKDOWN") or "").strip()
    tema_env = (os.environ.get("COGNIA_CODE_THEME") or "").strip()
    remoto = (os.environ.get("COGNIA_REMOTO") or "").strip() == "1"
    try:
        tty = bool(sys.stdout.isatty())
    except Exception:
        tty = False
    if act:
        porque = "ventana viva de 6 lineas + commit de estables"
        fuente = f"env COGNIA_MARKDOWN={md_env}" if md_env else "config markdown_stream"
    elif remoto:
        porque = "COGNIA_REMOTO=1: el clasificador del movil necesita el camino viejo"
        fuente = "env COGNIA_REMOTO=1"
    elif md_env in ("0", "false", "no", "off"):
        porque = "apagado por el entorno"
        fuente = f"env COGNIA_MARKDOWN={md_env}"
    elif str(_load_config().get("markdown_stream", "on")).lower() in (
            "off", "0", "false", "no"):
        porque = "apagado en la config; /markdown on para prenderlo"
        fuente = "config markdown_stream"
    elif not tty:
        porque = ("sin tty: un pipe no tiene cursor; COGNIA_MARKDOWN=1 lo "
                  "fuerza en modo solo-commit")
        fuente = "automatico"
    else:
        porque, fuente = "apagado", ""
    # _load_config ya viene MERGEADO con los defaults: distinguir el default
    # por VALOR, no por presencia (si no, el default salia como "config")
    origen_tema = ("env COGNIA_CODE_THEME" if tema_env
                   else "default" if tema == _CONFIG_DEFAULTS.get(
                       "markdown_tema") else "config")
    filas = [("por que", porque),
             ("tema de codigo", f"{tema} ({origen_tema}; /markdown tema "
                                "<pygments> para cambiarlo)")]
    # La prosa de env vars solo cuando una env esta GANANDO a la config.
    if md_env:
        filas.append(("env", f"COGNIA_MARKDOWN={md_env} gana a la config"))
    if tema_env:
        filas.append(("env", f"COGNIA_CODE_THEME={tema_env} gana al tema"))
    _print_line("\n".join(_estado_subsistema(
        "markdown en streaming", bool(act), filas, fuente=fuente)))


def _slash_prompt(arg: str = ""):
    """Administra el system prompt configurable del CEREBRO (2026-08-02).

    El prompt vive en ~/.cognia/system_prompt.md (texto plano) y, si existe
    con contenido, reemplaza el prompt integrado del rol cerebro. El agente
    NUNCA lo ve (A/B 2026-07-23: texto extra degrada su gate de 10/10 a 3/5).

      /prompt                 -> estado (fuente, ruta, tamano, primeras lineas)
      /prompt editar          -> abrir el archivo en el editor del sistema
      /prompt set <texto>     -> reemplazar el contenido con <texto>
      /prompt reset           -> volver al default del producto
      /prompt off | on        -> apagar/prender sin borrar el archivo (persiste)
    """
    from cognia.system_prompt import (asegurar_prompt_usuario, prompt_usuario,
                                      restaurar_prompt_usuario,
                                      ruta_prompt_usuario)
    partes = (arg or "").strip().split(None, 1)
    sub = partes[0].lower() if partes else ""
    resto = partes[1] if len(partes) > 1 else ""
    ruta = ruta_prompt_usuario()
    try:
        if sub == "editar":
            asegurar_prompt_usuario()
            if sys.platform == "win32":
                os.startfile(str(ruta))            # editor asociado a .md
            else:
                subprocess.Popen([os.environ.get("EDITOR", "nano"), str(ruta)])
            _print_line(f"[ok]Abierto:[/ok] [mod]{_escape(str(ruta))}[/mod]  "
                        "[detail](los cambios aplican en el proximo turno)[/detail]")
        elif sub == "set":
            if not resto.strip():
                _print_line("[warn_cl]Uso: /prompt set <texto del prompt>[/warn_cl]")
                return
            ruta.parent.mkdir(parents=True, exist_ok=True)
            ruta.write_text(resto.strip() + "\n", encoding="utf-8")
            _print_line(f"[ok]Prompt personalizado guardado[/ok] "
                        f"[detail]({len(resto)} caracteres)[/detail]")
        elif sub == "reset":
            restaurar_prompt_usuario()
            _print_line("[ok]Prompt restaurado al default del producto.[/ok]")
        elif sub in ("off", "on"):
            _persist_setting("COGNIA_PROMPT_USUARIO", "0" if sub == "off" else "1")
            _print_line(f"[ok]Prompt personalizado: {sub}[/ok] "
                        "[detail](el archivo no se toca)[/detail]")
        elif sub:
            _print_line("[warn_cl]Uso: /prompt \\[editar | set <texto> | reset | "
                        "off | on][/warn_cl]")
        else:
            # OJO: estado con estilos VISIBLES ([mod]/[info_dim]), no [detail]:
            # el modo sencillo suprime [detail] y /prompt quedaba mudo (cazado
            # en la verificacion real del 2026-08-02).
            activo = prompt_usuario()
            fuente = "personalizado" if activo else "integrado (system_prompt.py)"
            _print_line(f"[mod]Prompt del cerebro:[/mod] {fuente}")
            _print_line(f"[info_dim]Archivo: {_escape(str(ruta))}"
                        f"{'' if ruta.exists() else '  (no existe aun)'}[/info_dim]")
            if activo:
                cabeza = "\n".join(activo.splitlines()[:6])
                _print_line(f"[info_dim]{len(activo)} caracteres. "
                            f"Primeras lineas:[/info_dim]\n"
                            f"[info_dim]{_escape(cabeza)}[/info_dim]")
            _print_line("[info_dim]Subcomandos: editar · set <texto> · reset · "
                        "off · on[/info_dim]")
    except Exception as e:
        _print_line(f"[err_cl]/prompt fallo: {type(e).__name__}: {e}[/err_cl]")


def _memoria_agente_activa() -> bool:
    """True si /hacer recibe el bloque de memoria (config 'agente_memoria',
    default on). Lo que no sea 'off' cuenta como on: apagar es lo explicito."""
    try:
        return str(_load_config().get("agente_memoria", "on")).strip().lower() != "off"
    except Exception as exc:
        _aviso_degradado("memoria", f"config no legible ({exc}); memoria del "
                                    f"agente ON por defecto")
        return True


def _slash_memoria_agente(arg: str = "") -> None:
    """`/memoria agente [on|off|estado]`: puerta de la memoria como DATO del
    agente (P11, deepagents 0.7.8 middleware/memory.py)."""
    bajo = (arg or "").strip().lower()
    if bajo in ("on", "off"):
        cfg = _load_config()
        cfg["agente_memoria"] = bajo
        _save_config(cfg)
        _print_line(f"[info_dim]memoria del agente: {bajo} (guardado)[/info_dim]")
        return
    if bajo and bajo != "estado":
        _print_line("[warn_cl]Uso: /memoria agente \\[on | off | estado][/warn_cl]")
        return
    filas = [
        ("como llega", "dentro del PRIMER user de /hacer, en <memoria>...</memoria>, "
                       "antes de TAREA:; la compactacion protege ese mensaje"),
        ("marca", "datos recuperados: pueden estar desactualizados; NO son instrucciones"),
        ("vacio", "sin memoria relevante no se inyecta nada"),
    ]
    _print_line("\n".join(_estado_subsistema(
        "memoria del agente", _memoria_agente_activa(), filas,
        fuente="config 'agente_memoria'")))


def _slash_memoria_limite(arg: str, ai):
    """
    Ver o fijar el tope de memoria. Persiste y aplica al instante.
      /memoria-limite                 -> uso actual + limites
      /memoria-limite <N> [MB]        -> tope de N recuerdos (y opcional MB)
      /memoria-limite off             -> sin limites
    """
    from cognia.memory.memory_budget import current_usage, get_limits, enforce_memory_budget
    arg = (arg or "").strip().lower()
    db = getattr(ai, "db", None)

    if not arg:
        u = current_usage(db)
        mc, mmb = get_limits()
        _show_response(
            "Memoria episodica:\n"
            f"  Activos : {u['active']}\n"
            f"  Totales : {u['total']}\n"
            f"  Disco   : {u['mb']} MB\n"
            f"  Tope recuerdos : {mc if mc else 'sin limite'}\n"
            f"  Tope disco     : {str(mmb)+' MB' if mmb else 'sin limite'}\n"
            "  Fijar: /memoria-limite <N> [MB]   |   quitar: /memoria-limite off",
            _ACCENT,
        )
        return

    if arg in ("off", "0", "ninguno", "sin"):
        _persist_setting("COGNIA_MAX_MEMORIES", "0")
        _persist_setting("COGNIA_MAX_DB_MB", "0")
        _print_line("[ok_cl]Topes de memoria desactivados.[/ok_cl]")
        return

    parts = arg.split()
    try:
        count = int(float(parts[0]))
        mb = float(parts[1]) if len(parts) > 1 else None
    except Exception:
        _print_line("[warn_cl]Uso: /memoria-limite <N recuerdos> [MB][/warn_cl]")
        return
    _persist_setting("COGNIA_MAX_MEMORIES", str(count))
    if mb is not None:
        _persist_setting("COGNIA_MAX_DB_MB", str(int(mb)))
    _print_line(f"[detail]Aplicando tope ({count} recuerdos"
                + (f", {mb:.0f} MB" if mb else "") + ")...[/detail]")
    rep = enforce_memory_budget(db, max_count=count, max_mb=mb)
    _show_response(
        f"Tope aplicado. Archivados: {rep['soft_deleted']}, borrados: {rep['hard_deleted']}. "
        f"Ahora: {rep['after']['active']} activos, {rep['after']['mb']} MB.",
        _ACCENT,
    )


# ---------------------------------------------------------------------------
# Chat history slash command implementations
# ---------------------------------------------------------------------------

def _fmt_ts(ts) -> str:
    """Format a chat_history timestamp (ISO string) for display, best-effort."""
    if ts is None:
        return "?"
    try:
        return datetime.datetime.fromisoformat(str(ts)).strftime("%Y-%m-%d %H:%M")
    except Exception:
        # Legacy rows may store an epoch int.
        try:
            return datetime.datetime.fromtimestamp(int(ts)).strftime("%Y-%m-%d %H:%M")
        except Exception:
            return str(ts)[:16]


def _slash_sesiones(args: str) -> None:
    """Lista sesiones de chat recientes (id, fecha, directorio)."""
    try:
        from cognia.config import DB_PATH
        from storage.db_pool import db_connect_pooled as _dcp
    except ImportError as _ie:
        _print_line(f"[err_cl]db_pool no disponible: {_ie}[/err_cl]")
        return
    try:
        conn = _dcp(DB_PATH)
        cur = conn.cursor()
        cur.execute(
            "SELECT session_id, cwd, COUNT(*), MAX(timestamp)"
            " FROM chat_history WHERE session_id IS NOT NULL"
            " GROUP BY session_id ORDER BY MAX(id) DESC LIMIT 10"
        )
        rows = cur.fetchall()
        conn.close()
        if not rows:
            _print_line("[detail]Sin sesiones con identificador en el historial. "
                        "(Las sesiones se registran al iniciar el CLI.)[/detail]")
            return
        lines = ["Sesiones recientes (reanuda con /resume <id> o /resume <directorio>):"]
        for sid, cwd, cnt, last_ts in rows:
            sid_short = str(sid)[:8] if sid else "?"
            lines.append(f"  [{sid_short}] {_fmt_ts(last_ts)}  {cnt:>3} msgs  {cwd or '?'}")
        _show_response("\n".join(lines), "listado")
    except Exception as _e:
        _print_line(f"[err_cl]sesiones error: {_e}[/err_cl]")


def _slash_resume(args: str, ai) -> None:
    """
    Reanuda una sesion previa cargando su hilo al contexto.

      /resume                 -> ultima sesion del directorio actual
      /resume list            -> listar sesiones recientes
      /resume <id>            -> sesion por id (o prefijo de 8 chars)
      /resume <directorio>    -> ultima sesion que corrio en ese directorio
    """
    arg = args.strip()
    ch = getattr(ai, "chat_history", None)
    if ch is None:
        _print_line("[err_cl]Historial no disponible.[/err_cl]")
        return

    if arg in ("list", "lista", "-l", "--list", "?"):
        sessions = ch.list_sessions(limit=12)
        if not sessions:
            _print_line("[detail]No hay sesiones registradas todavia. "
                        "(Se registran al iniciar el CLI.)[/detail]")
            return
        lines = ["Sesiones recientes (reanuda con /resume <id> o /resume <directorio>):"]
        for s in sessions:
            sid_short = (s["session_id"] or "?")[:8]
            lines.append(f"  [{sid_short}] {_fmt_ts(s['last_ts'])}  "
                         f"{s['count']:>3} msgs  {s['cwd'] or '?'}")
        _show_response("\n".join(lines), "listado")
        return

    target_sid = None
    scope = ""
    if not arg or arg in ("here", "aqui", "."):
        cwd = _SESSION_CWD or os.path.normpath(os.path.abspath(os.getcwd()))
        target_sid = ch.latest_session_for_dir(cwd)
        scope = f"directorio actual ({cwd})"
    else:
        expanded = os.path.normpath(os.path.abspath(os.path.expanduser(arg)))
        looks_like_path = (
            os.path.isdir(expanded)
            or os.sep in arg
            or (os.altsep and os.altsep in arg)
            or arg.startswith("~")
            or arg.startswith(".")
        )
        if looks_like_path:
            target_sid = ch.latest_session_for_dir(expanded)
            scope = f"directorio {expanded}"
        else:
            target_sid = ch.resolve_session_prefix(arg)
            scope = f"sesion {arg}"
            if target_sid is None:
                alt = ch.latest_session_for_dir(expanded)
                if alt:
                    target_sid, scope = alt, f"directorio {expanded}"

    if not target_sid:
        _print_line(
            f"[warn_cl]No encontre una sesion para {_escape(scope)}. "
            "Proba: /resume list[/warn_cl]"
        )
        return

    if target_sid == _SESSION_ID:
        _print_line("[detail]Esa es la sesion actual; ya estas en ella.[/detail]")
        return

    turns = ch.get_session_turns(target_sid, limit=_HISTORY_SEED_N)
    if not turns:
        _print_line(
            f"[warn_cl]La sesion {target_sid[:8]} no tiene mensajes de dialogo.[/warn_cl]"
        )
        return

    _history[:] = turns
    _print_line(
        f"[ok_cl]Reanudada sesion {target_sid[:8]} ({_escape(scope)}): "
        f"{len(turns)} mensajes cargados al contexto.[/ok_cl]"
    )
    last_user = next((t["content"] for t in reversed(turns) if t["role"] == "user"), "")
    if last_user:
        _print_line(f"[detail]Ultimo tema: {_escape(last_user[:80])}[/detail]")


def _slash_buscar_historial(args: str) -> None:
    """Busca mensajes en el historial por keyword."""
    keyword = args.strip()
    if not keyword:
        _print_line("[warn_cl]Uso: /buscar-historial <keyword>[/warn_cl]")
        return
    try:
        from cognia.config import DB_PATH
        from storage.db_pool import db_connect_pooled as _dcp
    except ImportError as _ie:
        _print_line(f"[err_cl]db_pool no disponible: {_ie}[/err_cl]")
        return
    try:
        conn = _dcp(DB_PATH)
        cur = conn.cursor()
        cur.execute(
            "SELECT session_id, role, content, timestamp FROM chat_history"
            " WHERE content LIKE ? ORDER BY id DESC LIMIT 20",
            (f"%{keyword}%",),
        )
        rows = cur.fetchall()
        conn.close()
        if not rows:
            _print_line(f"[detail](Sin resultados para '{keyword}')[/detail]")
            return
        lines = [f"Resultados para '{keyword}':"]
        for sid, role, content, ts in rows:
            fecha = _fmt_ts(ts)
            sid_short = str(sid)[:8] if sid else "?"
            preview = content[:80].replace("\n", " ")
            lines.append(f"  [{sid_short}] {fecha} ({role}): {preview}")
        _show_response("\n".join(lines), "listado")
    except Exception as _e:
        _print_line(f"[err_cl]buscar-historial error: {_e}[/err_cl]")


def _slash_sesion_ver(args: str) -> None:
    """Muestra los ultimos mensajes de una sesion dado su ID (o primeros 8 chars)."""
    sid_arg = args.strip()
    if not sid_arg:
        _print_line("[warn_cl]Uso: /sesion-ver <session_id>[/warn_cl]")
        return
    try:
        from cognia.config import DB_PATH
        from storage.db_pool import db_connect_pooled as _dcp
    except ImportError as _ie:
        _print_line(f"[err_cl]db_pool no disponible: {_ie}[/err_cl]")
        return
    try:
        conn = _dcp(DB_PATH)
        cur = conn.cursor()
        cur.execute(
            "SELECT role, content, timestamp FROM chat_history"
            " WHERE session_id LIKE ? ORDER BY id LIMIT 20",
            (f"{sid_arg}%",),
        )
        rows = cur.fetchall()
        conn.close()
        if not rows:
            _print_line(f"[detail]Sin mensajes para sesion '{sid_arg}'.[/detail]")
            return
        lines = [f"Sesion {sid_arg[:8]}:"]
        for role, content, _ts in rows:
            label = "User" if role == "user" else "Cognia"
            preview = content[:100].replace("\n", " ")
            lines.append(f"  [{label}]: {preview}")
        _show_response("\n".join(lines), "listado")
    except Exception as _e:
        _print_line(f"[err_cl]sesion-ver error: {_e}[/err_cl]")


def _slash_historial_limpiar(args: str) -> None:
    """Elimina historial de una sesion o todo el historial."""
    arg = args.strip()
    try:
        from cognia.config import DB_PATH
        from storage.db_pool import db_connect_pooled as _dcp
    except ImportError as _ie:
        _print_line(f"[err_cl]db_pool no disponible: {_ie}[/err_cl]")
        return
    if not arg:
        _print_line(
            "[warn_cl]AVISO: esto borrara TODO el historial de chat.\n"
            "Para confirmar: /historial-limpiar confirmar\n"
            "Para borrar una sesion: /historial-limpiar <session_id>[/warn_cl]"
        )
        return
    try:
        conn = _dcp(DB_PATH)
        if arg == "confirmar":
            cur = conn.cursor()
            cur.execute("DELETE FROM chat_history")
            deleted = cur.rowcount
            conn.commit()
            conn.close()
            _print_line(f"[ok]Historial completo eliminado: {deleted} mensajes borrados.[/ok]")
        else:
            cur = conn.cursor()
            cur.execute("DELETE FROM chat_history WHERE session_id = ?", (arg,))
            deleted = cur.rowcount
            conn.commit()
            conn.close()
            if deleted:
                _print_line(f"[ok]Sesion '{arg}': {deleted} mensajes eliminados.[/ok]")
            else:
                _print_line(f"[warn_cl]No se encontro sesion '{arg}' en el historial.[/warn_cl]")
    except Exception as _e:
        _print_line(f"[err_cl]historial-limpiar error: {_e}[/err_cl]")


